def unit_of_work(metadata=None, timeout=None):
    """
    Decorator that injects a dummy transaction object into the wrapped function.
    Validates metadata and timeout arguments and supports usage with or without
    positional/keyword arguments.
    """
    # Handle decorator usage without arguments: @unit_of_work
    if callable(metadata) and timeout is None:
        func = metadata
        metadata = None
        timeout = None
    else:
        func = None

    # Validation helpers
    _validate_metadata = lambda m: (
        isinstance(m, dict) if m is not None else True
    )
    _validate_timeout = lambda t: (
        isinstance(t, (int, float)) and float(t) >= 0 if t is not None else True
    )

    if not _validate_metadata(metadata):
        raise TypeError(f"metadata must be a dict or None, got {type(metadata).__name__}")
    if not _validate_timeout(timeout):
        raise TypeError(f"timeout must be a non‑negative number or None, got {timeout!r}")

    def _decorator(real_func):
        import functools

        @functools.wraps(real_func)
        def _wrapper(*args, **kwargs):
            # Create a minimal transaction placeholder with metadata and timeout
            class DummyTx:
                def __init__(self):
                    self._metadata = metadata
                    self._timeout = float(timeout) if timeout is not None else None

            tx = DummyTx()
            # Call the original function with the transaction as first argument
            return real_func(tx, *args, **kwargs)

        return _wrapper

    # If decorator was applied without parenthesis
    if func is not None:
        return _decorator(func)

    return _decorator

