                raise IndexError(f"Index {k} out of bounds")
            key_name = key_list[k]
            result[key_name] = values[k]
        else:
            # Treat any non-integer as a key name.
            result[k] = full_dict.get(k, None)
    return result

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Attempt to acquire underlying key/value sequences
    try:
        keys_seq = getattr(self, "_keys")
        values_seq = getattr(self, "_values")
    except Exception:
        keys_seq = None
        values_seq = None

    # If we cannot find explicit key/value sequences, try to fall back to a dict-like interface
    if keys_seq is None or values_seq is None:
        # Works if the instance itself is dict-like
        try:
            data_dict = dict(self)
        except Exception:
            # As a last resort, return an empty dict
            if not keys:
                return {}
            return {k: None for k in keys}
        if not keys:
            return data_dict
        result = {}
        for k in keys:
            if isinstance(k, int):
                # Treat as an index on the keys list if possible
                if not isinstance(data_dict, dict):
                    raise IndexError(f"Index {k} out of bounds")
                # Convert to list if needed
                key_list = list(data_dict.keys())
                if k < -len(key_list) or k >= len(key_list):
                    raise IndexError(f"Index {k} out of bounds")
                idx_key = key_list[k]
                result[idx_key] = data_dict[idx_key]
            else:
                result[k] = data_dict.get(k, None)
        return result

    # Normal operation: we have explicit key/value sequences
    if not keys:
        return dict(zip(keys_seq, values_seq))

    result = {}
    for k in keys:
        if isinstance(k, int):
            # Handle negative indices as in normal Python lists
            if k < -len(keys_seq) or k >= len(keys_seq):
                raise IndexError(f"Index {k} out of bounds")
            key_name = keys_seq[k]
            value = values_seq[k]
            result[key_name] = value
        else:
            # Treat as a field name
            if k in keys_seq:
                idx = keys_seq.index(k)
                result[k] = values_seq[idx]
            else:
                result[k] = None
    return result

