def round_half_to_even(n):
    """
    Round float n to the nearest integer using the round-half-to-even rule.
    Integers are returned unchanged.
    """
    # validate input type
    if not isinstance(n, (int, float)):
        raise TypeError(f"Expected int or float, got {type(n)}")
    # treat int-like values as integer
    if isinstance(n, int) or (isinstance(n, float) and n.is_integer()):
        return int(n)
    # compute floor without importing math
    if n >= 0:
        floor = int(n)
    else:
        if n == int(n):
            floor = int(n)
        else:
            floor = int(n) - 1
    frac = n - floor
    # use a small tolerance for floating point comparison
    tol = 1e-12
    if abs(frac - 0.5) < tol:
        # exactly halfway; round to nearest even
        if floor % 2 == 0:
            return floor
        else:
            return floor + 1
    if frac > 0.5:
        return floor + 1
    else:
        return floor

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    The returned class will have the specified *fields* as attributes,
    accept an optional `srid` keyword, and provide a `to_dict()` method
    containing the coordinates, fields and srid.
    """
    # Validate inputs
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    try:
        field_names = list(fields)
    except Exception:
        raise TypeError("fields must be an iterable of field names")
    for f in field_names:
        if not isinstance(f, str):
            raise TypeError("field names must be strings")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dictionary")

    # Disallow reserved names
    reserved = {"x", "y", "srid"}
    overlap = set(field_names) & reserved
    if overlap:
        raise ValueError(f"field names cannot include reserved names: {', '.join(sorted(overlap))}")

    # Class namespace
    class_dict = {
        "srid_map": srid_map,
    }

    def __init__(self, x, y, **kwargs):
        # Convert coordinates
        try:
            self.x = float(x)
            self.y = float(y)
        except Exception as exc:
            raise ValueError(f"invalid coordinates for point: {exc}") from exc
        # Set dynamic fields from kwargs if provided
        for f in field_names:
            setattr(self, f, kwargs.get(f))
        # Optional srid
        self.srid = kwargs.get("srid", None)

    def __repr__(self):
        field_str = ", ".join(f"{f}={getattr(self, f)!r}" for f in field_names)
        return f"{name}(x={self.x!r}, y={self.y!r}, {field_str})"

    def to_dict(self):
        d = {"x": self.x, "y": self.y}
        for f in field_names:
            d[f] = getattr(self, f)
        d["srid"] = getattr(self, "srid", None)
        return d

    class_dict["__init__"] = __init__
    class_dict["__repr__"] = __repr__
    class_dict["to_dict"] = to_dict

    return type(name, (object,), class_dict)

