        # Preserve original function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper

    return decorator

def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    try:
        import traceback
        import os
    except Exception:
        # If imports fail, fall back to simple string
        return str(e)

    def _shorten_path(path):
        parts = path.split(os.sep)
        if len(parts) <= max_path_level:
            return path
        return os.sep.join(parts[-max_path_level:])

    # List to accumulate lines
    lines = []

    def _format_exc(exc):
        if not isinstance(exc, BaseException):
            return
        # Exception type and message
        lines.append(f"{exc.__class__.__name__}: {exc}")
        tb = exc.__traceback__
        if tb:
            # Extract frames; traceback.extract_tb returns in order from outermost to innermost
            frames = traceback.extract_tb(tb)
            # Limit to max_level
            for frame in frames[:max_level]:
                file_path = _shorten_path(frame.filename)
                lines.append(f"  File \"{file_path}\", line {frame.lineno}, in {frame.name}")
                if frame.line:
                    stripped = frame.line.strip()
                    if stripped:
                        lines.append(f"    {stripped}")
        # Handle exception chaining
        cause = exc.__cause__
        if cause:
            lines.append("\nThe above exception was the direct cause of the following exception:")
            _format_exc(cause)
        elif exc.__context__ and not exc.__suppress_context__:
            lines.append("\nDuring handling of the above exception, another exception occurred:")
            _format_exc(exc.__context__)

    _format_exc(e)
    return "\n".join(lines) if lines else str(e)

def file_to_textbuffer(file_name, encoding):
    """
    Load a file toward a text buffer (UTF-8), using the specify encoding while reading.
    CAUTION : This will read the whole file IN MEMORY.
    :param file_name: File name.
    :type file_name: str
    :param encoding: Encoding to use.
    :type encoding: str
    :return: A text buffer or None in case of error.
    :rtype str
    """
    # Validate file_name
    if isinstance(file_name, (str, bytes)):
        if not file_name:
            return None
    elif hasattr(file_name, "__fspath__"):
        try:
            # Convert to a string path
            file_name = os.fspath(file_name)
        except Exception:
            return None
    else:
        return None

    # Validate encoding
    if not isinstance(encoding, str) or not encoding:
        return None

    try:
        with open(file_name, "r", encoding=encoding) as f:
            return f.read()
    except Exception:
        return None

