            return False

def _reset_logging(cls):
    """Resets logging: clears all handlers from the root logger and sets the default level."""
    import logging
    try:
        root_logger = logging.getLogger()
        # Remove all handlers
        handlers = root_logger.handlers[:]
        for handler in handlers:
            root_logger.removeHandler(handler)
            try:
                handler.close()
            except Exception:
                pass
        # Reset the level to WARNING as a safe default
        root_logger.setLevel(logging.WARNING)
        # Ensure propagation is enabled
        root_logger.propagate = True
    except Exception:
        # Silently ignore any errors during reset
        pass

def _reset_logging(cls):
        """
        Reset the logging configuration to a clean state.
        This removes all handlers from the root logger, closes them
        (if possible), and sets the root logger level back to the
        default (WARNING).  It is safe to call even if logging has not
        been configured yet or if no handlers are attached.
        """
        try:
            import logging
        except Exception:
            # If the logging module cannot be imported, nothing to reset.
            return

        try:
            root = logging.getLogger()
        except Exception:
            # If retrieving the root logger fails, exit silently.
            return

        # If there are any handlers, close and remove them.
        handlers = list(root.handlers)  # Copy to avoid modification during iteration
        for handler in handlers:
            try:
                handler.close()
            except Exception:
                # Ignore any errors while closing handlers
                pass
            try:
                root.removeHandler(handler)
            except Exception:
                # Ignore any errors while removing handlers
                pass

        # Reset root logger level to the default (WARNING)
        try:
            root.setLevel(logging.WARNING)
        except Exception:
            # In rare cases setting the level may fail; ignore.
            pass

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    cls_name = getattr(self, "__class__").__name__
    if not cls_name:
        raise ValueError("Unable to determine class name for target implementation.")
    # Strip known suffixes
    if cls_name.endswith("Py"):
        target = cls_name[:-2]
    elif cls_name.endswith("Fallback"):
        target = cls_name[:-len("Fallback")]
    else:
        target = cls_name
    if not target:
        raise ValueError(f"Target class name derived from '{cls_name}' is empty after stripping suffixes.")
    return target

def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """

    # Basic input validation
    if orderings is None:
        raise ValueError("orderings cannot be None")
    if not isinstance(orderings, list):
        raise TypeError("orderings must be a list of lists")
    for idx, ordering in enumerate(orderings):
        if not isinstance(ordering, list):
            raise TypeError(f"ordering at index {idx} must be a list")

    # Build graph adjacency and indegree
    adjacency = {}
    indegree = {}
    # Track first appearance order for tie-breaking
    order_key = {}
    appearance_counter = 0

    for o_idx, ordering in enumerate(orderings):
        for pos, elem in enumerate(ordering):
            if elem not in adjacency:
                adjacency[elem] = set()
            if elem not in indegree:
                indegree[elem] = 0
            if elem not in order_key:
                # Use ordering index and position to generate a comparable key
                order_key[elem] = (o_idx, pos, appearance_counter)
                appearance_counter += 1

    # Add edges
    for ordering in orderings:
        for i in range(len(ordering) - 1):
            a = ordering[i]
            b = ordering[i + 1]
            # Avoid duplicate edges
            if b not in adjacency[a]:
                adjacency[a].add(b)
                indegree[b] = indegree.get(b, 0) + 1

    # Topological sort with priority based on order_key
    import heapq
    heap = []
    for elem, indeg in indegree.items():
        if indeg == 0:
            heapq.heappush(heap, (order_key[elem], elem))

    result = []
    seen = set()
    while heap:
        _, node = heapq.heappop(heap)
        if node in seen:
            continue
        seen.add(node)
        result.append(node)
        for nb in adjacency.get(node, []):
            indegree[nb] -= 1
            if indegree[nb] == 0:
                heapq.heappush(heap, (order_key[nb], nb))

    # If there are remaining nodes with indegree > 0, there's a cycle
    if len(result) != len(indeg_degree := indegree):
        raise ValueError("Cyclic dependency detected in orderings")

    return result

def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """
