def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    # Guard against invalid inputs; if the object is None or does not
    # have a ``__provides__`` attribute we return an empty mapping.
    try:
        provides = getattr(object, "__provides__", None)
    except Exception:
        # Any exception (e.g. object is not an instance) results in an empty
        # declaration to keep the function robust.
        return {}
    if provides is None:
        return {}
    # The ``__provides__`` attribute is expected to be an instance of
    # ``zope.interface.interfaces.IDeclaration``. If it is not, we fall back
    # to an empty declaration to avoid exposing an unexpected type.
    try:
        if not hasattr(provides, "keys") or not hasattr(provides, "items") \
                or not hasattr(provides, "copy"):
            return {}
    except Exception:
        return {}
    return provides

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Ensure we have an iterable sequence; if not, return empty list
    try:
        seq = list(classes)
    except Exception:
        return []

    result = []
    for cls in seq:
        # Skip None entries
        if cls is None:
            continue

        # If the item is not a class, add it directly
        try:
            is_cls = isinstance(cls, type)
        except Exception:
            # In unexpected cases treat it as non-class
            result.append(cls)
            continue

        if not is_cls:
            result.append(cls)
            continue

        # Skip cls if it is a subclass of any previously kept base
        skip_add = False
        for b in result:
            try:
                if isinstance(b, type) and issubclass(cls, b):
                    skip_add = True
                    break
            except Exception:
                continue
        if skip_add:
            continue

        # Remove any existing base that is a subclass of this new class
        # (those bases become redundant because they are already included via cls)
        filtered = []
        for b in result:
            try:
                if isinstance(b, type) and issubclass(b, cls):
                    # skip removal
                    continue
                filtered.append(b)
            except Exception:
                filtered.append(b)
        result = filtered
        result.append(cls)

    return result

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not isinstance(classes, (list, tuple)):
        raise TypeError(f"Expected a list or tuple of classes, got {type(classes)}")
    seen = set()
    result = []
    for c in classes:
        if not isinstance(c, type):
            raise TypeError(f"Expected a class type, got {type(c)!r}")
        if c not in seen:
            seen.add(c)
            result.append(c)
    return result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    results = []
    try:
        for name in dir(self):
            if name.startswith("_"):
                continue
            if not hasattr(self, name):
                continue
            try:
                value = getattr(self, name)
            except Exception:
                continue
            if callable(value):
                continue
            if isinstance(value, property):
                continue
            if not all and name not in self.__class__.__dict__:
                continue
            desc = ""
            try:
                desc = value.__doc__ or ""
            except Exception:
                desc = ""
            if not desc:
                try:
                    desc = getattr(value, "description", "") or ""
                except Exception:
                    desc = ""
            if not desc and hasattr(value, "field_info"):
                try:
                    field_info = getattr(value, "field_info")
                    desc = getattr(field_info, "description", "") or ""
                except Exception:
                    pass
            results.append((name, desc.strip()))
        results.sort(key=lambda x: x[0])
    except Exception:
        results = []
    return results

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """
    Return a mapping of attribute names to their descriptions.
    If *all* is True, include both class and instance attributes;
    otherwise only class attributes defined on the type are included.
    Private and built‑in attributes (starting with an underscore) are omitted.
    Descriptions are taken from the attribute's docstring if available,
    otherwise an empty string is returned.
    """
    # Choose attributes to inspect
    attrs = set()
    cls = self.__class__
    try:
        # class level attributes
        cls_attrs = vars(cls).keys()
        attrs.update(cls_attrs)
    except Exception:
        pass
    if all:
        try:
            # instance level attributes
            instance_attrs = vars(self).keys()
            attrs.update(instance_attrs)
        except Exception:
            pass

    result = {}
    for name in sorted(attrs):
        if name.startswith('_'):
            continue
        try:
            # Get the value from the instance
            val = getattr(self, name)
        except Exception:
            # Skip if value cannot be retrieved
            continue

        # Attempt to get a description
        desc = ''
        try:
            # Try to get the attribute descriptor from the class
            descriptor = getattr(cls, name, None)
            if descriptor is not None and hasattr(descriptor, '__doc__'):
                desc = descriptor.__doc__ or ''
        except Exception:
            desc = ''

        # If no descriptor docstring, check the value's type for a docstring
        if not desc:
            typ = type(val)
            if hasattr(typ, '__doc__') and typ.__doc__:
                desc = typ.__doc__.strip() if isinstance(typ.__doc__, str) else ''

        result[name] = desc
    return result

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    try:
        cls = self.__class__
    except AttributeError:
        raise TypeError("The 'names' method requires an instance with a __class__ attribute")

    # Retrieve attribute names from class annotations (attributes explicitly declared)
    annotations = getattr(cls, "__annotations__", {})
    interface_names = list(annotations.keys())

    # If 'all' is requested, also include other class attributes that are not
    # private, not built-in dunder names, and not callables (methods).
    if all:
        try:
            class_attrs = [
                name for name, value in cls.__dict__.items()
                if not name.startswith("_")
                and not callable(value)
                and name not in interface_names
            ]
        except Exception:
            class_attrs = []
        try:
            instance_attrs = [
                name for name in getattr(self, "__dict__", {})
                if not name.startswith("_")
                and name not in interface_names
            ]
        except Exception:
            instance_attrs = []

        interface_names.extend(class_attrs)
        interface_names.extend(instance_attrs)

    # Return sorted list for consistent ordering
    return sorted(set(interface_names))

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    names_set = set()
    try:
        # Include instance attributes
        instance_attrs = getattr(self, "__dict__", {})
        for key, value in instance_attrs.items():
            if key.startswith("_") or callable(value):
                continue
            names_set.add(key)

        # Determine which classes to inspect
        mro = self.__class__.mro()
        if not all:
            mro = [self.__class__]

        # Include class and (optionally) base class attributes
        for cls in mro:
            cls_dict = getattr(cls, "__dict__", {})
            for key, value in cls_dict.items():
                if key.startswith("_") or callable(value):
                    continue
                names_set.add(key)
    except Exception:
        # On unexpected errors, return an empty list
        return []
    return sorted(names_set)

def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments.

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        # Start with a new list if none provided
        output = []

    # Helper to determine if an object is a sequence that should be iterated.
    def _is_iterable(obj):
        return hasattr(obj, "__iter__") and not isinstance(obj, (str, bytes))

    # If the top-level sequence is iterable and not a string, iterate over it.
    if _is_iterable(sequence):
        for item in sequence:
            # If the item itself is a sequence (list/tuple), decide how to treat it.
            if isinstance(item, (list, tuple)) and _is_iterable(item):
                # Detect an "implements spec": all elements are non-sequences.
                if all(not _is_iterable(sub) for sub in item):
                    # Treat the whole tuple as a single implements spec.
                    output.append(item)
                else:
                    # Expand nested sequences recursively.
                    _normalizeargs(item, output)
            else:
                # Base case: not a nested sequence, add directly.
                output.append(item)
    else:
        # The input is a single (non-iterable) argument; add it.
        output.append(sequence)

    return output

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarations, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    if sequence is None:
        return output
    try:
        iterator = iter(sequence)
    except TypeError:
        # Not iterable, treat as single element
        iterator = [sequence]
    for item in iterator:
        # If item is an instance of tuple or list, expand it
        if isinstance(item, (tuple, list)):
            for subitem in item:
                # Avoid expanding nested tuples/lists again
                if isinstance(subitem, (tuple, list)):
                    output.extend(subitem)
                else:
                    output.append(subitem)
        else:
            output.append(item)
    return output

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarations, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    # Initialize output container
    if output is None:
        output = []

    # Ensure we have an iterable
    try:
        seq_iter = iter(sequence)
    except TypeError:
        seq_iter = (sequence,)

    for item in seq_iter:
        # If the item is a tuple or list, recurse to flatten it
        if isinstance(item, (list, tuple)):
            _normalizeargs(item, output)
        else:
            output.append(item)

    return tuple(output)  # Return a tuple for consistency

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    # Use an auxiliary function for recursion
    def _inner(items, out):
        for item in items:
            # Skip None values
            if item is None:
                continue
            # If the item is an iterable but not a string/bytes, process it
            if isinstance(item, (list, tuple)):
                # Determine if this tuple represents an implements spec:
                # a 2‑element tuple that does not contain nested iterables.
                if isinstance(item, tuple) and len(item) == 2 and not any(isinstance(sub, (list, tuple)) for sub in item):
                    out.append(item)
                else:
                    # Recursively flatten nested iterable
                    _inner(item, out)
            else:
                out.append(item)

    # Initialise output list if not provided
    if output is None:
        output = []

    # Guard against non-iterables being passed directly
    if not isinstance(sequence, (list, tuple)):
        # Treat as a single declaration
        output.append(sequence)
    else:
        _inner(sequence, output)

    return output

def _should_attempt_c_optimizations():
    """
    Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    try:
        import os
        import sys
    except Exception:
        # If for some reason importing fails, avoid using C optimizations.
        return False
    # Avoid C optimizations if the PURE_PYTHON environment variable is set.
    if os.getenv("PURE_PYTHON"):
        return False
    # Avoid C optimizations on PyPy, which may have issues loading native
    # extensions in some environments.
    try:
        if getattr(sys.implementation, "name", "").lower() == "pypy":
            return False
    except Exception:
        pass
    return True

