    try:
        # Assume _c_optimizations_required is defined elsewhere and returns a truthy/falsy value
        return not _c_optimizations_required()
    except NameError:
        raise RuntimeError("_c_optimizations_required is not defined.")
    except Exception as e:
        raise RuntimeError(f"Error evaluating _c_optimizations_required: {e}") from e

def _c_optimizations_ignored():
    """
