    """
    try:
        # If PURE_PYTHON is truthy, C optimizations are not required.
        return not bool(PURE_PYTHON)
    except Exception:
        # If the variable is missing or any error occurs, assume optimizations are required.
        return True

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    # If PURE_PYTHON is set and truthy (e.g., True, non-empty string, non-zero integer)
    # then we are running in pure‑python mode and C optimizations are *not* required.
    # In all other circumstances we default to requiring the C optimizations.
    try:
        return not bool(globals().get("PURE_PYTHON", False))
    except Exception:
        # If for any reason we cannot access PURE_PYTHON, assume C optimizations are needed
        return True

def _c_optimizations_required():
