def to_csv(self, separator=",", header=None):
        """Convert graph's points to CSV.

        Args:
            separator (str, optional): Value delimiter. Defaults to ','.
            header (str, optional): First line of output. If provided,
                a trailing newline will be appended automatically.

        Returns:
            str: CSV representation of the graph.

        Raises:
            TypeError: If ``separator`` is not a string.
            ValueError: If graph points cannot be iterated.
        """
        if not isinstance(separator, str):
            raise TypeError(f"separator must be a string, got {type(separator).__name__}")

        lines = []
        if header is not None:
            lines.append(str(header))

        try:
            for point in self.points:
                # Try to extract coordinates and value parts from point
                coord = None
                value = None
                # Common case: point is a tuple/list of (coord, value)
                if isinstance(point, (list, tuple)):
                    if len(point) >= 2:
                        coord, value = point[0], point[1]
                    elif len(point) == 1:
                        coord, value = None, point[0]
                else:
                    # Fallback: use attributes if available
                    coord = getattr(point, "coords", None)
                    value = getattr(point, "value", None)
                    if coord is None and value is None:
                        # Treat whole point as a value
                        coord, value = None, point

                # Convert coordinate parts to string
                coord_parts = []
                if coord is not None:
                    if isinstance(coord, (list, tuple)):
                        coord_parts = [str(c) for c in coord]
                    else:
                        coord_parts = [str(coord)]

                # Convert value parts to string
                value_parts = []
                if isinstance(value, (list, tuple)):
                    value_parts = [str(v) for v in value]
                else:
                    value_parts = [str(value)]

                # Join all parts
                line = separator.join(coord_parts + value_parts)
                lines.append(line)
        except Exception as exc:
            raise ValueError(f"Error generating CSV: {exc}") from exc

        # Join lines with newlines and ensure trailing newline
        return "\n".join(lines) + ("\n" if lines else "")

def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional, for each point first its
    coordinate is converted to string (separated by *separator*), then
    each part of its value.
    """
    sep = str(separator)
    lines = []
    try:
        # Header handling: add header line if provided
        if header is not None:
            lines.append(str(header))

        # Retrieve points; expect an iterable of (coord, value) tuples
        points = getattr(self, "points", None)
        if points is None:
            return "\n".join(lines)

        for point in points:
            try:
                coord, value = point
            except Exception:
                # Skip points that cannot be unpacked into two items
                continue

            # Build list of string parts: coordinates followed by value parts
            parts = []

            # Handle coordinate part
            if isinstance(coord, (list, tuple)):
                parts.extend(str(c) for c in coord)
            else:
                parts.append(str(coord))

            # Handle value part
            if isinstance(value, (list, tuple)):
                parts.extend(str(v) for v in value)
            else:
                parts.append(str(value))

            lines.append(sep.join(parts))

        return "\n".join(lines)
    except Exception:
        # In case of any unexpected error, return an empty string
        return ""

def to_csv(self, separator=",", header=None):
        """
        Convert graph's points to CSV.

        *separator* delimits values, the default is comma.

        *header*, if not ``None``, is the first string of the output
        (new line is added automatically).

        Since a graph can be multidimensional,
        for each point first its coordinate is converted to string
        (separated by *separator*), then each part of its value.
        """
        # Ensure separator is a string
        if not isinstance(separator, str):
            try:
                separator = str(separator)
            except Exception as exc:
                raise ValueError("separator must be string convertible") from exc

        lines = []

        # Add header if provided
        if header is not None:
            # Convert header to string
            lines.append(str(header))

        # Retrieve points from the graph; this attribute may vary by implementation
        points = getattr(self, "points", None)
        if points is None:
            # No points to export
            return "\n".join(lines)

        for idx, point in enumerate(points):
            try:
                x, val = point
            except Exception as exc:
                raise ValueError(f"Point {idx} is not a (coordinate, value) pair") from exc

            # Build list of string parts for the line
            line_parts = []

            # Handle coordinate(s)
            if isinstance(x, (list, tuple)):
                for coord in x:
                    line_parts.append(str(coord))
            else:
                line_parts.append(str(x))

            # Handle value(s)
            if isinstance(val, (list, tuple)):
                for comp in val:
                    line_parts.append(str(comp))
            else:
                line_parts.append(str(val))

            # Join parts with separator
            lines.append(separator.join(line_parts))

        return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Construct the expected attribute name for the error array/datum.
    err_attr = f"{coord_name}_err"
    # Retrieve the error data.  If it does not exist, return an empty list.
    err = getattr(self, err_attr, None)
    if err is None:
        return []

    # Helper: flatten a nested sequence into a 1‑D list.  This is used if
    # NumPy is not available or the err object is not array‑like.
    def _flatten(seq):
        if isinstance(seq, (str, bytes)):
            return [seq]
        try:
            iter(seq)
        except TypeError:
            return [seq]
        out = []
        for sub in seq:
            out.extend(_flatten(sub))
        return out

    # Try importing NumPy for efficient handling.  Fall back to pure Python
    # list processing if NumPy is not available.
    try:
        import numpy as np  # type: ignore
        try:
            arr = np.asarray(err)
        except Exception:
            # If conversion fails, fall back to raw handling
            raise ImportError
        # Identify finite elements (i.e., valid error values).  NaN or
        # Inf are considered invalid and excluded.
        mask = np.isfinite(arr)
        # np.where returns a tuple of arrays; the first element contains the
        # indices along the first axis for a flattened view of the array.
        indices = np.where(mask)[0]
        return indices.tolist()
    except Exception:
        # Use pure Python fallback
        flat_err = _flatten(err)
        indices = []
        for idx, val in enumerate(flat_err):
            # Treat None and NaN as missing errors.
            if val is None:
                continue
            try:
                if isinstance(val, float) and val != val:  # NaN detection
                    continue
            except Exception:
                continue
            indices.append(idx)
        return indices

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate input
    if coord_name is None or not isinstance(coord_name, str):
        raise TypeError("coord_name must be a non‑empty string")
    coord_name = coord_name.strip().lower()
    if not coord_name:
        raise ValueError("coord_name cannot be an empty string")

    # Attempt to locate error data for the given coordinate
    err_values = None
    # 1. Check for a dedicated attribute like _err_x, _err_y, etc.
    attr_name = f"_err_{coord_name}"
    if hasattr(self, attr_name):
        err_values = getattr(self, attr_name)
    # 2. Check for a dictionary of errors
    elif hasattr(self, "err") and isinstance(getattr(self, "err"), dict):
        err_values = getattr(self, "err").get(coord_name)

    # 3. If still not found, raise
    if err_values is None:
        raise AttributeError(f"No error information found for coordinate '{coord_name}'")

    # Convert to a generic sequence if needed
    try:
        length = len(err_values)
    except Exception:
        raise TypeError(f"Error data for '{coord_name}' must be a sequence or array")

    # Gather indices where the error value is present and non‑zero
    indices = []
    for idx in range(length):
        try:
            val = err_values[idx]
        except Exception:
            # If we cannot access the element, skip it
            continue
        if val is None:
            continue
        # Accept numeric types and compare to zero
        try:
            # For bools, a bool is considered an error if True, but bools usually not used
            if isinstance(val, bool):
                if val:
                    indices.append(idx)
                continue
            if float(val) != 0.0:
                indices.append(idx)
        except Exception:
            # For non‑numeric values, treat any value other than None as error
            indices.append(idx)

    return indices

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    try:
        if not isinstance(coord_name, str):
            return []
        # Attempt to retrieve from a dedicated error index mapping if present
        err_map = getattr(self, "_err_indices", None) or getattr(self, "_error_indices", None)
        if isinstance(err_map, dict):
            return list(err_map.get(coord_name, []))
        # Fallback: assume an 'errors' attribute where each coordinate has a list/tuple of error flags
        errors = getattr(self, "errors", None)
        if isinstance(errors, dict):
            err_flags = errors.get(coord_name)
            if isinstance(err_flags, (list, tuple, set)):
                return [i for i, flag in enumerate(err_flags) if bool(flag)]
        # If no suitable structure is found, return an empty list
        return []
    except Exception:
        # In case of unexpected issues, return an empty list to avoid propagating errors
        return []

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    try:
