            indices = errors_dict.get(coord_name, [])
        else:
            # If no dictionary, check if the instance has separate attributes per coordinate
            # For example, self._x_err_idx, self._y_err_idx, etc.
            attr_name = f"_{coord_name}_err_idx"
            if hasattr(self, attr_name):
                indices = getattr(self, attr_name)
            else:
                # As a last resort, look for a generic _err_idx attribute that might be a list
                # of indices for all coordinates and a mapping to coordinate names
                generic_indices = getattr(self, "_err_idx", None)
                coord_map = getattr(self, "_coord_to_index", {})
                idx = coord_map.get(coord_name)
                if generic_indices is not None and idx is not None:
                    indices = generic_indices[idx]
                else:
                    indices = []
        # Normalise to a list (or empty list if None)
        if indices is None:
            indices = []
        if isinstance(indices, (tuple, set)):
            indices = list(indices)
        # If indices is a scalar, wrap it in a list
        if isinstance(indices, (int, float)):
            indices = [indices]
        return indices
    except Exception as exc:
        raise RuntimeError(
            f"Unable to retrieve error indices for coordinate '{coord_name}': {exc}"
        ) from exc

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    try:
        bins_list = list(bins)
        edges_list = list(edges)
    except TypeError:
        raise TypeError("bins and edges must be iterable types")

    n_bins = len(bins_list)
    n_edges = len(edges_list)

    if n_edges != n_bins + 1:
        raise ValueError(f"Expected edges length to be one more than bins length, got {n_edges} and {n_bins}")

    # Compute the width of each bin
    widths = []
    for i in range(n_bins):
        try:
            lower = float(edges_list[i])
            upper = float(edges_list[i + 1])
        except (TypeError, ValueError):
            raise TypeError(f"Edge {i} or {i + 1} is not a numeric value")
        if upper < lower:
            raise ValueError(f"Edge {i + 1} ({upper}) is less than edge {i} ({lower})")
        widths.append(upper - lower)

    # Compute the integral by weighting each bin value with its width
    integral_val = 0.0
    for val, width in zip(bins_list, widths):
        try:
            val_float = float(val)
        except (TypeError, ValueError):
            raise TypeError("All elements in bins must be numeric values")
        integral_val += val_float * width

    return integral_val

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # validate inputs
    try:
        bins = list(bins)
        edges = list(edges)
    except TypeError:
        raise TypeError("`bins` and `edges` must be iterable")

    if not isinstance(bins, list) or not isinstance(edges, list):
        raise TypeError("`bins` and `edges` must be iterable")

    n_bins = len(bins)
    if len(edges) != n_bins + 1:
        raise ValueError("Length of `edges` must be len(`bins`) + 1")

    total = 0.0
    for i in range(n_bins):
        try:
            width = edges[i + 1] - edges[i]
        except Exception as exc:
            raise ValueError("`edges` must contain numeric values") from exc
        try:
            total += float(bins[i]) * float(width)
        except Exception as exc:
            raise ValueError("`bins` and `edges` must contain numeric values") from exc

    return total

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Basic input validation
    if bins is None:
        raise TypeError("bins must not be None")
    if edges is None:
        raise TypeError("edges must not be None")
    # Ensure both are iterable
    try:
        b_iter = list(bins)
    except Exception as exc:
        raise TypeError("bins must be an iterable of numeric values") from exc
    try:
        e_iter = list(edges)
    except Exception as exc:
        raise TypeError("edges must be an iterable of numeric values") from exc

    # Check that edges contain at least two points
    if len(e_iter) < 2:
        raise ValueError("edges must contain at least two points")
    # Check that number of bins matches edges-1
    if len(b_iter) != len(e_iter) - 1:
        raise ValueError("Number of bins must be one less than number of edges")

    # Verify that edges are monotonically increasing
    for i in range(len(e_iter) - 1):
        if e_iter[i] >= e_iter[i + 1]:
            raise ValueError("edges must be monotonically increasing")

    # Compute widths
    widths = []
    for i in range(len(e_iter) - 1):
        try:
            width = e_iter[i + 1] - e_iter[i]
        except Exception as exc:
            raise TypeError("edges must contain numeric values") from exc
        if width < 0:
            raise ValueError("edge differences must be non-negative")
        widths.append(width)

    # Compute integral
    integral_value = 0.0
    for bin_val, width in zip(b_iter, widths):
        try:
            integral_value += bin_val * width
        except Exception as exc:
            raise TypeError("bins must contain numeric values") from exc

    return integral_value

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

