        if seq is None or isinstance(seq, (str, bytes)):
            return False

        # Attempt to iterate over seq
        try:
            iterator = iter(seq)
        except TypeError:
            # seq is not iterable
            return False

        # Check each item for an instance of FillRequest
        for item in seq:
            if item is None:
                continue
            if isinstance(item, FillRequest):
                # Ensure seq itself wasn't mistakenly identified as a Source later
                if Source is not None and isinstance(seq, Source):
                    return False
                return True

        # No FillRequest found
        return False
    except Exception:
        # In case of any unexpected runtime error, default to False
        return False

