def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        try:
            import numpy as np
            # Ensure the coordinate is an array
            coord_arr = np.asarray(coord)
            # Accept either a single point (n,) or a batch of points (m, n)
            if coord_arr.ndim == 1:
                points = [coord_arr]
            elif coord_arr.ndim == 2 and coord_arr.shape[1] == len(self.edges):
                points = [row for row in coord_arr]
            else:
                # Invalid shape: ignore
                return

            for pt in points:
                # Check bounds for each axis
                in_bounds = True
                for val, edges in zip(pt, self.edges):
                    if val < edges[0] or val >= edges[-1]:
                        in_bounds = False
                        break
                if not in_bounds:
                    continue

                # Find the bin indices
                indices = []
                for val, edges in zip(pt, self.edges):
                    # np.searchsorted returns the index where val would be inserted to maintain order
                    idx = np.searchsorted(edges, val, side='right') - 1
                    indices.append(idx)

                # Increment the histogram bin by the weight
                try:
                    self.data[tuple(indices)] += weight
                except Exception:
                    # If the weight can’t be added or indices are invalid, skip silently
                    continue
        except Exception:
            # If any error occurs (e.g., missing attributes), ignore and exit gracefully
            return

