def validate_value(value):
    """
    Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    # Import ValidationError if it hasn't been imported already
    try:
        ValidationError  # noqa: F821
    except NameError as exc:
        raise NameError("The 'ValidationError' exception must be defined globally.") from exc

    # Ensure the value is a string; attempt conversion if possible
    if value is None:
        raise ValidationError("Value cannot be None.")
    if not isinstance(value, str):
        try:
            value = str(value)
        except Exception as exc:
            raise ValidationError(f"Value of type {type(value).__name__} cannot be stringified: {exc}") from exc

    # Retrieve the regex pattern that should have been defined globally
    # The pattern may be a compiled regex object or a string
    try:
        pattern = globals().get('VALUE_REGEX')
    except Exception as exc:
        raise ValidationError(f"Failed to retrieve global 'VALUE_REGEX': {exc}") from exc

    if pattern is None:
        raise ValidationError("Global variable 'VALUE_REGEX' is required for validation but is missing.")

    # Attempt to perform the matching
    try:
        # If compiled, use fullmatch directly
        match_obj = None
        if hasattr(pattern, 'fullmatch') and callable(pattern.fullmatch):
            match_obj = pattern.fullmatch(value)
        else:
            import re  # ensure re is available
            match_obj = re.fullmatch(pattern, value)
    except re.error as exc:  # noqa: F821
        raise ValidationError(f"Invalid regular expression in 'VALUE_REGEX': {exc}") from exc
    except Exception as exc:
        # Catch any unexpected errors during matching
        raise ValidationError(f"Error during regex matching: {exc}") from exc

    if not match_obj:
        raise ValidationError(f"Invalid value: {value!r}")

    # If we reach here, the value matches the pattern
    return True

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Update a partial `last_applied_manifest` (a list) from a partial Kubernetes response
    using a schema describing the observed fields.

    Parameters
    ----------
    last_applied_manifest : list
        The manifest list to be updated in place.
    observer_schema : list or dict
        Schema description defining the fields expected in each element of the list.
    response : list
        The partial response received from the Kubernetes API.

    Notes
    -----
    * The function appends placeholder dictionaries to `last_applied_manifest` if it contains
      fewer elements than `response`.
    * Each element of `response` that is a dictionary is merged into the corresponding
      dictionary in `last_applied_manifest` via :func:`update_last_applied_manifest_dict_from_resp`.
    * Scalar items in the list are copied directly.
    * The function is designed to be used recursively for nested lists.
    """
    # Basic input validation
    if not isinstance(last_applied_manifest, list):
        raise TypeError(
            f"last_applied_manifest must be a list, got {type(last_applied_manifest).__name__}"
        )
    if not isinstance(response, list):
        raise TypeError(
            f"response must be a list, got {type(response).__name__}"
        )
    if observer_schema is None:
        # Nothing to observe: just copy the response list if not already present
        # Ensure last_applied_manifest has the same contents
        for idx, val in enumerate(response):
            if idx < len(last_applied_manifest):
                if last_applied_manifest[idx] != val:
                    last_applied_manifest[idx] = val
            else:
                last_applied_manifest.append(val)
        return

    # Ensure last_applied_manifest has enough placeholders for each response item
    while len(last_applied_manifest) < len(response):
        last_applied_manifest.append({})

    # Determine item schema for processing; for a list schema it may provide a single dict or a list of dicts
    # For simplicity, if it's a list we use the first element as the schema for all items
    if isinstance(observer_schema, list) and len(observer_schema) > 0:
        item_schema = observer_schema[0]
    else:
        item_schema = observer_schema

    for idx, resp_item in enumerate(response):
        try:
            # If the response item is not a dict, copy it directly
            if not isinstance(resp_item, dict):
                last_applied_manifest[idx] = resp_item
                continue

            # Ensure the corresponding manifest item is a dict
            if not isinstance(last_applied_manifest[idx], dict):
                last_applied_manifest[idx] = {}

            # Recursively update the dictionary
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[idx], item_schema, resp_item
            )
        except Exception as exc:
            # Log the error and skip the problematic entry to avoid halting
            # the entire update process. In production code, use logging.
            # For this module, we simply re‑raise to indicate failure.
            raise RuntimeError(
                f"Failed to update list element at index {idx} due to: {exc}"
            ) from exc
    return

