                if isinstance(response[key], list):
                    # Attempt to call a sibling helper; if not available, fall back
                    try:
                        update_last_applied_manifest_list_from_resp(
                            last_applied_manifest[key], sub_schema, response[key]
                        )
                    except NameError:
                        # No dedicated list updater; simply copy if types match
                        if (
                            isinstance(last_applied_manifest[key], list)
                            and last_applied_manifest[key] == []
                        ):
                            last_applied_manifest[key] = copy.deepcopy(response[key])
                    except Exception:
                        # On any error, fall back to a full copy
                        last_applied_manifest[key] = copy.deepcopy(response[key])
                else:
                    last_applied_manifest[key] = copy.deepcopy(response[key])
            else:
                # Scalar or other type: preserve existing value
                pass
    return last_applied_manifest

def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema.

    Returns:
        dict: A mapping from resource names to the generated default observer schemas.

    Raises:
        TypeError: If ``app`` is ``None``.
        AttributeError: If required attributes are missing on ``app`` or its ``spec``.
    """
    if app is None:
        raise TypeError("app must not be None")

    spec = getattr(app, "spec", None)
    if spec is None:
        raise AttributeError("app has no 'spec' attribute")

    manifest = getattr(spec, "manifest", None)
    if manifest is None:
        raise AttributeError("spec has no 'manifest' attribute")

    # Custom observer schemas that already exist
    custom_schemas = getattr(spec, "observer_schemas", {})
    if custom_schemas is None:
        custom_schemas = {}

    default_schemas = {}

    # Handle both list and dict manifests
    if isinstance(manifest, dict):
        resources = [(name, resource) for name, resource in manifest.items() if isinstance(resource, dict)]
    elif isinstance(manifest, list):
        resources = [(None, resource) for resource in manifest if isinstance(resource, dict)]
    else:
        # If the manifest is neither list nor dict, we cannot process it
        raise TypeError("spec.manifest must be a list or dict of resource definitions")

    for idx, (key_in_manifest, res) in enumerate(resources):
        # Determine a resource name
        res_name = None
        if isinstance(res, dict):
            res_name = res.get("name") or res.get("metadata", {}).get("name")
        if not res_name:
            res_name = f"resource_{idx}"

        # Skip resources that already have a custom schema
        if res_name in custom_schemas:
            continue

        # Build a default schema that includes all top‑level keys of the resource
        schema = {}
        for k, v in res.items():
            if k == "metadata" and isinstance(v, dict):
                schema["metadata"] = {subk: True for subk in v}
            else:
                schema[k] = True

        default_schemas[res_name] = schema

    return default_schemas

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Validate the overall argument
    if app is None:
        raise ValueError("The 'app' argument must not be None")

    # ----------------------------------------------------
    # 1) Extract the manifest dictionary from the spec.
    # ----------------------------------------------------
    try:
        manifest = getattr(app.spec, "manifest")
    except AttributeError as exc:
        raise AttributeError("The application spec must contain a 'manifest' attribute.") from exc

    if not isinstance(manifest, dict):
        raise TypeError("The application spec's 'manifest' must be a dictionary")

    # ----------------------------------------------------
    # 2) Ensure the observer_schema structure exists.
    # ----------------------------------------------------
    try:
        observer_schema = getattr(app.spec, "observer_schema")
    except AttributeError:
        # If it does not exist, create it.
        observer_schema = {}
        setattr(app.spec, "observer_schema", observer_schema)

    if observer_schema is None:
        observer_schema = {}
        setattr(app.spec, "observer_schema", observer_schema)

    if not isinstance(observer_schema, dict):
        raise TypeError("The application spec's 'observer_schema' must be a dictionary")

    # ----------------------------------------------------
    # 3) For each resource, add a default schema if missing.
    # ----------------------------------------------------
    for res_name in manifest:
        if res_name not in observer_schema:
            # The default observer schema is a minimal placeholder.
            # It could be expanded later by more specific logic.
            observer_schema[res_name] = {"default": True}

    # ----------------------------------------------------
    # 4) No explicit return value: the function mutates
    #    the application spec in place.
    # ----------------------------------------------------
    return None

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Basic validation of the input object
    try:
        spec = app.spec
    except AttributeError:
        raise ValueError("The provided application object does not have a 'spec' attribute.")

    # Retrieve the manifest which should contain the Kubernetes resources
    manifest = getattr(spec, "manifest", None)
    if manifest is None:
        return  # nothing to process

    # The manifest can be a dictionary with a 'resources' key or a direct list
    if isinstance(manifest, dict):
        resources = manifest.get("resources", [])
    else:
        resources = manifest

    if not isinstance(resources, list):
        raise ValueError(
            f"Expected 'spec.manifest' to be a list of resources or a dict containing 'resources', "
            f"got {type(resources).__name__}"
        )

    # Ensure we have a mutable dictionary for observers
    observers = getattr(spec, "observers", None)
    if observers is None:
        observers = {}
        setattr(spec, "observers", observers)
    elif not isinstance(observers, dict):
        raise ValueError(
            f"Expected 'spec.observers' to be a dict mapping kind to schema, got {type(observers).__name__}"
        )

    # Iterate through resources and generate default schemas where missing
    for res in resources:
        if not isinstance(res, dict):
            continue  # skip non-dict entries
        kind = res.get("kind")
        if not kind:
            continue  # skip resources without a kind
        if kind not in observers:
            # Create a basic default JSON schema that accepts any object
            observers[kind] = {"type": "object", "properties": {}, "required": [], "additionalProperties": True}

def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: A dictionary mapping each resource kind to its observer schema.
    """
    # Validate input
    if app is None:
        raise ValueError("app cannot be None")

    # Try to access spec and its attributes; handle missing attributes gracefully
    try:
        spec = getattr(app, "spec", None)
    except Exception as exc:
        raise ValueError(f"Unable to access app.spec: {exc}") from exc

    if not isinstance(spec, object):
        raise TypeError("app.spec must be an object")

    # Retrieve the manifest; it should be an iterable of Kubernetes resource dicts
    manifest = getattr(spec, "manifest", None)
    if manifest is None:
        raise AttributeError("app.spec.manifest is required")
    if not isinstance(manifest, (list, tuple)):
        raise TypeError("app.spec.manifest must be a list or tuple of resources")

    # Existing observer schemas, if any
    existing_schemas = getattr(spec, "observer_schema", {})
    if existing_schemas is None:
        existing_schemas = {}
    if not isinstance(existing_schemas, dict):
        raise TypeError("app.spec.observer_schema must be a dict if present")

    # Prepare the result dictionary
    result = existing_schemas.copy()

    for resource in manifest:
        # Each resource is expected to be a dict with a 'kind' key
        if not isinstance(resource, dict):
            # Skip non-dict entries
            continue
        kind = resource.get("kind")
        if not kind:
            continue
        if kind not in result:
            # Create a very generic default schema that captures the whole object.
            # This can be refined later if needed.
            default_schema = {
                "type": "object",
                "properties": {},
                "additionalProperties": True
            }
            result[kind] = default_schema
    return result

def validate(self, path):
        """Validate OCFL object at path or pyfs root.

        Returns True if valid (warnings permitted), False otherwise.
        """
        # Basic sanity checks: path must be provided
        if path is None:
            return False
        try:
            # Determine if the path is a string or a file-system-like object
            if isinstance(path, str):
                # Use os.path utilities for string paths
                import os

                # Resolve to absolute path
                abs_path = os.path.abspath(path)
                if not os.path.isdir(abs_path):
                    return False
                # In a valid OCFL root there should be a ".ocfl_root" file
                root_file = os.path.join(abs_path, ".ocfl_root")
                if not os.path.isfile(root_file):
                    return False
                # The ".ocfl_root" file should contain the string "1.0" (OCFL v1.0)
                try:
                    with open(root_file, "r", encoding="utf-8") as f:
                        content = f.read().strip()
                        if content != "1.0":
                            # allow warning but still consider valid for version mismatch
                            pass
                except Exception:
                    # If we can't read the file, consider invalid
                    return False
                return True
            else:
                # Assume a pyfs-like object with typical methods
                # It should have exists() and isdir()
                if not getattr(path, "exists", None) or not getattr(path, "is_dir", None):
                    return False
                if not path.exists():
                    return False
                if not path.is_dir():
                    return False
                # Check for ".ocfl_root" file
                try:
                    root_file = path / ".ocfl_root"
                    if not root_file.exists():
                        return False
                    # Read the file content
                    with root_file.open("r", encoding="utf-8") as f:
                        content = f.read().strip()
                        if content != "1.0":
                            # Allow warning but still valid
                            pass
                except Exception:
                    return False
                return True
        except Exception:
            # Any unhandled exception results in invalid
            return False

