        errors = getattr(self, 'errors', None)
        warnings = getattr(self, 'warnings', None)

        # Helper to compute count or string representation
        def _repr(val):
            if val is None:
                return None
            if isinstance(val, (list, tuple, set)):
                return f"{len(val)} error(s)" if isinstance(val, (list, tuple, set)) and 'error' in errors.__class__.__name__.lower() else f"{len(val)} warning(s)"
            return str(val)

        has_errors = bool(errors) if errors is not None else False
        has_warnings = bool(warnings) if warnings is not None else False

        if not has_errors and not has_warnings:
