    if isinstance(log, str):
        log_items = [log]
    else:
        # Otherwise, assume it is an iterable of log entries
        log_items = log

    lines = []
    for entry in log_items:
        # Try to convert the entry to a string; fall back to repr if conversion fails
        try:
