def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type check
    if not isinstance(inventory, dict):
        raise ValueError("inventory must be a dictionary")

    errors = []

    # Determine spec_version
    spec_version = getattr(self, "spec_version", None)

    if extract_spec_version:
        type_value = inventory.get("type")
        if type_value is None:
            errors.append("missing inventory 'type'")
        elif not isinstance(type_value, str):
            errors.append("inventory 'type' must be a string")
        else:
            # Example mapping – can be extended as needed
            type_map = {
                "alpha": "1.0",
                "beta": "2.0",
                "gamma": "3.0",
            }
            key = type_value.lower()
            if key in type_map:
                spec_version = type_map[key]
            else:
                errors.append(f"unknown inventory type '{type_value}'")
                # keep default spec_version
    # Basic validation rules
    name = inventory.get("name")
    if not name or not isinstance(name, str):
        errors.append("inventory must have a non-empty string 'name'")

    devices = inventory.get("devices")
    if not isinstance(devices, list) or not devices:
        errors.append("inventory must contain a non-empty list of 'devices'")
    else:
        for idx, dev in enumerate(devices):
            if not isinstance(dev, dict) or "id" not in dev:
                errors.append(f"device at index {idx} is invalid; must be a dict with 'id'")

    # Result
    result = {"valid": not errors, "errors": errors}
    if spec_version is not None:
        result["spec_version"] = spec_version
    return result

def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # inventory must be a mapping
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict")

    # determine spec version
    spec_version = self.spec_version
    if extract_spec_version:
        type_val = inventory.get("type")
        if isinstance(type_val, str) and type_val in ("1.0", "2.0", "3.0"):
            spec_version = type_val

    # basic structure check – an inventory contains a 'components' list
    components = inventory.get("components")
    if not isinstance(components, list):
        raise ValueError("inventory must contain a 'components' list")

    # expected fields per spec version
    spec_requirements = {
        "1.0": ("name", "uri"),
        "2.0": ("name", "uri", "protocol"),
        "3.0": ("name", "uri", "plugin"),
    }
    required_fields = spec_requirements.get(spec_version)
    if required_fields is None:
        raise ValueError(f"Unsupported spec version: {spec_version!r}")

    # validate each component
    for idx, comp in enumerate(components):
        if not isinstance(comp, dict):
            raise ValueError(f"component at index {idx} must be a dict")
        missing = [key for key in required_fields if key not in comp]
        if missing:
            raise ValueError(
                f"component at index {idx} missing required fields: {missing}"
            )

    return True""

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Inventory must be a mapping.
    if not isinstance(inventory, dict):
        raise TypeError("Inventory must be a dictionary instance.")

    # Determine the spec version to validate against.
    if extract_spec_version:
        spec_version = inventory.get("type")
        try:
            spec_version = int(spec_version)
        except Exception:
            # Fallback to the default spec_version in the object.
            spec_version = getattr(self, "spec_version", None)
    else:
        spec_version = getattr(self, "spec_version", None)

    if spec_version is None:
        raise ValueError(
            "Could not determine the specification version for validation."
        )

    # Basic switch‑style validation for a few example specification versions.
    if spec_version == 1:
        required_keys = {"name", "packages"}
        missing = required_keys - inventory.keys()
        if missing:
            raise ValueError(
                f"Inventory missing required keys for spec_version 1: {missing}"
            )
        if not isinstance(inventory.get("packages"), list):
            raise TypeError("'packages' must be a list.")
    elif spec_version == 2:
        required_keys = {"name", "components"}
        missing = required_keys - inventory.keys()
        if missing:
            raise ValueError(
                f"Inventory missing required keys for spec_version 2: {missing}"
            )
        if not isinstance(inventory.get("components"), list):
            raise TypeError("'components' must be a list.")
    elif spec_version == 3:
        required_keys = {"name", "services", "config"}
        missing = required_keys - inventory.keys()
        if missing:
            raise ValueError(
                f"Inventory missing required keys for spec_version 3: {missing}"
            )
        if not isinstance(inventory.get("services"), dict):
            raise TypeError("'services' must be a dict.")
        if not isinstance(inventory.get("config"), dict):
            raise TypeError("'config' must be a dict.")
    else:
        raise ValueError(f"Unsupported or unknown spec_version {spec_version}")

    return True

def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Mapping of acceptable 'type' values to specification versions
    _TYPE_TO_VERSION = {
        "simple": 1,
        "full": 2,
        "advanced": 3,
    }

    if inventory is None or not isinstance(inventory, dict):
        # Inventory must be a dictionary; cannot validate further
        return False

    try:
        # 1. Extract spec version if requested
        if extract_spec_version:
            type_val = inventory.get("type")
            if isinstance(type_val, str) and type_val.lower() in _TYPE_TO_VERSION:
                # Use the discovered spec version
                self.spec_version = _TYPE_TO_VERSION[type_val.lower()]
            else:
                # If the type is absent or invalid, we rely on the pre‑set spec_version
                if not hasattr(self, "spec_version") or self.spec_version is None:
                    raise ValueError(
                        "Specification version cannot be determined from inventory "
                        "and no existing self.spec_version is set."
                    )

        # 2. Basic structural validation based on spec_version
        # For simplicity we support two rough schema shapes:
        #   * version 1: inventory must contain a 'hosts' list of host names (strings)
        #   * version 2 or 3: inventory must contain 'hosts' list, each host is a dict
        hosts = inventory.get("hosts")
        if hosts is None:
            raise ValueError("Inventory missing required 'hosts' key.")

        if not isinstance(hosts, list):
            raise ValueError("'hosts' must be a list.")

        if self.spec_version == 1:
            # Version 1 expects a list of strings
            for h in hosts:
                if not isinstance(h, str):
                    raise ValueError(f"Host entry '{h}' in version 1 must be a string.")
        else:
            # Versions 2 and 3 expect a list of dicts with at least a 'name' key
            for idx, h in enumerate(hosts):
                if not isinstance(h, dict):
                    raise ValueError(
                        f"Host entry at index {idx} in version {self.spec_version} "
                        f"must be a dict."
                    )
                name = h.get("name")
                if not isinstance(name, str):
                    raise ValueError(
                        f"Host dict at index {idx} missing required 'name' string."
                    )

        # 3. Additional simple verification can be added here based on spec_version
        # (e.g., presence of 'variables', 'groups', etc.) If none are needed we just
        # consider the inventory valid at this point.

        # If we successfully reach this point, the inventory is considered valid.
        return True

    except Exception as exc:
        # Log or process the exception as needed; for now we simply return False
        # to indicate the inventory failed validation. In a real system you might
        # want to raise a custom ValidationError or log details.
