                raise ValueError(f"Unable to access attribute '{attr}' for comparison: {exc}")

            # Ensure values are compatible for comparison
            try:
                if prior_val >= current_val:
                    raise ValueError(
                        f"The prior inventory's {attr} ({prior_val}) must be older than "
                        f"the current inventory's {attr} ({current_val})."
                    )
                # If we get here, the comparison succeeded and prior is valid
                return
            except TypeError:
                # Comparison not supported for these types; try next attribute
                continue

    # If we exit the loop, no suitable attribute was found or comparisons failed
    raise ValueError(
        "Could not determine if 'prior' is a valid previous version of the current inventory. "
        "Please ensure that both objects expose a comparable timestamp or version attribute."
    )

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is an object of the same type
    if not isinstance(prior, type(self)):
        raise TypeError("prior must be an instance of the same validator class")

    # Retrieve the inventory dictionaries (or equivalent attribute)
    inv_self = getattr(self, "inventory", None)
    inv_prior = getattr(prior, "inventory", None)

    if inv_self is None or inv_prior is None:
        raise ValueError("Both objects must expose an 'inventory' attribute")

    # Determine a common identifier to verify that we are comparing the same
    # inventory item. Try common key names.
    id_keys = ["id", "inventory_id", "name"]
    id_self = id_prior = None
    for key in id_keys:
        if key in inv_self and key in inv_prior:
            id_self = inv_self[key]
            id_prior = inv_prior[key]
            break

    if id_self is None or id_prior is None or id_self != id_prior:
        raise ValueError("Inventories refer to different items")

    # Determine how to compare versions. Prefer timestamps, fall back to
    # explicit numeric version fields.
    def _get_value(d, keys):
        for key in keys:
            if key in d:
                return d[key]
        return None

    ts_keys = ["last_modified", "modified", "updated_at", "timestamp", "time"]
    ver_keys = ["version", "ver", "rev"]

    ts_self = _get_value(inv_self, ts_keys)
    ts_prior = _get_value(inv_prior, ts_keys)

    ver_self = _get_value(inv_self, ver_keys)
    ver_prior = _get_value(inv_prior, ver_keys)

    # If we have timestamps that can be compared, use those
    if ts_self is not None and ts_prior is not None:
        try:
            # Assume timestamps are comparable directly (e.g., ISO strings or
            # datetime objects). If they are strings, we rely on lexicographic
            # ordering which works for ISO format.
            if not (ts_prior < ts_self):
                raise ValueError("Prior inventory is not older than the current inventory")
        except Exception as e:
            raise ValueError(f"Error comparing timestamps: {e}")
    elif ver_self is not None and ver_prior is not None:
        # Compare numeric versions if available
        try:
            if not (ver_prior < ver_self):
                raise ValueError("Prior inventory version is not less than the current inventory version")
        except Exception as e:
            raise ValueError(f"Error comparing version numbers: {e}")
    else:
        # Unable to determine ordering
        raise ValueError("Insufficient data to confirm that prior is an earlier version")

    # All checks passed
    return True

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type check
    try:
