    except NameError:
        raise RuntimeError("InventoryValidator class must be available in the context")

    if prior is None:
        raise ValueError("The prior inventory must not be None")

    if not isinstance(prior, InventoryValidator):
        raise TypeError(f"Expected 'prior' to be an InventoryValidator, got {type(prior).__name__}")

    # Ensure we're not comparing the same object
    if prior is self:
        raise ValueError("The prior inventory cannot be the same instance as the current inventory")

    # Helper to validate attribute presence
    def _require_attr(obj, attr_name):
        if not hasattr(obj, attr_name):
            raise AttributeError(f"Required attribute '{attr_name}' missing from {type(obj).__name__}")

    # Inventory ID check (identifying the same inventory resource)
    _require_attr(self, "inventory_id")
    _require_attr(prior, "inventory_id")
    if self.inventory_id != prior.inventory_id:
        raise ValueError(f"Inventory IDs differ: current={self.inventory_id!r}, prior={prior.inventory_id!r}")

    # Version comparison
    _require_attr(self, "version")
    _require_attr(prior, "version")
    try:
        if prior.version >= self.version:
            raise ValueError(
                f"Prior version ({prior.version!r}) must be less than current version ({self.version!r})"
            )
    except TypeError:
        raise TypeError(
            f"Version attributes must be comparable: self.version={self.version!r}, prior.version={prior.version!r}"
        )

    # Optional timestamp comparison for additional strictness
    if hasattr(self, "timestamp") and hasattr(prior, "timestamp"):
        try:
            if prior.timestamp >= self.timestamp:
                raise ValueError(
                    f"Prior timestamp ({prior.timestamp!r}) must be earlier than current timestamp ({self.timestamp!r})"
                )
        except TypeError:
            raise TypeError(
                f"Timestamp attributes must be comparable: self.timestamp={self.timestamp!r}, prior.timestamp={prior.timestamp!r}"
            )

    # If all checks pass, no exception is raised (validation successful)
    return None

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type and identity checks
    if prior is None:
        raise ValueError("prior cannot be None")
    if prior is self:
        raise ValueError("prior cannot be the same as the current object")
    if not isinstance(prior, type(self)):
        raise TypeError(
            f"prior must be an instance of {type(self).__name__}, "
            f"got {type(prior).__name__}"
        )

    # Ensure both objects have an 'inventory' attribute
    if getattr(self, "inventory", None) is None:
        raise ValueError("current object lacks an 'inventory' attribute")
    if getattr(prior, "inventory", None) is None:
        raise ValueError("prior object lacks an 'inventory' attribute")

    self_inv = self.inventory
    prior_inv = prior.inventory

    # Prefer a 'version' attribute, otherwise fall back to 'timestamp'
    self_version = getattr(self_inv, "version", None)
    prior_version = getattr(prior_inv, "version", None)

    if self_version is None or prior_version is None:
        # Try timestamp comparison if versions are missing
        self_ts = getattr(self_inv, "timestamp", None)
        prior_ts = getattr(prior_inv, "timestamp", None)
        if self_ts is None or prior_ts is None:
            raise ValueError(
                "Both inventory objects must provide either a 'version' or 'timestamp' "
                "attribute for comparison"
            )
        # Use timestamp as a fallback comparison
        if prior_ts >= self_ts:
            raise ValueError(
                f"Prior timestamp ({prior_ts}) must be earlier than current timestamp "
                f"({self_ts})"
            )
    else:
        # Numeric or comparable values
        try:
            if prior_version >= self_version:
                raise ValueError(
                    f"Prior version ({prior_version}) must be less than current "
                    f"version ({self_version})"
                )
        except TypeError:
            # If comparison is not possible, raise an informative error
            raise TypeError(
                f"Cannot compare versions: prior_version={prior_version!r}, "
                f"self_version={self_version!r}. "
                "Ensure both are comparable (e.g., integers or strings)."
            )

    # Optional: ensure the same inventory identifier if present
    self_id = getattr(self_inv, "id", None)
    prior_id = getattr(prior_inv, "id", None)
    if self_id is not None and prior_id is not None and self_id != prior_id:
        raise ValueError(
            f"Inventory identifiers differ: current id={self_id}, prior id={prior_id}"
        )

    return True

