                # Hash values must be strings
                if not isinstance(hash_value, str):
                    raise TypeError(f"Hash value for file '{file_path}' must be a string, got {type(hash_value).__name__}")

                if not file_path:
                    raise ValueError(f"Fixity entry contains an empty file path for algorithm '{algo}'.")

                if not hash_value:
