                # Check that the file is referenced in the manifest
                if file_path not in manifest_set:
                    raise ValueError(f"File '{file_path}' referenced in fixity for algorithm '{algo}' is not present in the manifest.")

                # Basic hex format validation for hash values
                if not all(c in '0123456789abcdefABCDEF' for c in hash_value):
                    raise ValueError(f"Hash value for file '{file_path}' under algorithm '{algo}' contains non-hex characters.")

        # If all checks pass, return True to indicate successful validation
        return True

