        if manifest_files is None:
            raise ValueError("Manifest files list cannot be None")
        if not isinstance(manifest_files, (list, set, tuple)):
            raise ValueError(f"Manifest files must be a list/tuple/set, got {type(manifest_files).__name__}")

        manifest_set = set(map(str, manifest_files))  # Ensure all entries are strings

        # Iterate over each algorithm in the fixity block
        for algo_name, algo_entries in fixity.items():
            if not isinstance(algo_entries, dict):
                raise ValueError(
                    f"Entries for algorithm '{algo_name}' must be a dict of file->checksum, got {type(algo_entries).__name__}"
                )
            for file_path, checksum in algo_entries.items():
                # Verify file_path is a string
                if not isinstance(file_path, str):
                    raise ValueError(
                        f"File path '{file_path}' (type {type(file_path).__name__}) for algorithm '{algo_name}' must be a string"
                    )
                # File must be present in the manifest
                if file_path not in manifest_set:
                    raise ValueError(
                        f"File '{file_path}' referenced in fixity block for algorithm '{algo_name}' "
                        f"is not listed in the manifest files"
                    )
                # Check checksum value is a non-empty string
                if not isinstance(checksum, str) or not checksum:
                    raise ValueError(
                        f"Checksum for file '{file_path}' under algorithm '{algo_name}' must be a non-empty string"
                    )

        # All checks passed
        return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise TypeError("fixity must be a mapping (dict)")

    if 'files' not in fixity:
        raise ValueError("fixity block is missing required 'files' key")

    files = fixity['files']

    if not isinstance(files, list):
        raise TypeError("The 'files' entry in fixity must be a list")

    # Ensure manifest_files is iterable of strings
    try:
        manifest_set = set(manifest_files)
    except Exception as exc:
        raise TypeError("manifest_files must be an iterable of file names") from exc

    # Validate each file entry
    for idx, f in enumerate(files):
        if not isinstance(f, str):
            raise TypeError(f"File entry at position {idx} in fixity is not a string")
        if f not in manifest_set:
            raise ValueError(f"File '{f}' referenced in fixity block is not present in the manifest")

    # Optional: check for duplicates
    duplicates = set([x for x in files if files.count(x) > 1])
    if duplicates:
        raise ValueError(f"Duplicate file references found in fixity block: {', '.join(sorted(duplicates))}")

def validate_fixity(self, fixity, manifest_files):
        """
        Validate the fixity block in an inventory.

        Parameters
        ----------
        fixity : dict or None
            The fixity block extracted from an inventory. It may be a mapping of
            file names to checksums, or a dictionary containing a ``files`` key
            whose value is a list of dictionaries each describing a file.
        manifest_files : Iterable[str]
            An iterable of file names that appear in the manifest. All files
            referenced in the fixity block must appear in this iterable.

        Raises
        ------
        ValueError
            If the fixity block is malformed or references files not in the
            manifest.
        """
        # Normalise manifest entries to a set for fast lookup
        if manifest_files is None:
            raise ValueError("Manifest files must be provided")
        try:
            manifest_set = set(manifest_files)
        except TypeError as exc:
            raise ValueError("manifest_files must be an iterable of strings") from exc

        if fixity is None:
            raise ValueError("Fixity block is missing")

        if not isinstance(fixity, dict):
            raise ValueError(f"Fixity block must be a dictionary, got {type(fixity).__name__}")

        # Determine fixity format
        entries = None
        if 'files' in fixity:
            files_val = fixity['files']
            if not isinstance(files_val, list):
                raise ValueError("'files' key must map to a list")
            entries = files_val
        else:
            # Treat the top-level mapping as file -> checksum
            if all(isinstance(k, str) and isinstance(v, str) for k, v in fixity.items()):
                entries = [{'name': k, 'checksum': v} for k, v in fixity.items()]
            else:
                raise ValueError("Unrecognised fixity format: expected 'files' list or a file->checksum dict")

        # Validate each entry
        required_keys = {'name', 'checksum'}
        for idx, entry in enumerate(entries):
            if not isinstance(entry, dict):
                raise ValueError(f"Entry {idx} in fixity block must be a dict, got {type(entry).__name__}")

            # Accept either 'name' or 'file' as key for the file name
            file_key = None
            if 'name' in entry:
                file_key = 'name'
            elif 'file' in entry:
                file_key = 'file'
            else:
                raise ValueError(f"Entry {idx} missing required file identifier ('name' or 'file')")

            if required_keys - entry.keys():
                missing = required_keys - entry.keys()
                raise ValueError(f"Entry {idx} is missing required keys: {missing}")

            file_name = entry[file_key]
            if file_name not in manifest_set:
                raise ValueError(f"File '{file_name}' referenced in fixity block not present in the manifest")

        return True

