def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename.

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    source : Any
        Unused in this implementation but kept for compatibility.
    xmls : list
        List of XML file paths.
    files : list
        List of other file paths.

    Returns
    -------
    dict
        Keys are the base names of the XML files (without extension).
        Values are dicts with keys:
            'xml'   : the full path of the XML file.
            'files' : list of file paths that share the same base name.
    """
    # Helper to extract basename without extension, handling both '/' and '\'
    def _base_no_ext(path: str) -> str:
        # Split on path separators
        for sep in ('/', '\\'):
            if sep in path:
                path = path.rsplit(sep, 1)[-1]
        # Remove extension
        if '.' in path:
            return path.rsplit('.', 1)[0]
        return path

    result = {}
    try:
        if not isinstance(xmls, (list, tuple)):
            raise TypeError("xmls must be a list or tuple of file paths")
        if not isinstance(files, (list, tuple)):
            raise TypeError("files must be a list or tuple of file paths")
        # Build mapping from base name to xml path
        xml_map = {}
        for xml_path in xmls:
            if not isinstance(xml_path, str):
                continue
            base = _base_no_ext(xml_path)
            xml_map[base] = xml_path

        # Group files by matching base name
        for base, xml_path in xml_map.items():
            matched_files = []
            for file_path in files:
                if not isinstance(file_path, str):
                    continue
                if _base_no_ext(file_path) == base:
                    matched_files.append(file_path)
            result[base] = {
                'xml': xml_path,
                'files': matched_files
            }
    except Exception as exc:
        # In case of unexpected errors, return empty dict and optionally log
        # Since we cannot import logging, we just silently return empty result
        return {}
    return result

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os

    # Initial empty dictionary to hold data about each package
    packages = {}

    try:
        if not isinstance(folder, str):
            raise TypeError("folder must be a string path")

        if not os.path.isdir(folder):
            raise FileNotFoundError(f"Directory '{folder}' does not exist or is not a directory")

        # Iterate over all entries in the folder
        for entry in os.listdir(folder):
            full_path = os.path.join(folder, entry)

            # Skip if not a file (ignore subdirectories)
            if not os.path.isfile(full_path):
                continue

            base_name, ext = os.path.splitext(entry)
            ext_lower = ext.lower()
            base_key = base_name.lower()  # use lowercase to normalize keys

            # Create a new entry for this base if it doesn't exist
            if base_key not in packages:
                packages[base_key] = {"xml": None, "assets": []}

            # If the file is an XML file, store its path
            if ext_lower == ".xml":
                packages[base_key]["xml"] = full_path
            else:
                packages[base_key]["assets"].append(full_path)

    except Exception:
        # In case of any error (e.g., permission issues), return an empty dict
        return {}

    # Clean up packages with no XML and no assets (no valid files)
    valid_packages = {}
    for key, info in packages.items():
        if info["xml"] or info["assets"]:
            valid_packages[key] = info

    return valid_packages

def _eval_file(prefix, file_path):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    file_path : str
        file path suitable for distinguishing type

    Returns
    -------
    dict
        Mapping with key ``prefix`` to a dict containing ``type`` and
        ``filepath`` of the analyzed file.
    """
    # Guard agains bad input
    if not isinstance(prefix, str) or not isinstance(file_path, str):
        return {}

    if not file_path.strip():
        return {}

    try:
        import os

        # Extract the base name and extension
        base_name = os.path.basename(file_path)
        _, ext = os.path.splitext(base_name)
        ext = ext.lower()

        # Define known asset extensions
        asset_exts = {'.mp4', '.mp3', '.wav', '.jpg', '.jpeg', '.png',
                      '.gif', '.bmp', '.pdf', '.doc', '.docx', '.xlsx'}

        # Determine file type
        if 'rendition' in base_name.lower() or base_name.lower().startswith('rend_'):
            file_type = 'rendition'
        elif ext in asset_exts:
            file_type = 'asset'
        else:
            # Default fallback: if the file name contains 'asset' assume asset,
            # otherwise default to asset to avoid misclassification.
            file_type = 'asset' if 'asset' in base_name.lower() else 'rendition'

        # Build the result dictionary
        result = {
            prefix: {
                'type': file_type,
                'filepath': os.path.abspath(file_path)
            }
        }
        return result

    except Exception:
        # In case of any unexpected error, return an empty dict
        return {}

def add_rendition(self, lang, file_path):
    """
    {
        "original": "artigo02.pdf",
        "en": "artigo02-en.pdf",
    }
    """
    # Basic validation for parameters
    if not isinstance(lang, str):
        raise TypeError("lang must be a string")
    if not isinstance(file_path, str):
        raise TypeError("file_path must be a string")
    if not lang.strip():
        raise ValueError("lang cannot be empty or whitespace")
    if not file_path.strip():
        raise ValueError("file_path cannot be empty or whitespace")

    # Ensure the renditions dict exists on the instance
    renditions = getattr(self, "renditions", {})
    # Add or replace the rendition for the specified language
    renditions[lang] = file_path
    # Store back on the instance
    setattr(self, "renditions", renditions)

    return renditions

def add_rendition(self, lang, file_path):
        """
        {
            "original": "artigo02.pdf",
            "en": "artigo02-en.pdf",
        }
        """
        # Validate language input
        if not isinstance(lang, str) or not lang.strip():
            raise ValueError("lang must be a non-empty string")
        lang = lang.strip()

        # Validate file_path input
        if file_path is None:
            raise ValueError("file_path cannot be None")
        if isinstance(file_path, (bytes, bytearray)):
            # Convert bytes to string if possible
            try:
                file_path = file_path.decode('utf-8')
            except Exception as e:
                raise ValueError("file_path bytes could not be decoded to UTF-8") from e
        if not isinstance(file_path, str) or not file_path.strip():
            raise ValueError("file_path must be a non-empty string or bytes")
        file_path = file_path.strip()

        # Initialize renditions dict if it doesn't exist
        if not hasattr(self, "renditions") or not isinstance(getattr(self, "renditions", None), dict):
            self.renditions = {}
        # Store the rendition
        self.renditions[lang] = file_path

        # If the language denotes the original document, store it in a separate attribute
        if lang.lower() == "original":
            self.original = file_path

        # Optionally return True to indicate success
        return True

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    result = {}
    try:
        zip_file = __import__('zipfile').ZipFile(zip_path, 'r')
    except Exception:
        return result
    try:
        # First pass: find XML files and store their content
        for name in zip_file.namelist():
            if name.lower().endswith('.xml'):
                base = __import__('os').path.splitext(__import__('os').path.basename(name))[0]
                try:
                    data = zip_file.read(name)
                except Exception:
                    data = None
                result.setdefault(base, {})['xml'] = data

        # Second pass: group other files that share the same basename
        for name in zip_file.namelist():
            if name.lower().endswith('.xml'):
                continue
            base = __import__('os').path.splitext(__import__('os').path.basename(name))[0]
            if base in result:
                try:
                    data = zip_file.read(name)
                except Exception:
                    data = None
                result[base].setdefault('files', {})[name] = data
    finally:
        try:
            zip_file.close()
        except Exception:
            pass
    return result

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    try:
        import zipfile
        import os
    except Exception:
        return {}

    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as z:
            for entry in z.infolist():
                if entry.is_dir():
                    continue
                rel_path = entry.filename
                # Determine grouping key from the basename of the file (exclude extension)
                base_name = os.path.splitext(os.path.basename(rel_path))[0]
                try:
                    raw_bytes = z.read(entry)
                except Exception:
                    # Skip files that can't be read
                    continue
                # Attempt to decode as UTF-8, fallback to binary string if needed
                try:
                    content = raw_bytes.decode('utf-8')
                except Exception:
                    content = raw_bytes.decode('utf-8', errors='ignore')
                if base_name not in result:
                    result[base_name] = {}
                result[base_name][rel_path] = content
    except Exception:
        # If zip file cannot be opened or read, return an empty dict
        return {}
    return result

