        # If it is an element (has .text or .text_content)
        try:
            # lxml Element
            if hasattr(first_match, "text") and isinstance(first_match, (type(node).__mro__[0]),):
                text = first_match.text
                if text is None:
                    # try text_content for lxml.html
                    if hasattr(first_match, "text_content"):
                        text = first_match.text_content()
                    else:
                        text = ""
                return text.strip() if text else None
        except Exception:
            pass

        # If it's a string or other type
        try:
            return str(first_match).strip()
        except Exception:
            continue

    return None

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if not isinstance(pubdate_xpaths, (list, tuple)):
        # Não é uma lista de caminhos, retorno None
        return None
    try:
        for xpath_expr in pubdate_xpaths:
            if not isinstance(xpath_expr, str):
                # Caminho inválido, ignora
                continue
            try:
                # Tenta avaliar o XPath no nó fornecido
                result = node.xpath(xpath_expr)
                if not result:
                    continue
                # Se o resultado for uma lista de elementos
                first = result[0]
                # Se for elemento XML/HTML
                if hasattr(first, 'text'):
                    txt = first.text
                    if txt is not None:
                        return txt.strip()
                # Se for string diretamente retornada pelo XPath
                if isinstance(first, str):
                    return first.strip()
                # Caso contrário, converte o primeiro item em string
                return str(first).strip()
            except Exception:
                # Se houver erro no XPath, passa para o próximo
                continue
    except Exception:
        # Erro inesperado, devolve None
        return None
    return None

def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    import re
    try:
        # Se a entrada for um objeto XML/Element, extrair seu texto.
        if hasattr(issue, 'text'):
            content = str(issue.text)
        else:
            content = str(issue)

        content = content.strip()
        if not content:
            return (None, None)

        # Normaliza espaços
        content = re.sub(r'\s+', ' ', content)

        # Busca todos os números inteiros na string
        numbers = [int(num) for num in re.findall(r'\d+', content)]

        number = numbers[0] if numbers else None
        suppl = numbers[1] if len(numbers) >= 2 else None

        return (number, suppl)
    except Exception:
        # Em caso de erro inesperado, devolve valores None
        return (None, None)

