        """
        try:
            # Validate indent value
            if not isinstance(indent, int) or indent < 0:
                raise ValueError("indent must be a non-negative integer")
            # If the object exposes a custom pretty method, use it
            if hasattr(self, "__pretty__") and callable(getattr(self, "__pretty__")):
                return self.__pretty__(indent=indent, debug=debug)
            # Attempt to use the object's __dict__ for representation
            data = getattr(self, "__dict__", None)
            if data is not None:
                import pprint
                return pprint.pformat(data, indent=indent)
            # For built‑in containers use pprint
            if isinstance(self, (list, tuple, set, dict)):
                import pprint
                return pprint.pformat(self, indent=indent)
            # Fallback to JSON serialization when possible
            try:
                import json
                return json.dumps(self, indent=indent, default=str)
            except Exception:
                pass
            # Final fallback: use the standard representation
            return repr(self)
        except Exception as e:
            if debug:
                import traceback
                return f"Error in pretty(): {e}\n{traceback.format_exc()}"
            return f"Error in pretty(): {e}"

