def on(self, hook):
    """
    Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    # Validate the hook argument
    if hook is None:
        raise ValueError("hook cannot be None")
    if not isinstance(hook, (str, int, tuple, frozenset)):
        # allow any hashable object; check hashability
        try:
            hash(hook)
        except TypeError:
            raise TypeError(f"hook must be hashable, got {type(hook).__name__}")

    # Ensure there is a registry dictionary on the instance
    if not hasattr(self, "_hook_registry"):
        try:
            self._hook_registry = {}
        except Exception as e:
            raise RuntimeError("Failed to initialize hook registry") from e

    # Initialize the list for this hook if not already present
    if hook not in self._hook_registry:
        self._hook_registry[hook] = []

    def decorator(func):
        """Inner decorator that registers the function as a listener for the hook."""
        if not callable(func):
            raise TypeError(f"The listener must be a callable, got {type(func).__name__}")

        try:
            self._hook_registry[hook].append(func)
        except Exception as e:
            raise RuntimeError(f"Failed to register handler for hook {hook}") from e

        # Return the original function unchanged
        return func

    return decorator

def on(self, hook):
        """Decorator function to add a new handler to the registry.

        Args:
            hook (HookType): Hook attribute for which to register the handler.

        Returns:
            callable: Decorator for registering listeners for the specified
            hook.
        """
        # Validate that the hook is hashable (required for dict keys)
        try:
            hash(hook)
        except Exception:
            raise TypeError("hook must be hashable") from None

        # Initialize the registry if it does not exist
        registry = getattr(self, "_hook_registry", None)
        if registry is None:
            registry = {}
            setattr(self, "_hook_registry", registry)

        # Ensure a list exists for this hook
        if hook not in registry:
            registry[hook] = []

        def decorator(func):
            """Register a callable as a handler for the specified hook."""
            if not callable(func):
                raise TypeError("handler must be callable")
            try:
                registry[hook].append(func)
            except Exception as exc:
                # In case something goes wrong during registration,
                # do not leave incomplete state; raise a clear error.
                raise RuntimeError(
                    f"Failed to register handler for hook {hook!r}"
                ) from exc
            return func

        return decorator

def base_config(user, etcd_host="localhost", etcd_port=2379):
    """
    Creates a configuration with some simple parameters, which have a default value
    that can be set.

    Args:
        user (str): the name of the user for the static authentication
        etcd_host (str): the host for the database.
        etcd_port (int): the port for the database.

    Returns:
        dict: the created configuration.
    """
    # Validate `user`
    if not isinstance(user, str):
        raise TypeError(f"Expected `user` to be a string, got {type(user).__name__}")
    if not user.strip():
        raise ValueError("`user` must be a non-empty string")

    # Validate `etcd_host`
    if not isinstance(etcd_host, str):
        raise TypeError(f"Expected `etcd_host` to be a string, got {type(etcd_host).__name__}")

    # Validate `etcd_port`
    if not isinstance(etcd_port, int):
        raise TypeError(f"Expected `etcd_port` to be an int, got {type(etcd_port).__name__}")
    if not (0 < etcd_port <= 65535):
        raise ValueError("`etcd_port` must be between 1 and 65535")

    # Construct the configuration dictionary
    config = {
        "auth": {
            "type": "static",
            "user": user
        },
        "etcd": {
            "host": etcd_host,
            "port": etcd_port
        }
    }

    return config

