def get_versions():
    """
    Get version information or return default if unable to do so.

    Returns:
        dict: Mapping of package names to their version strings. An empty dict
              is returned if all attempts to retrieve metadata fail.
    """
    # Attempt to use the modern importlib.metadata API (Python 3.8+)
    try:
        from importlib.metadata import distributions
        package_versions = {}
        for dist in distributions():
            # Some distributions may not have a 'Name' metadata entry; skip them
            try:
                name = dist.metadata.get('Name')
                if not name:
                    continue
                package_versions[name] = dist.version or "unknown"
            except Exception:
                # Skip any distribution that causes an unexpected error
                continue
        if package_versions:
            return package_versions
    except Exception:
        # Fallback to pkg_resources if importlib.metadata is unavailable or fails
        pass

    # Fallback to pkg_resources (part of setuptools)
    try:
        import pkg_resources
        package_versions = {}
        for dist in pkg_resources.working_set:
            try:
                package_versions[dist.project_name] = dist.version or "unknown"
            except Exception:
                continue
        return package_versions
    except Exception:
        # As a last resort, return an empty dictionary
        pass

    return {}

def get_versions():
    """
    Get version information from the installed distribution or package metadata.
    If unable to determine a version, returns a default placeholder string.

    Returns:
        dict: A dictionary containing the key 'version' with the package
        version or a default '0.0.0' if the version cannot be determined.
    """
    import sys
    import os

    # Default version to use when resolution fails
    default_version = "0.0.0"

    # Inner helper to try retrieving version via importlib.metadata
    try:
        # importlib.metadata is available in Python 3.8+
        import importlib.metadata
        MetadataVersionError = importlib.metadata.PackageNotFoundError
    except Exception:
        # Fallback for older Python (should not be needed in most CI environments)
        import importlib_metadata as importlib
        MetadataVersionError = importlib.PackageNotFoundError

    # Determine a candidate package name
    module = sys.modules.get(__name__)
    if module:
        pkg_name = module.__package__ or module.__name__.split(".")[0]
    else:
        pkg_name = __name__.split(".")[0]

    # Attempt to fetch the version via importlib.metadata
    try:
        version = importlib.metadata.version(pkg_name)
        if version:
            return {"version": version}
    except MetadataVersionError:
        pass
    except Exception:
        pass  # Any other exceptions are swallowed to allow fallback

    # Fallback 1: try pkg_resources (part of setuptools)
    try:
        from pkg_resources import get_distribution
        version = get_distribution(pkg_name).version
        if version:
            return {"version": version}
    except Exception:
        pass

    # Fallback 2: read a local VERSION file if present
    try:
        # Resolve the directory containing the current file
        my_dir = os.path.abspath(os.path.dirname(__file__))
        version_path = os.path.join(my_dir, "VERSION")
        if os.path.exists(version_path):
            with open(version_path, "r", encoding="utf-8") as vf:
                content = vf.read().strip()
                if content:
                    return {"version": content}
    except Exception:
        pass

    # Fallback 3: read environment variable (optional)
    try:
        env_version = os.getenv("PACKAGE_VERSION")
        if env_version:
            return {"version": env_version}
    except Exception:
        pass

    # If all attempts fail, return the default
    return {"version": default_version}

