            try:
                return style.format(*pieces_str)
            except Exception as exc:
                raise ValueError(f"Error applying format string: {exc}")

        # Fallback: treat the string as a custom delimiter if it is a single character
        if len(style) == 1:
            return style.join(pieces_str)

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    try:
        # Validate pieces
        if not isinstance(pieces, (list, tuple)):
            raise ValueError("pieces must be a list or tuple")
        if len(pieces) == 0:
            raise ValueError("pieces must contain at least one component")

        # Default style if None
        if style is None:
            style = "semantic"

        # Convert all pieces to string
        parts = [str(p) for p in pieces]

        if style == "semantic":
            # Handle major.minor.patch
            major = parts[0]
            minor = parts[1] if len(parts) > 1 else "0"
            patch = parts[2] if len(parts) > 2 else "0"
            base = f"{major}.{minor}.{patch}"
            if len(parts) > 3:
                suffix = "-" + "-".join(parts[3:])
                return base + suffix
            return base

        elif style == "pep440":
            # Base same as semantic
            major = parts[0]
            minor = parts[1] if len(parts) > 1 else "0"
            patch = parts[2] if len(parts) > 2 else "0"
            base = f"{major}.{minor}.{patch}"
            if len(parts) > 3:
                suffix = "+" + "+".join(parts[3:])
                return base + suffix
            return base

        elif style == "plain":
            return ".".join(parts)

        else:
            raise ValueError(f"Unsupported style: {style}")

    except Exception as exc:
        raise ValueError(f"Error rendering version: {exc}") from exc

