def register_vcs_handler(vcs, method=None):
    """Create decorator to mark a method as the handler of a VCS.

    The decorator can be used in two ways::

        @register_vcs_handler('git')
        def git_handler(...):
            ...

    or directly::

        def git_handler(...):
            ...
        register_vcs_handler('git', git_handler)

    The function is stored in a registry attached to the decorator
    function itself, accessible via ``register_vcs_handler._registry``.
    """
    # Allow the decorator to be called with or without the handler
    if method is None:
        # Return a new decorator that expects the handler
        return lambda f: register_vcs_handler(vcs, f)

    # Validate inputs
    if not isinstance(vcs, str):
        raise TypeError(f"VCS name must be a string, got {type(vcs).__name__}")
    if not callable(method):
        raise TypeError(f"Handler must be callable, got {type(method).__name__}")

    # Create registry attribute if it does not exist
    if not hasattr(register_vcs_handler, "_registry"):
        register_vcs_handler._registry = {}

    # Store the handler in the registry
    register_vcs_handler._registry[vcs] = method

    return method

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    # Validate input types
    if not isinstance(vcs, str):
        raise TypeError("vcs must be a string")
    if not callable(method):
        raise TypeError("method must be a callable")
    # Initialise the registry on the decorator function if not already present
    if not hasattr(register_vcs_handler, "_registry"):
        register_vcs_handler._registry = {}
    # Register the handler, allowing overriding of existing ones
    register_vcs_handler._registry[vcs] = method
    return method

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """
        Validate storage root hierarchy.

        Returns:
            tuple(int, int): (num_objects, good_objects)
                num_objects - number of objects checked
                good_objects - number of objects checked that were found to be valid
        """
        # Defensive: determine root path
        root = getattr(self, 'root_path', None)
        if root is None:
            # If no root, nothing to validate
            return 0, 0

        # Ensure root is a pathlib.Path or convertible
        try:
            from pathlib import Path
            root_path = Path(root)
        except Exception:
            # invalid root, return zeros
            return 0, 0

        if not root_path.exists() or not root_path.is_dir():
            # invalid directory
            return 0, 0

        num_objects = 0
        good_objects = 0

        # Iterate over entries in the root directory recursively
        for entry in root_path.rglob('*'):
            if not entry.is_file() and not entry.is_dir():
                continue  # skip special files
            num_objects += 1

            is_valid = True

            # Validate objects: attempt to open/read if file
            if validate_objects:
                if entry.is_file():
                    try:
                        with entry.open('rb') as f:
                            f.read(1)  # just attempt a read
                    except Exception as exc:
                        is_valid = False
                        if show_warnings:
                            try:
                                print(f"WARNING: Failed to read '{entry}': {exc}")
                            except Exception:
                                pass  # silence any print errors

            # Check digests: compute SHA256 and compare to a stored digest if exists
            if is_valid and check_digests:
                if entry.is_file():
                    try:
                        import hashlib
                        sha = hashlib.sha256()
                        with entry.open('rb') as f:
                            for chunk in iter(lambda: f.read(8192), b''):
                                sha.update(chunk)
                        digest = sha.hexdigest()
                        # Assume there might be a .digest file alongside
                        digest_file = entry.with_suffix(entry.suffix + '.digest')
                        if digest_file.exists():
                            try:
                                stored = digest_file.read_text().strip()
                                if stored.lower() != digest.lower():
                                    is_valid = False
                                    if show_warnings:
                                        try:
                                            print(f"WARNING: Digest mismatch for '{entry}'. Expected {stored}, got {digest}")
                                        except Exception:
                                            pass
                            except Exception as exc:
                                is_valid = False
                                if show_warnings:
                                    try:
                                        print(f"WARNING: Could not read digest file '{digest_file}': {exc}")
                                    except Exception:
                                        pass
                    except Exception as exc:
                        is_valid = False
                        if show_warnings:
                            try:
                                print(f"WARNING: Could not compute digest for '{entry}': {exc}")
                            except Exception:
                                pass

            if is_valid:
                good_objects += 1

        return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Parameters
    ----------
    validate_objects : bool, optional
        If True, each object will be passed to its ``is_valid`` method if available.
    check_digests : bool, optional
        If True, each object will be passed to its ``check_digest`` method if available.
    show_warnings : bool, optional
        If True, print warnings when an object fails validation or digest check.

    Returns
    -------
    tuple(int, int)
        num_objects - number of objects checked
        good_objects - number of objects that passed all enabled checks
    """
    num_objects = 0
    good_objects = 0

    # Helper to safely get children of an object
    def _get_children(obj):
        try:
            # Common patterns for child containers
            if hasattr(obj, "children"):                  # list or tuple
                return obj.children
            if hasattr(obj, "get_children"):
                return obj.get_children()
            if isinstance(obj, dict):
                return obj.values()
            if isinstance(obj, (list, tuple)):
                return obj
        except Exception:
            pass
        return []

    # Helper to run validation checks on a single object
    def _check_object(obj):
        nonlocal num_objects, good_objects
        num_objects += 1
        is_good = True

        if validate_objects:
            try:
                # Some objects may expose a 'is_valid' method, otherwise assume True
                if hasattr(obj, "is_valid"):
                    if not obj.is_valid():
                        is_good = False
                elif hasattr(obj, "validate"):
                    if not obj.validate():
                        is_good = False
            except Exception as exc:
                is_good = False
                if show_warnings:
                    name = getattr(obj, "name", str(obj))
                    print(f"Warning: validation error for {name}: {exc}")

        if is_good and check_digests:
            try:
                if hasattr(obj, "check_digest"):
                    if not obj.check_digest():
                        is_good = False
                elif hasattr(obj, "checksum_valid"):
                    if not obj.checksum_valid():
                        is_good = False
            except Exception as exc:
                is_good = False
                if show_warnings:
                    name = getattr(obj, "name", str(obj))
                    print(f"Warning: digest check error for {name}: {exc}")

        if is_good:
            good_objects += 1
        else:
            if show_warnings:
                name = getattr(obj, "name", str(obj))
                print(f"Warning: object {name} failed validation/digest check")

    # Gather root objects; handle common storage root patterns
    try:
        if hasattr(self, "root"):
            roots = [_self.root for _self in [self]]  # just add root once
        else:
            roots = []

        # If no explicit root, try to use the instance itself as root
        if not roots:
            roots = [self]
    except Exception:
        # If any problem retrieving roots, return zeros
        return (0, 0)

    # Traverse the hierarchy depth‑first or breadth‑first
    stack = []
    for root in roots:
        stack.append(root)

    while stack:
        current = stack.pop()
        _check_object(current)
        # Add children to stack for further processing
        children = _get_children(current)
        for child in children:
            stack.append(child)

    return (num_objects, good_objects)

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    try:
        import pathlib
        import hashlib
        import warnings

        root = getattr(self, "root", None) or getattr(self, "storage_root", None)
        if root is None:
            raise ValueError("Storage root is not defined in the object.")
        root_path = pathlib.Path(root)
        if not root_path.is_dir():
            raise FileNotFoundError(f"Storage root '{root_path}' does not exist or is not a directory.")

        num_objects = 0
        good_objects = 0

        for path in root_path.rglob("*"):
            if path.is_file():
                num_objects += 1
                is_valid = True
                # Basic object validation: try opening the file
                if validate_objects:
                    try:
                        with path.open("rb") as f:
                            # read first few bytes to ensure file can be read
                            f.read(1024)
                    except Exception as exc:
                        is_valid = False
                        if show_warnings:
                            warnings.warn(f"Failed to read '{path}': {exc}")

                # Digest validation: compare against a sidecar .sha256 file if present
                if is_valid and check_digests:
                    digest_path = path.with_suffix(path.suffix + ".sha256")
                    if digest_path.is_file():
                        try:
                            stored_digest = digest_path.read_text().strip()
                            # Compute SHA-256 of the file
                            sha256 = hashlib.sha256()
                            with path.open("rb") as f:
                                for chunk in iter(lambda: f.read(8192), b""):
                                    sha256.update(chunk)
                            computed_digest = sha256.hexdigest()
                            if computed_digest != stored_digest:
                                is_valid = False
                                if show_warnings:
                                    warnings.warn(f"Digest mismatch for '{path}'. "
                                                   f"Expected {stored_digest}, got {computed_digest}")
                        except Exception as exc:
                            is_valid = False
                            if show_warnings:
                                warnings.warn(f"Error computing digest for '{path}': {exc}")

                if is_valid:
                    good_objects += 1

        return num_objects, good_objects

    except Exception as error:
        # Log the error and re-raise to maintain visibility of failure
        if hasattr(self, "logger"):
            try:
                self.logger.error(f"Error during hierarchy validation: {error}")
            except Exception:
                pass
        # Use print as a fallback if logger is not available
        try:
            print(f"[validate_hierarchy] Error: {error}")
        except Exception:
            pass
        # Re-raise the original exception for upstream handling
        raise

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Ensure we have a collection of objects; default to empty list if not present
    objects = getattr(self, 'objects', None)
    if objects is None:
        num_objects = 0
        good_objects = 0
        if show_warnings:
            print("Warning: No 'objects' attribute found; nothing to validate.")
        return num_objects, good_objects

    # Ensure objects is iterable
    try:
        iterator = iter(objects)
    except TypeError:
        if show_warnings:
            print("Warning: 'objects' attribute is not iterable; cannot validate.")
        return 0, 0

    num_objects = 0
    good_objects = 0

    # Import hashlib only if needed
    hashlib = None
    if check_digests:
        try:
            import hashlib as _hashlib
            hashlib = _hashlib
        except ImportError:
            if show_warnings:
                print("Warning: hashlib module could not be imported; skipping digest checks.")
            hashlib = None

    for obj in iterator:
        num_objects += 1
        is_valid = True

        # Validate object if required
        if validate_objects:
            try:
                if hasattr(obj, 'validate'):
                    val_result = obj.validate()
                    if isinstance(val_result, bool):
                        is_valid = val_result
                    else:
                        # If validate returns non-boolean, interpret truthiness
                        is_valid = bool(val_result)
                else:
                    # No explicit validate method; assume object is valid
                    is_valid = True
            except Exception as e:
                is_valid = False
                if show_warnings:
                    print(f"Warning: Object {obj} validation raised exception: {e}")

        # Digest check if enabled
        if is_valid and check_digests and hashlib:
            try:
                # Attempt to compute digest if object provides content or data
                content = None
                if hasattr(obj, 'content'):
                    content = obj.content
                elif hasattr(obj, 'data'):
                    content = obj.data
                else:
                    # Cannot compute digest; skip check
                    content = None

                if content is not None:
                    # Ensure content is bytes for hashing
                    if isinstance(content, str):
                        content_bytes = content.encode('utf-8')
                    elif isinstance(content, (bytes, bytearray)):
                        content_bytes = content
                    else:
                        # Unsupported content type; treat as invalid
                        is_valid = False
                        if show_warnings:
                            print(f"Warning: Unsupported content type {type(content)} for object {obj}.")
                        raise TypeError

                    # Compute hash (using SHA256 by default)
                    computed_digest = hashlib.sha256(content_bytes).hexdigest()
                    # Expected digest may be stored in obj.digest or obj.expected_digest
                    expected_digest = None
                    if hasattr(obj, 'digest'):
                        expected_digest = obj.digest
                    elif hasattr(obj, 'expected_digest'):
                        expected_digest = obj.expected_digest

                    if expected_digest is None:
                        # No digest to compare against; skip check
                        pass
                    else:
                        if isinstance(expected_digest, str):
                            expected_digest = expected_digest.strip().lower()
                        if computed_digest.lower() != expected_digest:
                            is_valid = False
                            if show_warnings:
                                print(f"Warning: Digest mismatch for object {obj}. Expected {expected_digest}, got {computed_digest}.")
                else:
                    # No content to verify; skip digest check
                    pass
            except Exception as e:
                # Any failure in digest calculation marks object as invalid
                is_valid = False
                if show_warnings:
                    print(f"Warning: Digest check failed for object {obj}: {e}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def initialize(self):
        """
        Create and initialize a new OCFL storage root.

        This method ensures that the root directory exists, creates the
        standard OCFL subdirectories and writes a minimal `ocfl_info.json`
        file if it does not already exist.  Any exception during the
        creation process is wrapped in a RuntimeError with contextual
        information to aid debugging.
        """
        try:
            root = getattr(self, "root", None)
            if not root:
                raise ValueError("Root path attribute 'root' is missing or empty")

            # Ensure the root path is a directory
            if os.path.exists(root):
                if not os.path.isdir(root):
                    raise RuntimeError(f"Root path '{root}' exists but is not a directory")
            else:
                os.makedirs(root, exist_ok=True)

            # Path to the OCFL metadata file
            ocfl_info_path = os.path.join(root, "ocfl_info.json")

            # Create a minimal ocfl_info.json if it does not exist
            if not os.path.exists(ocfl_info_path):
                default_info = {
                    "ocfl_version": "2.0",
                    "layout_version": "1.0",
                    "layout": {"type": "default"}
                }
                try:
                    with open(ocfl_info_path, "w", encoding="utf-8") as f:
                        json.dump(default_info, f, ensure_ascii=False, indent=4)
                except Exception as write_err:
                    raise RuntimeError(f"Failed to write OCFL info file at '{ocfl_info_path}': {write_err}") from write_err

            # Ensure the objects directory exists
            objects_dir = os.path.join(root, "objects")
            if not os.path.isdir(objects_dir):
                os.makedirs(objects_dir, exist_ok=True)

            # Mark initialization flag if the class uses one
            if hasattr(self, "_is_initialized"):
                self._is_initialized = True

        except Exception as exc:
            raise RuntimeError(f"Failed to initialize OCFL storage root at '{getattr(self, 'root', None)}': {exc}") from exc

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    if version == "":
        raise ValueError("empty version string")
    if not version.isdigit():
        # This implementation only supports numeric version identifiers.
        raise ValueError("version must be a numeric string")
    # Preserve leading zeros if present
    original_len = len(version)
    try:
        number = int(version)
    except Exception as e:
        raise ValueError(f"cannot convert version to integer: {e}")
    next_number = number + 1
    next_str = str(next_number)
    # If the original had leading zeros, pad the result back to the original length
    if original_len > len(next_str):
        next_str = next_str.rjust(original_len, "0")
    return next_str

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str) or not version:
        raise ValueError(f"Invalid version: {version!r}")

    parts = version.split('.')
    # Find the rightmost numeric part and increment it
    for i in range(len(parts) - 1, -1, -1):
        part = parts[i]
        if part.isdigit():
            try:
                new_val = int(part) + 1
            except ValueError:
                raise ValueError(f"Invalid numeric part in version: {part!r}") from None
            # Preserve leading zeros if length hasn't increased; if it does, use the new length
            new_str = str(new_val).zfill(max(len(part), len(str(new_val))))
            parts[i] = new_str
            return '.'.join(parts)
    # If no numeric part found, raise an error
    raise ValueError(f"Version string '{version}' does not contain a numeric component.")

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        if not isinstance(version_dirs, (list, tuple)):
            raise TypeError("version_dirs must be a list or tuple of directory names")
        if not version_dirs:
            raise ValueError("version_dirs is empty")

        # Ensure we have a root inventory loaded
        if not hasattr(self, "root_inventory") or not isinstance(self.root_inventory, dict):
            raise AttributeError("Attribute 'root_inventory' must be defined as a dict before validation")

        # Prepare a container for digest differences
        self.different_digests = {}

        for vdir in version_dirs:
            if not isinstance(vdir, str) or not vdir:
                raise ValueError(f"Invalid directory name in version_dirs: {vdir!r}")

            inv_path = os.path.join(self.base_dir, vdir, "inventory.json")
            if not os.path.isfile(inv_path):
                raise FileNotFoundError(f"Missing inventory file: {inv_path}")

            try:
                with open(inv_path, "r", encoding="utf-8") as f:
                    inv = json.load(f)
            except (OSError, json.JSONDecodeError) as exc:
                raise RuntimeError(f"Failed to read inventory at {inv_path}: {exc}") from exc

            if not isinstance(inv, dict):
                raise ValueError(f"Inventory in {inv_path} is not a JSON object")

            # Validate that inventory contains all items from the root inventory
            missing_items = set(self.root_inventory) - set(inv)
            if missing_items:
                raise ValueError(
                    f"Inventory in {vdir} is missing entries for: {', '.join(sorted(missing_items))}"
                )

            # Compare digests and record differences
            for item_path, root_entry in self.root_inventory.items():
                ver_entry = inv.get(item_path, {})
                root_digest = root_entry.get("digest")
                ver_digest = ver_entry.get("digest")
                if root_digest is None:
                    continue  # nothing to compare
                if ver_digest != root_digest:
                    self.different_digests.setdefault(item_path, []).append(vdir)

        # No explicit return; method stores differences in self.different_digests    
        return None

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    from pathlib import Path

    try:
        p = Path(path)
    except Exception as exc:
        return f"Invalid path: {exc}"

    if not p.exists():
        return "Path does not exist"

    # Files (including inventories, etc.)
    if p.is_file():
        return "file"

    # Directory handling – inspect for Namaste files
    if p.is_dir():
        try:
            namaste_files = [
                f for f in p.iterdir()
                if f.is_file() and f.name.startswith("0=")
            ]
        except Exception as exc:
            return f"Error accessing directory contents: {exc}"

        if namaste_files:
            # Presence of a "0=" file indicates an OCFL Object
            return "object"

        # No Namaste files: treat as storage root (ocfl root dir)
        return "root"

    return "Unable to determine type"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    import re

    # Resolve symlinks and absolute path
    try:
        abs_path = os.path.abspath(os.path.realpath(path))
    except Exception as e:
        return f"error: invalid path ('{e}')"

    if not os.path.exists(abs_path):
        return f"error: path does not exist"

    if os.path.isfile(abs_path):
        return "file"

    if os.path.isdir(abs_path):
        try:
            entries = os.listdir(abs_path)
        except Exception as e:
            return f"error: cannot list directory ('{e}')"

        namaste_files = []
        for entry in entries:
            full = os.path.join(abs_path, entry)
            if not os.path.isfile(full):
                continue
            if re.match(r"^0=.*", entry):
                namaste_files.append(entry)

        if not namaste_files:
            return "error: no Namaste '0=*' file found in directory"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    try:
        if not os.path.exists(path):
            return "does not exist"
        if os.path.isfile(path):
