                old_key, old_value = result[idx]
                if is_mapping_node(old_value) and is_mapping_node(value_node):
                    # Deep merge mappings
                    result[idx] = (old_key, merge_mapping_nodes(old_value, value_node))
                else:
                    # Last wins for non-mapping values
                    result[idx] = (old_key, value_node)
