def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args.

    The function looks for placeholders surrounded by curly braces
    ``{placeholder}`` within *url* and substitutes them with the
    corresponding value from *url_args*.

    Parameters
    ----------
    url : str
        The URL possibly containing placeholder tokens.
    url_args : dict | iterable
        A mapping of keys to values.  If an iterable of two-item
        pairs is supplied, it is converted to a dictionary.

    Returns
    -------
    str
        The URL with placeholders replaced by the supplied values.
        If a placeholder key is not present in *url_args*, the
        placeholder is left unchanged.

    Raises
    ------
    TypeError
        If *url* is not a string.
    """
    if not isinstance(url, str):
        raise TypeError("url must be a string")

    # Normalise url_args to a dictionary
    if url_args is None:
        mapping = {}
    elif isinstance(url_args, dict):
        mapping = url_args
    else:
        try:
            mapping = dict(url_args)
        except Exception:
            mapping = {}

    result_parts = []
    i = 0
    length = len(url)

    while i < length:
        if url[i] == '{':
            end = url.find('}', i + 1)
            if end == -1:
                # No closing brace; append the rest and break
                result_parts.append(url[i:])
                break

            key = url[i + 1:end]
            if key in mapping:
                result_parts.append(str(mapping[key]))
            else:
                # Keep the original placeholder if no value found
                result_parts.append('{' + key + '}')
            i = end + 1
        else:
            result_parts.append(url[i])
            i += 1

    return ''.join(result_parts)

