    """Replace any custom string URL items with values in args

    Args:
        url (str): The URL containing placeholders in ``{placeholder}`` format.
        url_args (dict): Mapping of placeholder names to replacement values.

    Returns:
        str: The URL with any matched placeholders replaced by the corresponding
        values from ``url_args``. Placeholders without a matching key are left
        unchanged.

    Raises:
        TypeError: If ``url`` is not a string or ``url_args`` is not a mapping.
    """
    import re

    # Validate inputs
    if not isinstance(url, str):
        raise TypeError("url must be a str")
