    def _replace(match):
        key = match.group(1)
        if key in url_args:
            # Convert value to string (handle bytes, etc.)
            return str(url_args[key])
        # If key not found, leave placeholder as is
        return match.group(0)

    # Perform replacement
    return pattern.sub(_replace, url)

