def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    # Ensure the destination directory exists
    try:
        destination_path.mkdir(parents=True, exist_ok=True)
    except Exception as exc:
        raise RuntimeError(f"Could not create destination directory '{destination_path}': {exc}")

    # Prepare path for temporary download
    temp_archive = destination_path / "temp_repo_archive.tar.gz"

    try:
        # Download the archive with streaming
        with requests.get(url, stream=True, timeout=30) as r:
            r.raise_for_status()
            with open(temp_archive, "wb") as f:
                for chunk in r.iter_content(chunk_size=8192):
                    if chunk:  # filter out keep-alive chunks
                        f.write(chunk)
    except requests.exceptions.RequestException as re:
        # Remove partial file if exists
        if temp_archive.exists():
            try:
                temp_archive.unlink()
            except Exception:
                pass
        raise RuntimeError(f"Failed to download repository archive from '{url}': {re}")

    # Extract the archive
    try:
        import tarfile  # local import to keep imports minimal
        with tarfile.open(temp_archive, "r:gz") as tar:
            tar.extractall(path=destination_path)
    except (tarfile.TarError, OSError) as te:
        # Cleanup temp file
        if temp_archive.exists():
            try:
                temp_archive.unlink()
            except Exception:
                pass
        raise RuntimeError(f"Failed to extract repository archive '{temp_archive}': {te}")

    # Clean up the downloaded archive file
    try:
        temp_archive.unlink()
    except Exception:
        pass  # ignore if deletion fails

    return destination_path

