        platform = 0 if sys.platform.startswith('win') else 1
    # POSIX
    if platform == 1:
        # shlex.split with posix=True handles POSIX quoting rules
        return shlex.split(s, posix=True)
    # Windows
    if platform == 0:
        # shlex.split with posix=False handles Windows CMD quoting rules
        return shlex.split(s, posix=False)
    raise ValueError(f"Unsupported platform flag: {platform}")

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """
    Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Create a temporary directory where the archive will be extracted
    try:
        tmp_dir_bytes = subprocess.check_output(
            ["mktemp", "-d", "-p", str(tmp_path)],
            stderr=subprocess.STDOUT
        )
        temp_dir = tmp_dir_bytes.decode().strip()
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to create temporary directory: {e.output.decode().strip()}") from e

    # Determine the archive type based on its extension
    lower_path = archive_path.lower()
    try:
        if lower_path.endswith(".zip"):
            subprocess.check_call(
                ["unzip", "-q", archive_path, "-d", temp_dir],
                stderr=subprocess.STDOUT
            )
        elif lower_path.endswith(".tar.gz") or lower_path.endswith(".tgz"):
            subprocess.check_call(
                ["tar", "-xzf", archive_path, "-C", temp_dir],
                stderr=subprocess.STDOUT
            )
        elif lower_path.endswith(".tar.bz2")

