def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    # Handle empty or special cases
    if frequency is None:
        return None
    freq = frequency.strip()
    if not freq:
        return None
    if freq.lower() == 'always':
        return None

    # Expect a format like "<number> <unit>"
    parts = freq.split()
    if len(parts) != 2:
        raise ValueError(f"Invalid frequency format: '{frequency}'")

    number_part, unit_part = parts
    try:
        number = float(number_part)
    except ValueError:
        raise ValueError(f"Invalid numeric value in frequency: '{number_part}'")

    unit = unit_part.lower()
    if unit.startswith('day'):
        return datetime.timedelta(days=number)
    elif unit.startswith('hour'):
        return datetime.timedelta(hours=number)
    elif unit.startswith('minute'):
        return datetime.timedelta(minutes=number)
    elif unit.startswith('second'):
        return datetime.timedelta(seconds=number)
    elif unit.startswith('week'):
        return datetime.timedelta(weeks=number)
    else:
        raise ValueError(f"Unrecognized time unit in frequency: '{unit_part}'")

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    import datetime
    import re

    # Return None for null or always
    if frequency is None:
        return None
    freq_str = frequency.strip().lower()
    if freq_str == "always":
        return None

    # Regex to capture a number (int or float) followed by a unit word
    pattern = r'^\s*(?P<value>\d+(?:\.\d+)?(?:e[+-]?\d+)?)\s*(?P<unit>[a-zA-Z]+)\s*$'
    match = re.fullmatch(pattern, freq_str)
    if not match:
        raise ValueError(f"Unable to parse frequency: {frequency!r}")

    number_str = match.group('value')
    unit_str = match.group('unit')

    try:
        # Prefer int if possible, otherwise float
        if '.' in number_str or 'e' in number_str.lower():
            value = float(number_str)
        else:
            value = int(number_str)
    except ValueError:
        raise ValueError(f"Invalid number in frequency: {number_str!r}")

    # Map units to datetime.timedelta keyword arguments
    unit_map = {
        'day': 'days', 'days': 'days',
        'hour': 'hours', 'hours': 'hours',
        'minute': 'minutes', 'minutes': 'minutes',
        'second': 'seconds', 'seconds': 'seconds',
        'week': 'weeks', 'weeks': 'weeks',
    }

    if unit_str not in unit_map:
        raise ValueError(f"Unsupported time unit in frequency: {unit_str!r}")

    kwargs = {unit_map[unit_str]: value}
    try:
        return datetime.timedelta(**kwargs)
    except TypeError as e:
        raise ValueError(f"Error creating timedelta from frequency: {frequency!r}") from e

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    # Handle None or sentinel values
    if frequency is None:
        return None
    if not isinstance(frequency, str):
        raise ValueError(f"Frequency must be a string or None, got {type(frequency).__name__}")
    cleaned = frequency.strip().lower()
    if cleaned == "always":
        return None

    # Split into number and unit
    parts = cleaned.split()
    if len(parts) != 2:
        raise ValueError(f"Invalid frequency format: '{frequency}'. Expected '<number> <unit>'")
    num_str, unit = parts
    try:
        amount = int(num_str)
    except ValueError:
        raise ValueError(f"Invalid numeric value '{num_str}' in frequency '{frequency}'")

    # Map unit to timedelta keyword arguments
    unit_map = {
        ("day", "days"): {"days": amount},
        ("week", "weeks"): {"weeks": amount},
        ("hour", "hours"): {"hours": amount},
        ("minute", "minutes"): {"minutes": amount},
        ("second", "seconds"): {"seconds": amount},
    }

    # Find matching unit
    for key_tuple, kwargs in unit_map.items():
        if unit in key_tuple:
            return datetime.timedelta(**kwargs)

    # If unit not recognized, raise error
    raise ValueError(f"Unknown time unit '{unit}' in frequency '{frequency}'")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Handle invalid or missing input
    if not isinstance(host, str) or not host:
        return False

    # Direct name match
    if host.strip().lower() == "localhost":
        return True

    try:
        # Resolve the host to an IP address or list of addresses
        addr_infos = socket.getaddrinfo(host, None)
        for info in addr_infos:
            # the IP address is at index 4 of the tuple
            ip_addr = info[4][0]
            # IPv4 loopback
            if ip_addr == "127.0.0.1" or ip_addr.startswith("127."):
                return True
            # IPv6 loopback
            if ip_addr == "::1":
                return True
            # IPv4-mapped IPv6 loopback (::ffff:127.X.Y.Z)
            if ip_addr.startswith("::ffff:127.") or ip_addr.startswith("::ffff:"):
                # confirm it's mapped to a 127.* address
                try:
                    mapped = ip_addr.split(":")[-1]
                    if mapped.startswith("127."):
                        return True
                except Exception:
                    pass
    except socket.gaierror:
        # Hostname could not be resolved
        return False
    except Exception:
        # Any other error should not crash; consider non-local
        return False

    return False

def is_local(host):
