def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # Ensure we are on Windows
        if os.name != 'nt':
            return False

        # Git Bash (MSYS2 / MinGW) sets the MSYSTEM environment variable
        msystem = os.environ.get('MSYSTEM')
        if not msystem:
            return False

        msystem = msystem.upper()
        return msystem in ('MINGW32', 'MINGW64', 'MSYS', 'MSYS2')
    except Exception:
        # In any unexpected error case, default to False
        return False

