    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    if matcher is None:
        raise ValueError("Provided matcher is None")

    var_name = None
    default_value = None

    # Handle a regex match object (it usually provides groupdict())
    if hasattr(matcher, "groupdict"):
        gdict = matcher.groupdict()
        # Commonly-used group names
        for key in ("var", "name", "env", "variable"):
            if key in gdict and gdict[key]:
                var_name = gdict[key]
                break
        default_value = gdict.get("default", None)

    # Handle a tuple or list (often from a split of a string like "VAR:default")
    elif isinstance(matcher, (tuple, list)):
        if len(matcher) == 2:
            var_name, default_value = matcher
        elif len(matcher) == 1:
            var_name = matcher[0]
        else:
            raise ValueError(f"Matcher tuple/list must have 1 or 2 elements, got {len(matcher)}")

    # Assume matcher is a simple string representing the variable name
    elif isinstance(matcher, str):
        var_name = matcher

    else:
        raise TypeError(f"Unsupported matcher type: {type(matcher).__name__}")

    if not var_name:
        raise ValueError(f"Unable to extract a variable name from matcher: {matcher}")

    # Retrieve from environment
    env_value = os.getenv(var_name)

    if env_value is None:
        if default_value is not None:
            return default_value
        raise KeyError(f"Environment variable '{var_name}' not defined and no default value provided")

    return env_value

