    # If matcher is a tuple/list (unlikely), extract accordingly.
    elif isinstance(matcher, (list, tuple)):
        try:
            name = matcher[0]
            default = matcher[1] if len(matcher) > 1 else None
        except Exception:
            pass

    if not isinstance(name, str):
        raise ValueError("Matcher does not provide a valid variable name.")

    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        else:
            raise KeyError(f"Environment variable '{name}' is not set and no default was provided.")
    return value

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    if not isinstance(image_href, str):
        raise ValueError("image_href must be a string")
    image_href = image_href.strip()
    if not image_href:
        raise ValueError("image_href cannot be empty")

    # Helper to parse and validate
    def _do_parse(href: str) -> Tuple[str, str, bool]:
        try:
            parsed = urllib.parse.urlparse(href)
        except Exception as exc:
            raise ValueError(f"Failed to parse image_href: {href}") from exc

        scheme = parsed.scheme.lower()
        if scheme not in ("http", "https"):
            # If no scheme, insert http for parsing
            if not scheme:
                # prepend http to allow extraction of netloc and path
                parsed = urllib.parse.urlparse("http://" + href)
                scheme = parsed.scheme.lower()
            else:
                raise ValueError(f"Unsupported URL scheme: {scheme}")

        use_ssl = scheme == "https"

        netloc = parsed.netloc
        if not netloc:
            # If still no netloc, parsing failed
            raise ValueError(f"Unable to determine host from href: {href}")

        # Normalize image_id: remove leading slash, queries, fragments
        image_id = parsed.path.lstrip("/")
        comma = image_id.find("?")
        if comma != -1:
            image_id = image_id[:comma]
        hashidx = image_id.find("#")
        if hashidx != -1:
            image_id = image_id[:hashidx]
        return image_id, netloc, use_ssl

    # First attempt parsing normally
    try:
        return _do_parse(image_href)
    except ValueError:
        # Attempt to handle missing scheme scenarios
        if "://" not in image_href:
            return _do_parse("http://" + image_href)
        raise

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError: if the href is invalid or does not contain a usable image ID
    """
    if not isinstance(image_href, str):
        raise ValueError("image_href must be a string")
    href = image_href.strip()
    if not href:
        raise ValueError("image_href cannot be empty")

    parsed = urllib.parse.urlparse(href)

    # Default to http if scheme is missing but the href starts with a network path
    if not parsed.scheme and href.startswith('//'):
        parsed = urllib.parse.urlparse('http:' + href)

    # Determine whether SSL is required
    use_ssl = False
    if parsed.scheme:
        scheme = parsed.scheme.lower()
        if scheme == 'https':
            use_ssl = True
        elif scheme != 'http':
            raise ValueError(f"Unsupported URL scheme: {scheme}")

    netloc = parsed.netloc
    path = parsed.path

    # Extract the image ID from the path; if no path, treat the entire href as the ID
    if path and path != '/':
        image_id = path.rstrip('/').split('/')[-1]
    else:
        image_id = href

    if not image_id:
        raise ValueError("Image ID cannot be empty")
    if netloc and not path:
        # URL had a host but no path component – no image ID
        raise ValueError("No image ID found in href")
    return (image_id, netloc, use_ssl)

