    """
    This method converts the given string to a regex pattern.
    It strips whitespace (if ``strip=True``), escapes all regex metacharacters,
    and returns a compiled ``re.Pattern`` instance.
    """
    if pattern is None:
        raise ValueError("pattern must not be None")
    if not isinstance(pattern, str):
        raise TypeError(f"pattern must be a string, got {type(pattern).__name__}")
    # Optional whitespace stripping
    if strip:
        pattern = pattern.strip()
    # Escape the pattern to treat it as a literal string
    escaped = re.escape(pattern)
    # Compile the escaped pattern
    try:
        return re.compile(escaped)
    except re.error as exc:
        raise ValueError(f"Failed to compile regex pattern: {exc}") from exc

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to a regex pattern.
    Wildcards:
        * -> .*   (matches any sequence of characters)
        ? -> .    (matches any single character)
    Other regex metacharacters are escaped except for the ones used as anchors (^, $).
    If strip is True, leading and trailing whitespace is removed from the pattern.
    The function returns a compiled re.Pattern object. Raises TypeError if `pattern` is not a string.
    """
    if not isinstance(pattern, str):
        raise TypeError('pattern must be a string')
    if strip:
        pattern = pattern.strip()
    # Characters that should be escaped in a literal regex pattern,
    # excluding the wildcard characters * and ?, and the anchor characters ^ and $.
    escape_chars = r".+()[]{}|\\"
    escaped_parts = []
    for ch in pattern:
        if ch == '*':
            escaped_parts.append('.*')
        elif ch == '?':
            escaped_parts.append('.')
        elif ch in escape_chars:
            escaped_parts.append('\\' + ch)
        else:
            escaped_parts.append(ch)
    regex_str = ''.join(escaped_parts)
    try:
        compiled = re.compile(regex_str)
    except re.error as e:
        raise ValueError(f"Invalid regex pattern derived from '{pattern}': {e}") from e
    return compiled

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    # Validate the input type
    if pattern is None:
        raise ValueError("The pattern argument cannot be None.")
    if not isinstance(pattern, str):
        raise TypeError(f"The pattern argument must be a string, got {type(pattern).__name__}.")

    # Optional stripping of surrounding whitespace
    if strip:
        pattern = pattern.strip()

    # Escape all regex special characters so the pattern matches literally
    escaped = re.escape(pattern)

    # Compile the pattern, anchoring it to match the entire string
    try:
        compiled_pattern = re.compile(f'^{escaped}$')
    except re.error as e:
        raise ValueError(f"Error compiling regex pattern: {e}") from e

    return compiled_pattern

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate input types
    if commands is None:
        raise ValueError("commands cannot be None")
    if isinstance(commands, (list, tuple)):
        full_cmd = list(commands)
        if args and args != []:
            # If args are provided alongside a command list, convert the first element of args
            # to part of the command list only if it makes sense; otherwise ignore.
            # For safety we just ignore args in this case.
            pass
    elif isinstance(commands, str):
        full_cmd = [commands]
        if args is None:
            args = []
        if not isinstance(args, (list, tuple)):
            raise TypeError("args must be a list or tuple of strings")
        # Ensure all args are str
        for a in args:
            if not isinstance(a, str):
                raise TypeError(f"argument {a!r} is not a string")
        full_cmd += list(args)
    else:
        raise TypeError("commands must be a string or a list/tuple of strings")

    # Ensure all elements of full_cmd are strings
    for i, token in enumerate(full_cmd):
        if not isinstance(token, str):
            raise TypeError(f"command token at position {i} ({token!r}) is not a string")

    # Prepare environment
    if env is not None:
        if not isinstance(env, dict):
            raise TypeError("env must be a dictionary of environment variables")
        # Ensure keys and values are strings
        for k, v in env.items():
            if not isinstance(k, str) or not isinstance(v, str):
                raise TypeError(f"environment variable {k!r}={v!r} must be string")

    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=False
        )
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {full_cmd[0]}") from e
    except OSError as e:
        raise RuntimeError(f"Error executing command {full_cmd[0]}: {e}") from e

    if verbose:
        if result.stdout:
            print(result.stdout, end='')
        if not hide_stderr and result.stderr:
            print(result.stderr, end='')

    if result.returncode != 0:
        raise subprocess.CalledProcessError(
            returncode=result.returncode,
            cmd=full_cmd,
            output=result.stdout,
            stderr=result.stderr
        )

    return result

