            continue
        if not os.path.isfile(filename):
            error_records.append(_make_error_record(f"File not found: {filename}"))
            continue
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()
        except Exception as exc:
            error_records.append(_make_error_record(f"Error reading file {filename}: {exc}"))
