        for key, value in new.items():
            if isinstance(value, dict) and isinstance(orig.get(key), dict):
                deep_update(orig[key], value)
            else:
                orig[key] = value

    results = {}
    error_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                ext = os.path.splitext(filename)[1].lower()

                if ext in ('.json',):
                    config = json.load(f)
                    if not isinstance(config, dict):
                        raise ValueError(f"JSON root must be an object in {filename}")

                elif ext in ('.yml', '.yaml',):
                    if yaml is None:
                        raise ImportError(f"PyYAML is required to parse {filename}")
                    config = yaml.safe_load(f)
                    if not isinstance(config, dict):
                        raise ValueError(f"YAML root must be a mapping in {filename}")

                elif ext in ('.ini', '.cfg', '.conf'):
                    import configparser
                    parser = configparser.ConfigParser()
                    parser.read_file(f)
                    config = {section: dict(parser.items(section)) for section in parser.sections()}
                    # If there are options without sections, put them under DEFAULT
                    if parser.defaults():
                        config.setdefault('DEFAULT', {}).update(parser.defaults())

                else:
                    raise ValueError(f"Unsupported file extension '{ext}' for file {filename}")

                # Apply overrides if provided
                if overrides:
                    deep_update(config, overrides)

                # Environment variable substitution
                if resolve_env:
                    def recurse(value):
                        if isinstance(value, dict):
                            return {k: recurse(v) for k, v in value.items()}
                        elif isinstance(value, list):
                            return [recurse(v) for v in value]
                        else:
                            return substitute_env(value)
                    config = recurse(config)

                results[filename] = config

        except Exception as exc:
            message = f"Failed to load configuration from '{filename}': {exc}"
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname='',
                lineno=0,
                msg=message,
                args=(),
                exc_info=None
            )
            error_records.append(record)

    return results, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    # Import necessary modules locally to keep the signature clean
    import json
    import logging
    import os
    import re

    # Ensure config_filenames is a list or tuple; if a single string, make it a single-element list
    if isinstance(config_filenames, (str, bytes)):
        config_filenames = [config_filenames]
    elif not hasattr(config_filenames, '__iter__'):
        raise TypeError('config_filenames must be an iterable of filenames')

    configs = {}
    errors = []

    # Helper: resolve ${VAR} placeholders in all string values of a JSON object
    placeholder_pattern = re.compile(r'\$\{([^}]+)\}')

    def _resolve_in_string(s):
        def replace(match):
            var_name = match.group(1)
            return os.environ.get(var_name, match.group(0))
        return placeholder_pattern.sub(replace, s)

    def _resolve_env_in_obj(obj):
        if isinstance(obj, dict):
            return {k: _resolve_env_in_obj(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_resolve_env_in_obj(item) for item in obj]
        elif isinstance(obj, str):
            return _resolve_in_string(obj)
        else:
            return obj

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()
        except FileNotFoundError:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=__file__,
                lineno=0,
                msg=f'Configuration file not found: {filename}',
                args=(),
                exc_info=None
            )
            errors.append(record)
            continue
        except Exception as exc:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=__file__,
                lineno=0,
                msg=f'Error opening configuration file {filename}: {exc}',
                args=(),
                exc_info=None
            )
            errors.append(record)
            continue

        try:
            # Attempt to parse JSON; if fails, treat it as plain text and store
            parsed = json.loads(content)
        except json.JSONDecodeError as e:
            # Attempt to parse as plain text into a dictionary with a single key
            # Custom logic: treat entire content as a single string value
            parsed = {'_raw_content': content}
            # Log a warning about JSON decoding failed
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.WARNING,
                pathname=__file__,
                lineno=0,
                msg=f'JSON decode error in {filename}: {e}',
                args=(),
                exc_info=None
            )
            errors.append(record)

        # Resolve environment variables if required
        if resolve_env:
            try:
                parsed = _resolve_env_in_obj(parsed)
            except Exception as exc:
                record = logging.LogRecord(
                    name='load_configurations',
                    level=logging.ERROR,
                    pathname=__file__,
                    lineno=0,
                    msg=f'Environment resolution error in {filename}: {exc}',
                    args=(),
                    exc_info=None
                )
                errors.append(record)

        # Apply overrides if provided
        if overrides and isinstance(overrides, dict):
            if isinstance(parsed, dict):
                # Simple shallow merge: overrides overwrite keys in parsed
                merged = parsed.copy()
                merged.update(overrides)
                parsed = merged
            else:
                # If parsed is not a dict, wrap it and apply overrides as top-level keys
                parsed = {'_original': parsed}
                parsed.update(overrides)

        configs[filename] = parsed

    return (configs, errors)

def force_string(obj):
    """Return a UTF‑8 encoded bytes object if *obj* is a string; otherwise return *obj* unchanged."""
    if isinstance(obj, str):
        try:
            return obj.encode("utf-8")
        except Exception as exc:
            raise ValueError("Unable to encode string to UTF-8") from exc
    return obj

def protocol_handlers(cls, protocol_version=None):
    """
    Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple identifying a protocol version")

    # Retrieve the internal registry of handlers. If the class
    # hasn't defined one, treat it as empty.
    handlers = getattr(cls, "_protocol_handlers", {})
    if not isinstance(handlers, dict):
        # In case the attribute exists but is not a dict, ignore it
        handlers = {}

    if protocol_version is None:
        # Return a copy to prevent accidental external modifications
        return dict(handlers)

    handler = handlers.get(protocol_version)
    if handler is not None:
        return {protocol_version: handler}
    return {}

def protocol_handlers(cls, protocol_version=None):
    """
    Return a dictionary of available Bolt protocol handlers, keyed by
    version tuple.  If an explicit protocol version is provided, the
    dictionary will contain either zero or one items, depending on
    whether that version is supported. If no protocol version is
    provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """

    # Validate the input type
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple or None")

    # Retrieve the class-level mapping of supported handlers.
    # The mapping is expected to be stored in a class attribute named
    # "_PROTOCOL_HANDLERS" (fallback to empty if not present).
    handlers = getattr(cls, "_PROTOCOL_HANDLERS", {})
    if handlers is None:
        handlers = {}

    # Ensure we do not accidentally expose the internal mapping; copy it when needed.
    if protocol_version is not None:
        # Return a singleton dict if the requested version exists, otherwise an empty dict.
        if protocol_version in handlers:
            return {protocol_version: handlers[protocol_version]}
        return {}
    else:
        # Return a shallow copy so callers cannot mutate the original mapping.
        return dict(handlers)

def from_raw_values(cls, values):
    """
    Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    :return: A new instance of ``cls`` containing the supplied bookmarks.
    :rtype: cls
    """
    # Handle None or empty input
    if values is None:
        return cls()
    # Reject a single string (would be iterated over as individual characters)
    if isinstance(values, str):
        raise TypeError("values must be an iterable of strings, not a single string")
    # Ensure ``values`` is an iterable
    try:
        iterator = iter(values)
    except TypeError as exc:
        raise TypeError("values must be an iterable of string values") from exc

    processed = []
    for item in iterator:
        # Decode bytes to ASCII string
        if isinstance(item, bytes):
            try:
                item = item.decode('ascii')
            except UnicodeDecodeError as exc:
                raise ValueError(f"Bookmark byte value must be ASCII, got {item!r}") from exc
        elif not isinstance(item, str):
            raise TypeError(f"Bookmark values must be str or bytes, got {type(item).__name__}")
        processed.append(item)

    # Instantiate the Bookmarks object with the processed values.
    # If the constructor accepts an iterable directly, this should work.
    # If it expects a set, passing a list is still acceptable because it will be
    # iterated over. We attempt the simplest form first.
    try:
        instance = cls(processed)
    except Exception as exc:
        # In case the constructor expects a different signature, fall back to
        # passing a set of the values.
        try:
            instance = cls(set(processed))
        except Exception as exc2:
            raise TypeError("Failed to create Bookmarks instance with the provided values") from exc2
    return instance

