        # we create a generic attribute `_raw_values`.
        attr_name = None
        if hasattr(instance, "raw_values"):
            attr_name = "raw_values"
        elif hasattr(instance, "_raw_values"):
            attr_name = "_raw

def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        # Ensure `values` is iterable; if not, raise an informative error.
        try:
            raw_items = list(values)
        except TypeError as exc:
            raise TypeError(
                "values must be an iterable of strings (raw bookmarks)"
            ) from exc

        # Validate that each item is a string; this helps catch accidental
        # inclusion of non-string data such as newline objects or bytes.
        for idx, item in enumerate(raw_items):
            if not isinstance(item, str):
                raise TypeError(
                    f"Bookmark value at index {idx} is not a string: got {type(item).__name__}"
                )

        # Instantiate the Bookmarks object.  The constructor is expected to
        # accept an optional list of raw bookmark strings; if it accepts
        # a different argument signature, this code will propagate the
        # resulting exception to the caller as a helpful traceback.
        try:
            return cls(raw_items)
        except Exception as exc:
            # Wrap any unexpected error in a RuntimeError that
            # indicates the problem happened during deserialization.
            raise RuntimeError("Failed to create Bookmarks from raw values") from exc

def from_raw_values(cls, values):
    """
    Create a Bookmarks object from a list of raw bookmark string values.

    Raw bookmark values are expected to be simple ASCII strings. If a value
    contains an '=', it will be split into a key/value pair; otherwise the
    entire string will be used as a key with a ``None`` value.

    The returned instance should be usable as a mapping of keys to values.
    If the class does not support item assignment, the method falls back
    to using an ``add`` method if present.

    :param values: Iterable of raw bookmark strings.
    :type values: Iterable[str]
    :return: An instance of ``cls`` containing the parsed bookmarks.
    :rtype: cls
    """
    if values is None:
        raise TypeError("values argument may not be None")

    # Ensure we have an iterable of strings
    try:
        iter(values)
    except TypeError:
        raise TypeError("values must be an iterable")

    # Create the new instance
    instance = cls()

    # Helper function to set a key/value pair in the instance
    def _set_item(key, value):
        # Try dict-like assignment first
        try:
            instance[key] = value
        except Exception:
            # Fallback to an `add` method if it exists
            add = getattr(instance, "add", None)
            if callable(add):
                add(key, value)
            else:
                # If neither works, raise a clear error
                raise TypeError(
                    f"Cannot insert key '{key}' into instance of {cls.__name__}"
                )

    for entry in values:
        if not isinstance(entry, str):
            raise TypeError("All items in values must be strings")
        # Skip empty entries
        if entry == "":
            continue

        if "=" in entry:
            key, val = entry.split("=", 1)
            _set_item(key, val)
        else:
            _set_item(entry, None)

    return instance

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Validate input
    if seq is None:
        raise TypeError("seq must not be None")
    # Define which types are considered "sequence" for this context
    sequence_types = (list, tuple, str, bytes, bytearray, range)
    if isinstance(seq, sequence_types):
        return seq, type(seq)
    # Not a known sequence type
    # Try to build a list from the iterable
    try:
        derived = list(seq)
    except TypeError as exc:
        raise TypeError(f"Provided object {seq!r} is not iterable") from exc
    return derived, type(derived)  # usually list type here

def scale(self, other=None):
        """Get or set the scale of the graph.

        If *other* is ``None``, return the scale of this graph.

        If a numeric *other* is provided, rescale to that value.
        If the graph has unknown or zero scale,
        rescaling that will raise :exc:`~.LenaValueError`.

        To get meaningful results, graph's fields are used.
        Only the last coordinate is rescaled.
        For example, if the graph has *x* and *y* coordinates,
        then *y* will be rescaled, and for a 3-dimensional graph
        *z* will be rescaled.
        All errors are rescaled together with their coordinate.
        """
        # Get the current scale
        current_scale = getattr(self, "scale", None)

        if other is None:
            return current_scale

        # Validate the new scale is numeric
        try:
            new_scale = float(other)
        except Exception:
            raise TypeError("Scale must be a numeric value")

        # Validate the current scale is known and non‑zero
        if current_scale is None or current_scale == 0:
            raise LenaValueError("Cannot rescale a graph with unknown or zero scale")

        # Compute the conversion factor
        factor = new_scale / current_scale

        # Rescale the last coordinate of each data row
        if hasattr(self, "data"):
            try:
                # Try numpy array style if available
                if hasattr(self.data, "__array__") and self.data.ndim > 1:
                    self.data[:, -1] *= factor
                else:
                    # Assume list of lists or tuples
                    for row in self.data:
                        if row:
                            row[-1] *= factor
            except Exception:
                # If any error occurs during rescaling, raise a general error
                raise LenaValueError("Failed to rescale graph data")

        # Rescale errors if they exist
        if hasattr(self, "errors"):
            try:
                for row in self.errors:
                    if row:
                        row[-1] *= factor
            except Exception:
                # Ignore errors in error rescaling
                pass

        # Update the stored scale
        setattr(self, "scale", new_scale)

def scale(self, other=None):
        """Get or set the scale of the graph.

        If *other* is ``None``, return the scale of this graph.

        If a numeric *other* is provided, rescale to that value.
        If the graph has unknown or zero scale,
        rescaling that will raise :exc:`~.LenaValueError`.

        To get meaningful results, graph's fields are used.
        Only the last coordinate is rescaled.
        For example, if the graph has *x* and *y* coordinates,
        then *y* will be rescaled, and for a 3-dimensional graph
        *z* will be rescaled.
        All errors are rescaled together with their coordinate.
        """
        # Retrieve the current scale; if not stored, treat as None
        current_scale = getattr(self, "_scale", None)
        if other is None:
            # Getter: return the current scale, or raise if undefined
            if current_scale is None:
                raise ValueError("Scale is unknown.")
            return current_scale

        # Setter: ``other`` must be numeric
        if not isinstance(other, (int, float)):
            raise TypeError("Scale must be a numeric value.")

        if current_scale is None or current_scale == 0:
            raise ValueError("Cannot rescale when scale is unknown or zero.")

        # Compute scaling factor
        factor = other / current_scale

        # Identify the last field to be rescaled
        if not hasattr(self, "fields") or not isinstance(self.fields, (list, tuple)):
            raise AttributeError("Graph must have a 'fields' list.")
        if not self.fields:
            raise ValueError("No fields defined in the graph.")

        last_field = self.fields[-1]

        # Attempt to rescale the attribute corresponding to the last field
        if hasattr(self, last_field):
            attr = getattr(self, last_field)
            # Support lists, tuples, or numpy-like sequences
            try:
                if hasattr(attr, "__iter__") and not isinstance(attr, (str, bytes)):
                    for i in range(len(attr)):
                        attr[i] *= factor
            except TypeError:
                # If not iterable, try numeric multiplication
                try:
                    setattr(self, last_field, attr * factor)
                except Exception:
                    pass

        # Also rescale any associated error attribute (e.g., ``y_err``)
        error_attr_name = f"{last_field}_err"
        if hasattr(self, error_attr_name):
            err_attr = getattr(self, error_attr_name)
            try:
                if hasattr(err_attr, "__iter__") and not isinstance(err_attr, (str, bytes)):
                    for i in range(len(err_attr)):
                        err_attr[i] *= factor
            except TypeError:
                try:
                    setattr(self, error_attr_name, err_attr * factor)
                except Exception:
                    pass

        # Update the graph's scale
        setattr(self, "_scale", other)

        return self

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale, rescaling that will raise
    :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Get current scale if no new scale specified
    if other is None:
        return getattr(self, "_scale", None)

    # Validate that the new scale is numeric
    if not isinstance(other, (int, float)):
        raise TypeError("Scale must be a numeric value")

    # Retrieve the current scale value
    curr_scale = getattr(self, "_scale", None)

    # Rescaling is not allowed if the current scale is unknown or zero
    if curr_scale is None or curr_scale == 0:
        raise LenaValueError(
            "Cannot rescale graph with unknown or zero initial scale"
        )

    # Compute the scaling factor
    try:
        factor = other / curr_scale
    except Exception as exc:
        # Any unexpected error during division
        raise LenaValueError(f"Error computing scaling factor: {exc}") from exc

    # Rescale the last coordinate of the graph
    # Attempt to handle common storage formats
    if hasattr(self, "_coordinates"):
        coords = self._coordinates
        try:
            # If coordinates are a 2D array-like (rows x columns)
            if hasattr(coords, "__getitem__") and hasattr(coords, "__len__"):
                if isinstance(coords[0], (list, tuple)):
                    # List of coordinate lists, reshape to 2D list
                    coords = [list(row) for row in coords]
                # Rescale last column
                for row in coords:
                    row[-1] *= factor
        except Exception:
            # If in-place modification fails, ignore
            pass

    # Rescale any error values associated with the last coordinate
    if hasattr(self, "_errors"):
        errors = self._errors
        try:
            if isinstance(errors, (list, tuple)):
                # List of error lists corresponding to each coordinate
                errors[-1] = [e * factor for e in errors[-1]]
        except Exception:
            pass

    # Update the scale attribute
    self._scale = other
    return None

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """
    Convert a histogram-like object to a graph representation.
    The histogram is expected to have attributes:
        - bins: an iterable of bin contents or bin objects the first element
                of which is the numeric content.
        - bin_edges: an iterable of shape (N+1,) giving the edges of the bins.
          If not present, an attempt will be made to deduce edges from the
          histogram's class (e.g., by using `hist.edges` or `hist.axes[0]`).
    The resulting graph is an instance of a minimal Graph class with
    attributes:
        points: list of tuples, each containing the coordinate and other
                values designated by `field_names`.
        field_names: the names of the fields.
        scale: the scale of the graph, optionally taken from the histogram.
    """
    # Basic validation and default assignments
    if make_value is None:
        make_value = lambda x: x

    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError(f"Invalid get_coordinate: {get_coordinate}")

    if not hasattr(hist, "bins"):
        raise AttributeError("Histogram object must have a 'bins' attribute")

    # Retrieve edges
    try:
        edges = list(hist.bin_edges)
    except AttributeError:
        # Try common alternatives
        try:
            edges = list(hist.edges)
        except AttributeError:
            try:
                edges = list(hist.axes[0])
            except Exception:
                raise AttributeError("Histogram object must provide bin edges "
                                     "via 'bin_edges', 'edges', or 'axes[0]' classes")

    if len(edges) != len(hist.bins) + 1:
        raise ValueError("Number of edges must be one more than number of bins")

    points = []
    for i, bin_contents in enumerate(hist.bins):
        # Resolve bin content if it's an object with context
        # Assume we can get numeric content by calling bin_contents directly if it's a plain value
        # Or if it's an instance with a numeric attribute named 'content' or is indexable
        try:
            content = bin_contents.content
        except AttributeError:
            try:
                content = bin_contents[0]
            except Exception:
                content = bin_contents

        # Compute coordinate
        left = edges[i]
        right = edges[i + 1]
        if get_coordinate == "left":
            coord = left
        elif get_coordinate == "right":
            coord = right
        else:  # "middle"
            coord = (left + right) / 2

        # Apply value builder
        value = make_value(content)

        # Normalise value to a tuple
        try:
            iter(value)
        except Exception:
            value = (value,)
        else:
            # Avoid treating string as iterable
            if isinstance(value, str):
                value = (value,)

        # Assemble point tuple
        point = (coord, ) + value

        # Validate field_names length
        if len(field_names) != 1 + len(value):
            raise ValueError(f"field_names length {len(field_names)} does not match "
                             f"the expected number of values {1 + len(value)} for bin {i}")

        points.append(point)

    # Determine scale
    actual_scale = scale
    if scale is True:
        actual_scale = getattr(hist, "scale", None)

    # Minimal Graph representation
    class Graph:
        __slots__ = ("points", "field_names", "scale")

        def __init__(self, points, field_names, scale=None):
            self.points = points
            self.field_names = field_names
