    # Check for a custom header that might indicate a Diaspora request
    try:
        if hasattr(request, "headers"):
            header_val = request.headers.get("X-Diaspora-Request")
            if header_val and header_val.lower() == "true":
                return True
    except Exception:
        pass

    # Check form data for known diaspora keys (public or private messages)
    try:
        if hasattr(request, "form") and request.form:
            for key in request.form:
                if key == "diaspora" or key.startswith("diaspora_"):
                    return True
    except Exception:
        pass

    # Check JSON payload for diaspora keys
    try:
        json_payload = None
        if hasattr(request, "json"):
            json_payload = request.json
        elif hasattr(request, "get_json"):
            json_payload = request.get_json(silent=True)
        if isinstance(json_payload, dict):
            for key in json_payload:
                if key == "diaspora" or key.startswith("diaspora_"):
                    return True
    except Exception:
        pass

    # Check for a legacy payload identifier in the query string
    try:
        if hasattr(request, "args") and request.args:
            legacy_val = request.args.get("legacy")
            if legacy_val and legacy_val.lower() == "true":
                return True
    except Exception:
        pass

    # Default: not a Diaspora request
    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        path = None

        # 1. Attribute-based extraction
        if hasattr(request, "path"):
            path = getattr(request, "path")
        elif hasattr(request, "uri"):
            path = getattr(request, "uri")
        elif hasattr(request, "url"):
            url_value = getattr(request, "url")
            if isinstance(url_value, str):
                # Strip query and fragment
                for sep in ("?", "#"):
                    if sep in url_value:
                        url_value = url_value.split(sep, 1)[0]
                # Extract path from full URL if present
                if "://" in url_value:
                    # Remove scheme and host
                    try:
                        scheme_end = url_value.index("://") + 3
                        rest = url_value[scheme_end:]
                        slash_idx = rest.index("/") if "/" in rest else -1
                        path = rest[slash_idx:] if slash_idx != -1 else "/"
                    except ValueError:
                        # fallback: treat as path
                        path = url_value
                else:
                    path = url_value

        # 2. Handle plain string requests
        if path is None and isinstance(request, str):
            url_value = request
            for sep in ("?", "#"):
                if sep in url_value:
                    url_value = url_value.split(sep, 1)[0]
            if "://" in url_value:
                try:
                    scheme_end = url_value.index("://") + 3
                    rest = url_value[scheme_end:]
                    slash_idx = rest.index("/") if "/" in rest else -1
                    path = rest[slash_idx:] if slash_idx != -1 else "/"
                except ValueError:
                    path = url_value
            else:
                path = url_value

        # 3. Handle dictionary-like requests
        if path is None and isinstance(request, dict):
            path = request.get("path") or request.get("uri") or request.get("url")

        # 4. Final validation
        if not isinstance(path, str):
            return False

        # Ensure path starts with '/'
        if not path.startswith("/"):
            path = "/" + path

        return path.startswith("/_matrix")
    except Exception:
        return False

def identify_request(request: RequestType) -> bool:
    """
