    """
    try:
        if not request:
            return False

        # Attempt to get the request path or URL string
        path = None
        if hasattr(request, "path"):
            path = getattr(request, "path")
        elif hasattr(request, "url"):
            path = getattr(request, "url")

        # If we got a URL that may contain a scheme, strip it
        if path and isinstance(path, str):
            # Basic strip of scheme if present
            if "://" in path:
                path = path.split("://", 1)[1]
            # Remove query and fragment
            if "?" in path:
                path = path.split("?", 1)[0]
            if "#" in path:
                path = path.split("#", 1)[0]

        # Check the path for the Matrix API prefix
        if path and (path.startswith("/_matrix") or "/_matrix" in path):
            return True

        # Check for typical Matrix request headers
        headers = getattr(request, "headers", {})
        if isinstance(headers, dict):
            auth_header = headers.get("Authorization") or headers.get("authorization")
            if auth_header and auth_header.lower().startswith("bearer"):
                return True
            # Matrix clients often include "Client-User-Agent" or "User-Agent"
            ua = headers.get("User-Agent") or headers.get("user-agent")
            if ua and ("Matrix" in ua or "SYNapse" in ua):
                return True

