def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    # A Matrix request typically starts with "/_matrix" in the path or URL.
    # The `RequestType` may be a framework request object (having `.path`, `.url`, etc.)
    # or a plain dictionary describing the request. We try to handle those cases.
    try:
        if request is None:
            return False

        # 1. Try attribute access (common in Flask, Starlette, etc.)
        path = getattr(request, "path", None)
        if path is None:
            # Some frameworks expose the full URL instead
            url = getattr(request, "url", None) or getattr(request, "full_url", None)
            if isinstance(url, str) and "/_matrix" in url:
                return True
        else:
            if isinstance(path, str) and path.startswith("/_matrix"):
                return True

        # 2. Try dictionary style lookup
        if isinstance(request, dict):
            # look for path key
            path_k = request.get("path")
            if isinstance(path_k, str) and path_k.startswith("/_matrix"):
                return True
            # look for url key
            url_k = request.get("url") or request.get("full_url")
            if isinstance(url_k, str) and "/_matrix" in url_k:
                return True

        # 3. As a last resort, try inspecting headers/body
        # For example, a Matrix request might have content type application/json
        # and a presence of a "type" field in JSON body.
        # We'll attempt to parse a JSON body if present.
        try:
            body = getattr(request, "json", None)
            if body is None:
                # Some frameworks expose `get_json` method
                get_json = getattr(request, "get_json", None)
                if callable(get_json):
                    body = get_json()
        except Exception:
            body = None

        if isinstance(body, dict):
            # Common Matrix operations contain a "type" key at top level
            if "type" in body:
                return True

    except Exception:
        # any error during introspection should safely result in False
        return False

    return False

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    try:
        if not isinstance(tag, str):
            return False
        tag = tag.strip()
        if not tag:
            return False
        # Tags typically allow only alphanumerics, hyphens, and underscores.
        import re
        pattern = re.compile(r'^[A-Za-z0-9_-]+$')
        return bool(pattern.match(tag))
    except Exception:
        return False

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    # Ensure the input is a string
    if not isinstance(tag, str):
        return False

    # Trim whitespace
    tag = tag.strip()

    # Empty tags are invalid
    if not tag:
        return False

    # Tag must not start or end with a hyphen
    if tag[0] == "-" or tag[-1] == "-":
        return False

    # Validate characters: letters, digits, and hyphens only
    # Hyphens cannot appear consecutively
    prev_dash = False
    for ch in tag:
        if ch == "-":
            if prev_dash:  # consecutive hyphens
                return False
            prev_dash = True
        elif ch.isalnum():
            prev_dash = False
        else:
            return False

    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    # Ensure we have a valid node to work with
    if node is None:
        return {}
    try:
        # Retrieve children; this will work for most XML Element implementations
        children = list(node)
    except Exception:
        # If node is not iterable/acceptable, return empty dict
        return {}

    result = {}
    for child in children:
        try:
            key = child.tag
        except Exception:
            # Skip elements that do not have a tag attribute
            continue

        # Extract and clean the text content of the child
        try:
            text = child.text
            if text is not None:
                text = text.strip()
                if text == "":  # treat empty string as None
                    text = None
        except Exception:
            text = None

        # Handle duplicate tags by accumulating into a list
        if key in result:
            existing = result[key]
            if isinstance(existing, list):
                existing.append(text)
            else:
                result[key] = [existing, text]
        else:
            result[key] = text

    return result

