def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    """
    Ensure that the sender handle and the entity handle match.
    Raises a ValueError if they do not match or if the inputs are invalid.
    Returns True if they match.
    """
    # Basic type and null checks
    if sender_handle is None or entity_handle is None:
        raise ValueError("Sender handle and entity handle must not be None")

    if not isinstance(sender_handle, str):
        raise TypeError(
            f"Sender handle must be a string, got {type(sender_handle).__name__}"
        )
    if not isinstance(entity_handle, str):
        raise TypeError(
            f"Entity handle must be a string, got {type(entity_handle).__name__}"
        )

    # Normalize by stripping whitespace and converting to a consistent case
    sender_clean = sender_handle.strip()
    entity_clean = entity_handle.strip()

    if sender_clean != entity_clean:
        raise ValueError(
            f"Sender handle '{sender_handle}' does not match entity handle '{entity_handle}'"
        )

    return True

def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    """
    Ensure that sender and entity handles match.

    Basically we've already verified the sender is who they say when receiving the payload.
    However, the sender might be trying to set another author in the payload itself, since Diaspora has the
    sender in both the payload headers AND the object. We must ensure they're the same.
    """
    # Convert bytes to string if necessary and perform basic validation
    def _normalize(val, name):
        if val is None:
            raise ValueError(f"{name} cannot be None")
        if isinstance(val, bytes):
            try:
                val = val.decode("utf-8")
            except Exception as exc:
                raise ValueError(f"Failed to decode {name} from bytes: {exc}") from exc
        if not isinstance(val, str):
            raise TypeError(f"{name} must be a string (or bytes), got {type(val).__name__}")
        return val

    sender_handle = _normalize(sender_handle, "sender_handle")
    entity_handle = _normalize(entity_handle, "entity_handle")

    if sender_handle != entity_handle:
        raise ValueError(
            f"Sender and entity handles do not match: "
            f"sender_handle={sender_handle!r} vs entity_handle={entity_handle!r}"
        )
    return True

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Validate input
    if not isinstance(url, str) or not url:
        raise TypeError("url must be a non-empty string")
    if document_path is not None and not isinstance(document_path, str):
        raise TypeError("document_path must be a string if provided")

    # Default to the standard NodeInfo version 2.0 document path
    doc_path = document_path if document_path is not None else "/nodeinfo/2.0"

    # Ensure the document path starts with a slash
    if not doc_path.startswith("/"):
        doc_path = "/" + doc_path

    # Strip any trailing slash from the base URL to avoid double slashes
    base = url.rstrip("/")

    href = base + doc_path

    # Construct the .well-known response
    response = {
        "links": [
            {
                "rel": "https://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }

    return response

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

