        if document_path is None:
            # Default to NodeInfo v2.0 endpoint
            document_path = "nodeinfo/2.0.json"
        else:
            if not isinstance(document_path, str):
                raise ValueError("document_path must be a string if provided")

        # Normalize path (strip leading/trailing slashes)
        base = url.rstrip("/")
        path = document_path.lstrip("/")

        href = f"{base}/{path}"

        # Construct the .well-known NodeInfo document
        rel = "http://nodeinfo.diaspora.software/ns/schema/2.0"
        return {
            "links": [
                {
                    "rel": rel,
                    "href": href
                }
            ]
        }
    except Exception as e:
        # Gracefully handle unexpected errors and provide a clear message
        raise RuntimeError(f"Failed to generate NodeInfo .well-known document: {e}") from e

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    try:
        # Basic validation for url
        if not isinstance(url, str) or not url.strip():
            raise ValueError("`url` must be a non-empty string")
        # Remove any trailing whitespace
        url = url.strip()

        # Use urllib.parse to parse the URL and validate scheme
        from urllib.parse import urlparse

        parsed = urlparse(url)
        if parsed.scheme not in ("http", "https"):
            raise ValueError("`url` must include http or https scheme")

        # Normalise base URL by stripping trailing slash
        base_url = url.rstrip("/")

        # Determine the NodeInfo document path
        if document_path is None:
            # Default path as specified by the spec
            nodeinfo_path = "/.well-known/nodeinfo/2.0"
        else:
            if not isinstance(document_path, str):
                raise ValueError("`document_path` must be a string if provided")
            nodeinfo_path = document_path.strip()

        # Ensure the path starts with a slash
        if not nodeinfo_path.startswith("/"):
            nodeinfo_path = "/" + nodeinfo_path

        # Construct the full href avoiding double slashes
        href = base_url + nodeinfo_path

        # Build the NodeInfo .well-known document
        return {
            "links": [
                {
                    "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                    "type": "application/json",
                    "href": href,
                }
            ]
        }

    except Exception as exc:
        # Re-raise as a ValueError with a clear message for callers
        raise ValueError(f"Failed to generate NodeInfo document: {exc}") from exc

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify that `signature` is a valid digital signature for the XML document
    `doc` using the public key provided in `public_key`.

    The public key may be supplied as a PEM string or a path to a PEM file.
    The signature may be a bytes object or a base64 encoded string.

    Returns True if the signature is valid, False otherwise.

    The function attempts a graceful degradation: if the cryptography package
    is unavailable or the inputs cannot be parsed, it simply returns False
    instead of propagating an exception.
    """
    try:
        import base64
        from cryptography import hazmat
        from cryptography.hazmat.primitives import serialization, hashes
        from cryptography.hazmat.primitives.asymmetric import padding
    except Exception:
        # cryptography module is not available
        return False

    # Normalize the public key: if provided directly as a PEM string, use it;
    # otherwise try to read from a file path.
    try:
        pub_pem = None
        if isinstance(public_key, str):
            if public_key.strip().startswith("-----BEGIN"):
                pub_pem = public_key.encode("utf-8")
            else:
                # Try reading a file
                with open(public_key, "rb") as f:
                    pub_pem = f.read()
        elif isinstance(public_key, bytes):
            pub_pem = public_key
        else:
            return False

        if not pub_pem:
            return False

        load_public_key = serialization.load_pem_public_key
        public_key_obj = load_public_key(pub_pem)
    except Exception:
        return False

    # Prepare the document data
    try:
        if isinstance(doc, bytes):
            data = doc
        else:
            data = str(doc).encode("utf-8")
    except Exception:
        return False

    # Prepare the signature bytes
    try:
        if isinstance(signature, bytes):
            sig_bytes = signature
        else:
            sig_bytes = base64.b64decode(signature)
    except Exception:
        return False

    # Verify signature using PKCS1v15 + SHA256
    try:
        public_key_obj.verify(
            sig_bytes,
            data,
            padding.PKCS1v15(),
            hashes.SHA256()
        )
        return True
    except Exception:
        return False

def parse_diaspora_webfinger(document: str) -> dict:
    """
    Parse a Diaspora webfinger payload which may be in the newer JSON format or the older XRD (XML) format.
    Returns a dictionary with at least the keys 'subject' (a string) and 'links' (a list of dictionaries).
    Raises ValueError if the payload cannot be parsed or is missing required fields.
    """
    import json
    import xml.etree.ElementTree as ET

    if not document or not isinstance(document, str):
        raise ValueError("Document must be a non-empty string")

    # ----------- Try JSON first --------------------------------------------
    try:
        data = json.loads(document)
        if not isinstance(data, dict):
            raise ValueError("JSON webfinger must be an object")
        subject = data.get("subject")
        links = data.get("links")
        if subject is None:
            raise ValueError("JSON webfinger missing 'subject'")
        if links is None:
            links = []
        if not isinstance(links, list):
            raise ValueError("'links' must be a list")
        # Normalise each link dict
        normalised_links = []
        for link in links:
            if not isinstance(link, dict):
                continue
            normalised_links.append({
                "rel": link.get("rel"),
                "type": link.get("type"),
                "href": link.get("href")
            })
        return {"subject": subject, "links": normalised_links}
    except (json.JSONDecodeError, ValueError):
        # Not JSON – fall back to XML parsing
        pass

    # ----------- Try XML (XRD) --------------------------------------------
    try:
        root = ET.fromstring(document)
    except ET.ParseError as exc:
        raise ValueError(f"Unable to parse webfinger document: {exc}") from exc

    # XRD may use a default namespace; build a mapping for it
    ns = {}
    if root.tag.startswith("{"):
        uri, _, _ = root.tag[1:].partition("}")
        ns["atom"] = uri

    # Find subject
    subject_path = ".//{*}Subject"  # Ignore namespace
    subject = None
    for elem in root.iter():
        if elem.tag.endswith("Subject"):
            subject = elem.text
            break
    if subject is None:
        raise ValueError("XML webfinger missing 'Subject' element")

    # Find all Link elements; ignore other namespaces
    links = []
    for link in root.findall(".//{*}Link"):
        rel = link.attrib.get("rel")
        typ = link.attrib.get("type")
        href = link.attrib.get("href")
        if href:  # Only include if href present
            links.append({"rel": rel, "type": typ, "href": href})

    return {"subject": subject, "links": links}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree

    doc = document.strip()
    if not doc:
        raise ValueError("Empty webfinger document")

    # Try JSON format first
    try:
        data = json.loads(doc)
        if not isinstance(data, dict):
            raise ValueError("JSON webfinger must be an object")
        result: Dict = {}
        result["subject"] = data.get("subject")
        # New format may use "aliases" or "alias"
        result["alias"] = data.get("aliases") or data.get("alias") or []
        result["types"] = data.get("types") or []
        result["properties"] = data.get("properties") or {}
        links = data.get("links")
        if isinstance(links, list):
            result["links"] = links
        else:
            result["links"] = []
        return result
    except json.JSONDecodeError:
        pass  # fall back to XML parsing

    # Try XRD (XML) format
    try:
        root = ElementTree.fromstring(doc)
        ns = {}  # use no namespace handling
        # Helper function to find tag possibly with namespace
        def find(tag):
            return root.find(f".//{tag}", ns)

        subject = find("Subject")
        subject_text = subject.text if subject is not None else None

        alias_list = [elem.text for elem in root.findall("Alias")] if root.findall("Alias") else []

        types_list = [elem.text for elem in root.findall("Types/Type")] if root.find("Types") is not None else []

        # Properties
        properties: Dict = {}
        for prop in root.findall("Properties/Property"):
            typ = prop.get("type")
            if typ:
                properties[typ] = prop.text

        # Links
        links = []
        for link in root.findall("Link"):
            href = link.get("href")
            rel = link.get("rel")
            type_ = link.get("type")
            links.append({"href": href, "rel": rel, "type": type_})

        return {
            "subject": subject_text,
            "alias": alias_list,
            "types": types_list,
            "properties": properties,
            "links": links,
        }
    except Exception as exc:
        raise ValueError("Invalid Diaspora webfinger document") from exc

def parse_diaspora_webfinger(document: str) -> Dict:
    """
