                rel_type = elem.attrib.get("rel") or elem.attrib.get("type")
                if rel_type and "security-keys" in rel_type.lower():
                    if elem.text:
                        result["publicKey"] = elem.text.strip()
                        break

        return result
    except ET.ParseError:
        # Malformed XML; return empty dict
        return {}
    except Exception:
        # Any other error
        return {}

