    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    Returns a dictionary with keys: 'subject', 'aliases' (list), and 'links' (list of dicts).
    Raises ValueError if the document cannot be parsed as either format.
    """
    if not isinstance(document, str) or not document.strip():
        raise ValueError("Empty or non-string document")

    # Try JSON first
    try:
        # Import locally to avoid top-level imports
        import json
        data = json.loads(document)
        if not isinstance(data, dict):
            raise ValueError("JSON webfinger is not an object")
        subject = data.get("subject", "")
        aliases = data.get("aliases", [])
        if not isinstance(aliases, list):
            aliases = [aliases]
        links = data.get("links", [])
        if not isinstance(links, list):
            links = [links]
        # Ensure links are dicts with rel, type, href
        parsed_links = []
        for link in links:
            if isinstance(link, dict):
                parsed_links.append({
                    "rel": link.get("rel", ""),
                    "type": link.get("type", ""),
                    "href": link.get("href", ""),
                })
        return {"subject": subject, "aliases": aliases, "links": parsed_links}
    except Exception:
        pass

    # Try XRD (XML) parsing
    try:
        import xml.etree.ElementTree as ET
        # Handle namespace if present
        root = ET.fromstring(document)
        def find_tags(tag):
            # Return all elements matching tag ignoring namespace
            return [e for e in root.iter() if e.tag.split("}")[-1] == tag]

        subject_el = find_tags("Subject")
        subject = subject_el[0].text.strip() if subject_el else ""
        alias_els = find_tags("Alias")
        aliases = [a.text.strip() for a in alias_els if a.text]
        link_els = find_tags("Link")
        parsed_links = []
        for link in link_els:
            parsed_links.append({
                "rel": (link.attrib.get("rel") or "").strip(),
                "type": (link.attrib.get("type") or "").strip(),
                "href": (link.attrib.get("href") or "").strip(),
            })
        return {"subject": subject, "aliases": aliases, "links": parsed_links}
    except Exception as e:
        raise ValueError("Unable to parse webfinger document") from e

