    # Import os module inside function to avoid top-level imports
    os = __import__("os")

    for dir_path in directories:
        try:
            if not os.path.isdir(dir_path):
                # Skip invalid directories
                continue
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if os.path.isfile(full_path):
                    # If a spec_option is provided, filter by it
                    if spec_option:
                        # simple suffix match; use case-insensitive comparison
                        if full_path.lower().endswith(spec_option.lower()):
                            file_list.append(full_path)
