def list_of_file_names(settings_dirs, spec_option):
    """
    List file names from the provided directories that match the given pattern.

    Parameters
    ----------
    settings_dirs : str or iterable of str
        One or more directory paths to search for files.
    spec_option : str, optional
        Pattern to match file names (similar to glob syntax). If omitted or empty, all files are matched.

    Returns
    -------
    list of str
        Sorted list of full file paths that match the pattern. Non-existing or inaccessible directories are silently skipped.
    """
    # Dynamically import required modules without using explicit import statements
    os_module = __import__("os")
    fnmatch_module = __import__("fnmatch")

    # Normalize settings_dirs to a list
    if isinstance(settings_dirs, (str, bytes, os_module.PathLike)):
        dir_list = [settings_dirs]
    else:
        try:
            dir_list = list(settings_dirs)
        except Exception:
            raise TypeError("settings_dirs must be a string or iterable of directory paths")

    # Default pattern if spec_option is falsy
    pattern = spec_option if spec_option else "*"

    matched_files = []

    for d in dir_list:
        # Skip non-existent or non-directory paths
        try:
            if not os_module.path.isdir(d):
                continue
        except Exception:
            continue

        # Scan directory entries
        try:
            for entry in os_module.scandir(d):
                try:
                    if entry.is_file():
                        if fnmatch_module.fnmatch(entry.name, pattern):
                            matched_files.append(entry.path)
                except Exception:
                    # Skip problematic entries
                    continue
        except Exception:
            # Skip any directory that cannot be scanned
            continue

    # Return a deterministic order
    matched_files.sort()
    return matched_files

