    """
    Resolves the include dict directive in the spec files.
    An include directive is represented by a dictionary that contains a single key 'include',
    whose value is either the name of another dictionary within the same parser_dict
    or a file path pointing to a JSON/YAML file that defines the group.
    This method returns a new dictionary with all include directives resolved.
    """
    import json
    import os

    def _resolve(node, visited):
        if not isinstance(node, dict):
            # For non-dict nodes, return as is
            return node
        result = {}
        for key, value in node.items():
            # Detect include directive: a dict containing only an 'include' key
            if (
                isinstance(value, dict)
                and len(value) == 1
                and 'include' in value
            ):
                inc = value['include']
                # Detect circular references
