            raise TypeError("command_name must be a string")

        # The parser for each command is expected to be stored in a dictionary
        # called 'parsers' on the instance.  If it's not present we fall back
        # to an empty dict to avoid AttributeError.
        parsers = getattr(self, "parsers", {})

