        options = []
        try:
            # argparse.ArgumentParser stores actions in the _actions attribute.
            for action in getattr(parser, "_actions", []):
                # Some actions (like subparsers) may not have option_strings.
                opt_strings = getattr(action, "option_strings", [])
                # The help/wikipedia style options are included; filter empty ones.
                for opt in opt_strings:
                    if opt and isinstance(opt, str):
                        options.append(opt)
        except Exception as exc:
            raise RuntimeError(
