        min_val = getattr(self, "min_value", None)
        if min_val is None:
            min_val = getattr(self, "min", None)
        max_val = getattr(self, "max_value", None)
        if max_val is None:
            max_val = getattr(self, "max", None)

        # If there are no bounds defined, nothing to validate.
        if min_val is None and max_val is None:
            return

        def _validate_single(value, key=None):
            """Validate a single numeric value against configured bounds."""
            # Skip None values (often optional arguments).
            if value is None:
                return
            if not isinstance(value, (int, float)):
                name = f" {key!r}" if key is not None else ""
                raise TypeError(f"Argument{ name } must be a numeric type, got {type(value).__name__}")
            if min_val is not None and value < min_val:
                name = f" {key!r}" if key is not None else ""
                raise ValueError(f"Argument{ name } must be >= {min_val}, got {value}")
            if max_val is not None and value > max_val:
                name = f" {key!r}" if key is not None else ""
                raise ValueError(f"Argument{ name } must be <= {max_val}, got {value}")

        try:
            if isinstance(args, dict):
                for k, v in args.items():
                    _validate_single(v, key=k)
            elif isinstance(args, (list, tuple)):
                for idx, v in enumerate(args):
                    _validate_single(v, key=f"index {idx}")
            else:
                raise TypeError("args must be a dict, list, or tuple")
        except Exception as exc:
            # Re-raise the exception preserving the original traceback
            raise type(exc)(f"{exc}") from None

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument names to values")

    for key, val in args.items():
        if val is None:
            # Skip None values – typically optional arguments
            continue

        # Determine the minimum and maximum constraints for this argument
        min_val = None
        max_val = None

        # Check for explicit per-argument min/max dictionaries
        if hasattr(self, 'min_args') and isinstance(self.min_args, dict):
            min_val = self.min_args.get(key)
        if hasattr(self, 'arg_min') and isinstance(self.arg_min, dict):
            min_val = self.arg_min.get(key, min_val)

        if hasattr(self, 'max_args') and isinstance(self.max_args, dict):
            max_val = self.max_args.get(key)
        if hasattr(self, 'arg_max') and isinstance(self.arg_max, dict):
            max_val = self.arg_max.get(key, max_val)

        # Check for a combined limits dictionary, e.g. {'foo': (min, max), ...}
        if hasattr(self, 'arg_limits') and isinstance(self.arg_limits, dict):
            limits = self.arg_limits.get(key)
            if limits:
                if isinstance(limits, (list, tuple)) and len(limits) == 2:
                    # Ensure min_val and max_val are not overridden incorrectly
                    min_val = limits[0] if limits[0] is not None else min_val
                    max_val = limits[1] if limits[1] is not None else max_val
                else:
                    raise ValueError(f"arg_limits entry for '{key}' must be a (min, max) tuple")

        # If we have any constraints, enforce them
        if min_val is not None or max_val is not None:
            try:
                if min_val is not None and val < min_val:
                    raise ValueError(
                        f"Argument '{key}' value {val} is below its minimum allowed "
                        f"value of {min_val}"
                    )
                if max_val is not None and val > max_val:
                    raise ValueError(
                        f"Argument '{key}' value {val} exceeds its maximum allowed "
                        f"value of {max_val}"
                    )
            except TypeError:
                # Raised when val is not comparable to min/max (e.g., string vs int)
                raise TypeError(
                    f"Argument '{key}' with value {val} cannot be compared "
                    f"against defined min/max boundaries"
                )
    return True

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
        """Build the complex argument type

        :param subcommand: the command name
        :param type_name: the complex type name
        :param option_name: the option name
        :param spec_option: option's specifications
        :return: the complex type instance
        """
        # Basic input validation
        if not isinstance(subcommand, str) or not subcommand:
            raise ValueError("subcommand must be a non-empty string")
        if not isinstance(type_name, str) or not type_name:
            raise ValueError("type_name must be a non-empty string")
        if not isinstance(option_name, str) or not option_name:
            raise ValueError("option_name must be a non-empty string")
        if not isinstance(spec_option, dict):
            raise TypeError("spec_option must be a dictionary")

        import re

        # Retrieve optional specification fields
        # allow both 'type' and 'convert' keys for user convenience
        conv = spec_option.get('type', spec_option.get('convert'))
        pattern = spec_option.get('pattern')
        choices = spec_option.get('choices')
        default = spec_option.get('default')

        def _validate(value):
            """Inner validation function for the complex type."""
            try:
                # Apply type conversion if requested
                if conv:
                    if conv == 'int':
                        value = int(value)
                    elif conv == 'float':
                        value = float(value)
                    elif conv == 'bool':
                        # Basic string to bool conversion
                        if isinstance(value, bool):
                            pass
                        elif isinstance(value, str):
                            low = value.lower()
                            if low in ('true', '1', 'yes', 'y'):
                                value = True
                            elif low in ('false', '0', 'no', 'n'):
                                value = False
                            else:
                                raise ValueError(f"Invalid boolean value: {value!r}")
                        else:
                            raise ValueError(f"Cannot convert {value!r} to bool")
                    else:
                        # Treat unknown conv as a callable
                        value = conv(value)

                # Validate against a set of allowed choices
                if choices is not None and value not in choices:
                    raise ValueError(f"Value {value!r} not in allowed choices {choices}")

                # Regex pattern matching
                if pattern is not None:
                    if not re.fullmatch(pattern, str(value)):
                        raise ValueError(f"Value {value!r} does not match pattern {pattern!r}")

                return value
            except Exception as exc:
                raise ValueError(
                    f"Failed to validate value {value!r} for option {option_name!r}: {exc}"
                ) from exc

        # Construct a minimal-complex-type representation
        complex_type = {
            'subcommand': subcommand,
            'name': type_name,
            'option': option_name,
            'spec': spec_option,
            'validate': _validate,
            'default': default
        }
        return complex_type

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
        """Build the complex argument type

        :param subcommand: the command name
        :param type_name: the complex type name
        :param option_name: the option name
        :param spec_option: option's specifications
        :return: the complex type instance
        """
        # Basic validation of required parameters
        if not isinstance(subcommand, str) or not subcommand:
            raise ValueError("subcommand must be a non-empty string")
        if not isinstance(type_name, str) or not type_name:
            raise ValueError("type_name must be a non-empty string")
        if not isinstance(option_name, str) or not option_name:
            raise ValueError("option_name must be a non-empty string")

        # Normalize spec_option to a dictionary
        if spec_option is None:
            spec_option = {}
        if not isinstance(spec_option, dict):
            raise TypeError("spec_option must be a dictionary")

        # Define a simple type holder class
        class ComplexArgType:
            def __init__(self, subcmd, t_name, opt_name, spec):
                self.subcommand = subcmd
                self.type_name = t_name
                self.option_name = opt_name
                self.spec_option = spec
                # Copy spec keys as attributes for convenience
                for k, v in spec.items():
                    setattr(self, k, v)

            def __repr__(self):
                return (f"<ComplexArgType name={self.type_name!r} "
                        f"subcommand={self.subcommand!r} option={self.option_name!r}>")

        try:
            instance = ComplexArgType(subcommand, type_name, option_name, spec_option)
        except Exception as exc:
            raise RuntimeError(f"Failed to create complex argument type: {exc}") from exc

        return instance

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                 spec_option):
    """
    Build a complex argument type instance based on the provided specification.

    This method validates the input, dynamically creates a lightweight class
    that represents the complex type, and instantiates it with defaults and
    validation logic. The resulting object provides attribute access for all
    defined fields and performs basic type casting.

    :param subcommand: the command name (string)
    :param type_name: the name of the complex type (string)
    :param option_name: the option name (string)
    :param spec_option: a dictionary where keys are field names and values
                        are dictionaries possibly containing:
                          * 'type': expected type ('int', 'float', 'str',
                                    'bool', 'list', or a callable)
                          * 'default': default value if missing
                          * 'required': bool indicating if the field is
                                        mandatory
                          * 'description': optional description string
    :return: an instance of a dynamically created type that stores the parsed
             fields. Raises ValueError for invalid specifications or input.
    """
    # Basic input validation
    if not isinstance(subcommand, str):
        raise TypeError(f"subcommand must be a string, got {type(subcommand)}")
    if not isinstance(type_name, str):
        raise TypeError(f"type_name must be a string, got {type(type_name)}")
    if not isinstance(option_name, str):
        raise TypeError(f"option_name must be a string, got {type(option_name)}")
    if not isinstance(spec_option, dict):
        raise TypeError(f"spec_option must be a dict, got {type(spec_option)}")

    # Helper for type casting
    def _cast_value(value, cast_type):
        if cast_type is None:
            return value
        if isinstance(cast_type, str):
            try:
                if cast_type == 'int':
                    return int(value)
                if cast_type == 'float':
                    return float(value)
                if cast_type == 'str':
                    return str(value)
                if cast_type == 'bool':
                    if isinstance(value, bool):
                        return value
                    if isinstance(value, str):
                        lowered = value.lower()
                        if lowered in ('true', '1', 'yes', 'y'):
                            return True
                        if lowered in ('false', '0', 'no', 'n'):
                            return False
                    # fallback numeric check
                    return bool(int(value))
                if cast_type == 'list':
                    if isinstance(value, list):
                        return value
                    if isinstance(value, str):
                        return [item.strip() for item in value.split(',')]
                    return list(value)
            except Exception as exc:
                raise ValueError(f"Failed to cast value '{value}' to {cast_type!r}: {exc}") from exc
        if callable(cast_type):
            try:
                return cast_type(value)
            except Exception as exc:
                raise ValueError(f"Callable {cast_type!r} failed on value '{value}': {exc}") from exc
        raise TypeError(f"Unsupported cast_type: {cast_type!r}")

    # Construct the field metadata
    fields_meta = {}
    required_fields = set()
    for field_name, field_spec in spec_option.items():
        if not isinstance(field_name, str):
            raise TypeError(f"Field name must be a string, got {type(field_name)}")
        if not isinstance(field_spec, dict):
            raise TypeError(f"Specification for field '{field_name}' must be a dict, got {type(field_spec)}")

        field_type = field_spec.get('type')
        default = field_spec.get('default')
        required = bool(field_spec.get('required', False))

        fields_meta[field_name] = {
            'type': field_type,
            'default': default,
            'required': required,
            'description': field_spec.get('description')
        }
        if required:
            required_fields.add(field_name)

    # Dynamically create the complex type class
    class_name = type_name or f"ComplexArg_{subcommand}_{option_name}"
    bases = (object,)

    def __init__(self, **kwargs):
        missing = required_fields - kwargs.keys()
        if missing:
            raise ValueError(f"Missing required fields for {class_name}: {sorted(missing)}")
        # Set attributes with casting and defaults
        for fname, meta in fields_meta.items():
            if fname in kwargs:
                val = kwargs[fname]
            else:
                val = meta['default']
            if val is None and meta['required']:
                raise ValueError(f"Required field '{fname}' cannot be None")
            casted = _cast_value(val, meta['type'])
            setattr(self, fname, casted)
        # Store metadata
        self._subcommand = subcommand
        self._option_name = option_name

    def __repr__(self):
        attrs = ', '.join(f"{k}={getattr(self, k)!r}" for k in fields_meta.keys())
        return f"<{class_name} {attrs}>"

    # Build the class dict
    class_dict = {
        '__init__': __init__,
        '__repr__': __repr__,
        '_subcommand': subcommand,
        '_option_name': option_name,
    }

    ComplexType = type(class_name, bases, class_dict)

    # Return an instance with defaults (if desired)
    # User can pass values when constructing
    return ComplexType()

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
        """Build the complex argument type

        :param subcommand: the command name
        :param type_name: the complex type name
        :param option_name: the option name
        :param spec_option: option's specifications
        :return: the complex type instance
        """
        try:
            # Validate basic inputs
            if not isinstance(subcommand, str):
                raise TypeError("subcommand must be a string")
            if not isinstance(type_name, str) or not type_name:
                raise ValueError("type_name must be a non‑empty string")
            if not isinstance(option_name, str) or not option_name:
                raise ValueError("option_name must be a non‑empty string")

            # Normalize spec_option into a dictionary
            if spec_option is None:
                spec_dict = {}
            elif isinstance(spec_option, dict):
                spec_dict = spec_option
            elif isinstance(spec_option, list):
                # Treat list items as key=value or just keys
                spec_dict = {}
                for idx, item in enumerate(spec_option):
                    if isinstance(item, str) and ':' in item:
                        k, v = item.split(':', 1)
                        spec_dict[k.strip()] = v.strip()
                    else:
                        spec_dict[str(idx)] = item
            else:
                # Assume a comma separated string of key:value pairs
                spec_dict = {}
                try:
                    for part in str(spec_option).split(','):
                        part = part.strip()
                        if not part:
                            continue
                        if ':' in part:
                            k, v = part.split(':', 1)
                            spec_dict[k.strip()] = v.strip()
                        else:
                            spec_dict[part] = None
                except Exception:
                    # Fallback to empty dict if parsing fails
                    spec_dict = {}

            # Simple container object for the complex type
            class ComplexArgumentType:
                __slots__ = ("subcommand", "type_name",
                             "option_name", "spec")

                def __init__(self, subcommand, type_name, option_name, spec):
                    self.subcommand = subcommand
                    self.type_name = type_name
                    self.option_name = option_name
                    self.spec = spec

                def __repr__(self):
                    return (
                        f"<ComplexArgumentType {self.type_name} "
                        f"for '{self.subcommand}' option '{self.option_name}'>"
                    )

            return ComplexArgumentType(subcommand, type_name, option_name, spec_dict)

        except Exception as exc:
            # Re‑raise with a clearer error message
            raise ValueError(
                f"Failed to create complex argument type for '{type_name}': {exc}"
            ) from exc

