def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file.
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Helper to determine if a key/value pair is a control argument.
    def is_control(k):
        if k is None:
            return False
        # Known control prefixes / keyword patterns
        prefixes = ("control_", "ctrl_")
        special_keys = {"debug", "verbose", "dry_run", "force", "quiet", "output"}
        k_str = str(k)
        return k_str.startswith(prefixes) or k_str.lower() in special_keys

    # Helper to determine if a key/value pair is a custom argument
    def is_custom(k):
        if k is None:
            return False
        return str(k).startswith("custom_")

    if args is None:
        return control_args, nested_args

    # Normalize args to a list for safe iteration
    if not isinstance(args, (list, tuple)):
        try:
            args = list(args)
        except Exception:
            # If args cannot be iterated, treat as no args
            return control_args, nested_args

    for item in args:
        # Skip None entries
        if item is None:
            continue

        # Handle dict items: use key/value pairs
        if isinstance(item, dict):
            for k, v in item.items():
                if is_control(k):
                    control_args[str(k)] = v
                elif is_custom(k):
                    nested_args[str(k)] = v
                else:
                    nested_args[str(k)] = v
            continue

        # Handle tuple/list items of length >= 2: treat as (key, value)
        if isinstance(item, (list, tuple)) and len(item) >= 2:
            k, v = item[0], item[1]
            if is_control(k):
                control_args[str(k)] = v
            elif is_custom(k):
                nested_args[str(k)] = v
            else:
                nested_args[str(k)] = v
            # If there are more than two elements, ignore extras
            continue

        # If item is a simple string or other non-key/value type,
        # treat it as a flag with None value
        if isinstance(item, str):
            # We'll interpret it as a flag if it is known control,
            # otherwise as a nested flag with None
            if is_control(item):
                control_args[item] = None
            else:
                nested_args[item] = None
        else:
            # Unsupported type, ignore it
            continue

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars (string, list, or dict)
    :return: Updated dictionary
    """
    if vars_dict is None:
        vars_dict = {}
    if not extra_vars:
        return vars_dict

    def _add_kv(k, v, dest):
        dest[k] = v

    def _process_item(item, dest):
        # Handles a single string or dict entry
        if isinstance(item, dict):
            dest.update(item)
            return
        if not isinstance(item, str):
            # Unsupported type; ignore
            return
        # Convert comma separated string into items, also split on whitespace
        # Preserve quoted values by naive split; this is a best effort
        parts = []
        current = ""
        in_quote = False
        quote_char = '"'
        for ch in item:
            if ch in ('"', "'"):
                if in_quote:
                    if ch == quote_char:
                        in_quote = False
                    else:
                        current += ch
                else:
                    in_quote = True
                    quote_char = ch
            elif ch == ',' and not in_quote:
                if current:
                    parts.append(current)
                    current = ""
            elif ch.isspace() and not in_quote:
                if current:
                    parts.append(current)
                    current = ""
            else:
                current += ch
        if current:
            parts.append(current)

        for part in parts:
            if '=' in part:
                key, val = part.split('=', 1)
            elif ':' in part:
                key, val = part.split(':', 1)
            else:
                continue
            _add_kv(key.strip(), val.strip(), dest)

    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
    elif isinstance(extra_vars, (list, tuple)):
        for elem in extra_vars:
            _process_item(elem, vars_dict)
    else:
        _process_item(extra_vars, vars_dict)

    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``.

        :param vars_dict: Dictionary to merge extra-vars into.
        :param extra_vars: List of extra-vars or dictionary.
        :returns: Updated dictionary.
        """
        # Ensure vars_dict is a dictionary
        if not isinstance(vars_dict, dict):
            raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")

        # Nothing to merge
        if extra_vars is None:
            return vars_dict

        # If extra_vars is a dict, simply update
        if isinstance(extra_vars, dict):
            try:
                vars_dict.update(extra_vars)
            except Exception:
                # In case the dict contains non-serializable items
                for k, v in extra_vars.items():
                    vars_dict[k] = v
            return vars_dict

        # When extra_vars is a list-like iterable
        try:
            iterable = list(extra_vars)
        except TypeError:
            # Not iterable; attempt to convert it to a single-item list
            iterable = [extra_vars]

        for item in iterable:
            # Accept key-value tuples directly
            if isinstance(item, tuple) and len(item) == 2:
                key, value = item
            # Accept "key=value" string format
            elif isinstance(item, str) and '=' in item:
                key, value = item.split('=', 1)
            # Accept dict items (merge recursively)
            elif isinstance(item, dict):
                vars_dict.update(item)
                continue
            else:
                # Unsupported format; skip or raise
                continue

            # Parse the value to a Python literal if possible
            try:
                import ast
                parsed_value = ast.literal_eval(value)
                vars_dict[key] = parsed_value
            except Exception:
                # Leave as string if parsing fails
                vars_dict[key] = value

        return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object representing the active workspace.
    :param ir_plugin: An InfraredPlugin object of the current plugin.
    :param playbook_path: The path to the playbook to invoke.
    :param verbose: Ansible verbosity level (integer 0-5). If None, no verbosity flag is added.
    :param extra_vars: dict of variables to pass to Ansible as --extra-vars.
    :param ansible_args: dict of additional ansible-playbook arguments to pass directly to the CLI.
    :returns: subprocess.CompletedProcess instance containing the execution results.
    :raises FileNotFoundError: If the specified playbook does not exist.
    :raises RuntimeError: If an invalid verbosity level is provided or the command fails.
    """
    import subprocess
    import json
    import os
    from pathlib import Path

    # Validate the playbook path
    playbook = Path(playbook_path)
    if not playbook.is_file():
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    # Base command
    cmd = ["ansible-playbook", str(playbook)]

    # Handle ansible_args: dict where key is flag, value is optional argument
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dictionary")
        for key, value in ansible_args.items():
            if not isinstance(key, str):
                raise TypeError("ansible_args keys must be strings")
            # Ensure flag starts with '--' or '-'
            if not key.startswith("-"):
                key = f"--{key}"
            cmd.append(key)
            if value is not None:
                # Support list/tuple values by converting to a space-separated string
                if isinstance(value, (list, tuple)):
                    value = " ".join(map(str, value))
                cmd.append(str(value))

    # Add verbosity
    if verbose is not None:
        try:
            level = int(verbose)
        except Exception:
            raise RuntimeError(f"Invalid verbosity level: {verbose}")
        if level < 0 or level > 5:
            raise RuntimeError("Verbosity level must be between 0 and 5")
        if level > 0:
            cmd.append("-" + "v" * level)

    # Add extra_vars as JSON string
    if extra_vars is not None:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dictionary")
        try:
            json_str = json.dumps(extra_vars)
        except Exception as e:
            raise RuntimeError(f"Failed to serialize extra_vars: {e}")
        cmd.extend(["--extra-vars", json_str])

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            cwd=str(ir_workspace.path if hasattr(ir_workspace, "path") else os.getcwd()),
            capture_output=True,
            text=True,
            check=False,
        )
    except FileNotFoundError:
        raise RuntimeError("ansible-playbook command not found. Ensure Ansible is installed and in PATH.")
    except Exception as e:
        raise RuntimeError(f"An error occurred while executing ansible-playbook: {e}")

    # Log output if verbose
    if verbose:
        print(result.stdout)
        if result.stderr:
            print(result.stderr, file=sys.stderr)

    if result.returncode != 0:
        raise RuntimeError(
            f"ansible-playbook failed with exit code {result.returncode}.\n"
            f"stdout: {result.stdout}\n"
            f"stderr: {result.stderr}"
        )

    return result

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.
    """
    import os
    import subprocess
    import json
    # Helper for logging
    def _log(level, message):
        if hasattr(ir_plugin, 'log'):
            try:
                ir_plugin.log(level, message)
            except TypeError:
                # If log expects positional only
                ir_plugin.log(message)
        elif hasattr(ir_plugin, f"log_{level}") and callable(getattr(ir_plugin, f"log_{level}")):
            getattr(ir_plugin, f"log_{level}")(message)
        else:
            print(f"{level.upper()}: {message}")

    # Build base command
    cmd = ["ansible-playbook"]

    # Verbosity
    if verbose is not None:
        try:
            lvl = int(verbose)
            if lvl > 0:
                cmd.append("-" + "v" * lvl)
        except Exception:
            # Treat as simple '-v'
            cmd.append("-v")

    # Extra vars
    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise ValueError("extra_vars must be a dict")
        json_vars = json.dumps(extra_vars, separators=(",", ":"))
        cmd.extend(["-e", json_vars])

    # Additional Ansible arguments
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise ValueError("ansible_args must be a dict")
        for key, value in ansible_args.items():
            if isinstance(value, bool):
                if value:
                    cmd.append(f"--{key}")
            else:
                cmd.append(f"--{key}={value}")

    # Resolve playbook path relative to workspace if possible
    if hasattr(ir_workspace, "root"):
        playbook_abs = os.path.join(ir_workspace.root, playbook_path)
    else:
        playbook_abs = playbook_path

    if not os.path.isfile(playbook_abs):
        raise FileNotFoundError(f"Playbook not found: {playbook_abs}")

    cmd.append(playbook_abs)

    _log("debug", f"Executing command: {' '.join(cmd)}")

    try:
        result = subprocess.run(
            cmd, capture_output=True, text=True, check=True
        )
        _log("info", f"Ansible playbook completed with return code {result.returncode}")
        return result
    except FileNotFoundError:
        _log("error", "ansible-playbook command not found. Make sure Ansible is installed.")
        raise
    except subprocess.CalledProcessError as e:
        _log("error", f"Ansible playbook failed with return code {e.returncode}")
        _log("error", f"Stdout: {e.stdout}")
        _log("error", f"Stderr: {e.stderr}")
        raise
    except Exception as exc:
        _log("error", f"Unexpected error: {exc}")
        raise

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import os
    import json
    import shlex
    from subprocess import run, CalledProcessError, PIPE

    # Basic validation
    if not playbook_path:
        raise ValueError("playbook_path must be provided")
    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook '{playbook_path}' not found")

    # Build command list
    cmd = ["ansible-playbook"]

    # Add custom ansible-playbook arguments
    if ansible_args:
        for key, value in ansible_args.items():
            if isinstance(value, bool):
                if value:
                    cmd.append(f"--{key}")
            else:
                cmd.append(f"--{key}={shlex.quote(str(value))}")

    # Add verbosity
    if verbose is not None:
        try:
            vlevel = int(verbose)
            if vlevel > 0:
                vflag = "-" + "v" * min(vlevel, 3)
                cmd.append(vflag)
        except ValueError:
            pass  # ignore non-integer verbosity

    # Add extra-vars
    if extra_vars:
        try:
            json_vars = json.dumps(extra_vars, separators=(",", ":"))
        except (TypeError, ValueError) as exc:
            raise ValueError(f"extra_vars must be JSON serializable: {exc}") from exc
        cmd.extend(["--extra-vars", json_vars])

    # Append the playbook path
    cmd.append(playbook_path)

    # Determine working directory (prefer workspace root if available)
    cwd = None
    if ir_workspace is not None:
        try:
            cwd = getattr(ir_workspace, "root", None)
        except Exception:
            cwd = None

    # Execute the command
    try:
        result = run(
            cmd,
            cwd=cwd,
            text=True,
            capture_output=True,
            check=True,
            shell=False,
        )
        # Send output to plugin logger if available
        if ir_plugin is not None:
            try:
                out = getattr(ir_plugin, "log", None)
                if callable(out):
                    out(result.stdout)
            except Exception:
                pass
        return result.stdout
    except CalledProcessError as exc:
        if ir_plugin is not None:
            try:
                err = getattr(ir_plugin, "log", None)
                if callable(err):
                    err(exc.stderr)
            except Exception:
                pass
        raise RuntimeError(
            f"ansible-playbook failed (exit {exc.returncode}): {exc.stderr}"
        ) from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to run ansible-playbook: {exc}") from exc

