def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts argument values to the types expected by the parser, modifying values_dict in-place.

    The class should provide a mapping `self.arg_type_map` with the following structure:
        {
            "parser_name": {
                "arg_name": expected_type,   # e.g. int, float, bool, list, str
                ...
            },
            ...
        }
    If an argument is not present in the mapping, it will be left unchanged.

    Parameters
    ----------
    parser_name : str
        The name of the parser (e.g., 'main', 'virsh', 'ospd').
    values_dict : dict
        Dictionary mapping argument names to string values. The values are mutated in-place.

    Returns
    -------
    None
    """
    # Retrieve the expected type mapping for the parser, if available
    type_map = getattr(self, 'arg_type_map', {}).get(parser_name, {})
    if not type_map:
        # No type information; nothing to convert
        return

    for arg, expected_type in type_map.items():
        if arg not in values_dict:
            continue

        value = values_dict[arg]
        # Skip if already not a string or is None
        if not isinstance(value, str) or value is None:
            continue

        try:
            if expected_type is str:
                # No conversion needed, but ensure it's a plain string
                values_dict[arg] = str(value)
            elif expected_type is int:
                values_dict[arg] = int(value)
            elif expected_type is float:
                values_dict[arg] = float(value)
            elif expected_type is bool:
                lower = value.lower()
                if lower in ('true', '1', 'yes', 'y'):
                    values_dict[arg] = True
                elif lower in ('false', '0', 'no', 'n'):
                    values_dict[arg] = False
                else:
                    # Unable to parse boolean, keep original string
                    pass
            elif expected_type is list:
                # Assume comma-separated values; strip whitespace
                if value.strip() == '':
                    values_dict[arg] = []
                else:
                    parts = [p.strip() for p in value.split(',')]
                    values_dict[arg] = parts
            elif expected_type is set:
                if value.strip() == '':
                    values_dict[arg] = set()
                else:
                    values_dict[arg] = {p.strip() for p in value.split(',')}
            else:
                # Attempt generic conversion using the type constructor
                values_dict[arg] = expected_type(value)
        except Exception:
            # On any conversion error, leave the original string value
            pass

def _convert_non_cli_args(self, parser_name, values_dict):
        """
        Casts arguments to correct types by modifying values_dict in place.

        By default all the values are strings. The helper attempts to cast
        each string value to int, float or bool if it looks like such
        a literal.  The conversion is performed only for entries whose
        value is a non-empty string; otherwise the original value is
        preserved.  This method is safe to call on arbitrary dictionaries
        and does not modify the dictionary keys.

        Parameters
        ----------
        parser_name : str
            The command name (for possible future use).  Currently unused
            but kept for compatibility with the original interface.
        values_dict : dict
            Dictionary mapping argument names to string values.  The values
            will be overwritten if conversions succeed.

        Returns
        -------
        None
        """
        # Define helper to convert a single string
        def _convert_value(val: str):
            val_str = val.strip()
            # Empty string keeps as is
            if val_str == "":
                return val_str
            # Boolean conversion
            low = val_str.lower()
            if low in {"true", "false", "1", "0", "yes", "no"}:
                return low in {"true", "1", "yes"}
            # Integer conversion
            if val_str.isdigit() or (val_str.startswith("-") and val_str[1:].isdigit()):
                try:
                    return int(val_str)
                except ValueError:
                    pass
            # Float conversion
            try:
                # Reject strings like '1e2' if not desired; keep for now
                f = float(val_str)
                # Avoid converting integers represented as floats (e.g., '3.0')
                if f.is_integer():
                    return int(f)
                return f
            except ValueError:
                pass
            # Default: return original
            return val_str

        if not isinstance(values_dict, dict):
            raise TypeError("values_dict must be a dict")
        for key in list(values_dict.keys()):
            val = values_dict[key]
            if isinstance(val, str):
                try:
                    values_dict[key] = _convert_value(val)
                except Exception:
                    # In case of unexpected errors, keep original string
                    pass
            else:
                # If it's not a string we leave it untouched
                continue

def _convert_non_cli_args(self, parser_name, values_dict):
        """
        Casts arguments to correct types by modifying values_dict in place.
        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict with arguments
        """
        # Resolve a mapping that defines expected types for arguments.
        # Accept several naming conventions for this attribute.
        type_map = None
        for attr in [
            f"{parser_name.upper()}_ARGS_TYPES",
            f"{parser_name.upper()}_ARGS_TYPE",
            f"{parser_name}_ARGS_TYPES",
            f"{parser_name}_ARGS_TYPE",
        ]:
            if hasattr(self, attr):
                type_map = getattr(self, attr)
                break

        if not isinstance(type_map, dict):
            # No type mapping defined; nothing to cast.
            return

        # Helper to perform casting.
        def _cast(value, target_type):
            try:
                if target_type is bool:
                    if isinstance(value, str):
                        low = value.lower()
                        if low in ("true", "yes", "1"):
                            return True
                        if low in ("false", "no", "0"):
                            return False
                        # Try numeric interpretation
                        return bool(int(value))
                    return bool(value)
                if target_type is int:
                    return int(value)
                if target_type is float:
                    return float(value)
                if target_type is list:
                    if isinstance(value, str):
                        # Split by commas and strip.
                        return [v.strip() for v in value.split(",") if v.strip()]
                    return list(value)
                if target_type is dict:
                    import json
                    if isinstance(value, str):
                        return json.loads(value)
                    return dict(value)
                # For any other callable, try to invoke.
                return target_type(value)
            except Exception:
                # On failure return the original value.
                return value

        # Iterate over the provided arguments and cast them.
        for key, val in list(values_dict.items()):
            expected_type = type_map.get(key)
            if expected_type is None:
                continue
            values_dict[key] = _cast(val, expected_type)

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict in place.

        The conversion is performed generically: string values are examined and,
        if possible, converted to int, float, bool or a list of such items.
        Handles errors silently by leaving the original string.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc (currently unused).
        :param values_dict: The dict of arguments to convert.
        """
        def _convert_value(val):
            """Attempt to convert a string to int/float/bool; otherwise return the original."""
            # Try integer conversion
            try:
                if val.startswith('0') and len(val) > 1:
                    # Avoid octal-like ambiguity; treat as string
                    pass
                return int(val)
            except (ValueError, TypeError):
                pass
            # Try float conversion
            try:
                return float(val)
            except (ValueError, TypeError):
                pass
            # Try boolean conversion
            lowered = val.strip().lower()
            if lowered == 'true':
                return True
            if lowered == 'false':
                return False
            # Return string unchanged
            return val

        # Convert each key/value in the dict
        for key, val in list(values_dict.items()):
            if isinstance(val, str):
                cleaned = val.strip()
                # List detection
                if ',' in cleaned:
                    items = [item.strip() for item in cleaned.split(',')]
                    converted_items = [_convert_value(item) for item in items]
                    values_dict[key] = converted_items
                else:
                    values_dict[key] = _convert_value(cleaned)
            elif isinstance(val, list):
                # Convert each string element in a list if needed
                new_list = []
                for item in val:
                    if isinstance(item, str):
                        new_list.append(_convert_value(item.strip()))
                    else:
                        new_list.append(item)
                values_dict[key] = new_list
            else:
                # Leave non-string, non-list values unchanged
                continue
        return None  # function modifies values_dict in place only.

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Ensure we have a mapping to iterate over; do nothing if input is not a dict
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dict, got %r" % type(values_dict).__name__)

    for key in list(values_dict):
        val = values_dict[key]
        # Only attempt conversion for string values
        if not isinstance(val, str):
            continue
        stripped = val.strip()
        if stripped == "":
            continue

        lower_val = stripped.lower()
        if lower_val in ("true", "yes", "1"):
            values_dict[key] = True
            continue
        if lower_val in ("false", "no", "0"):
            values_dict[key] = False
            continue

        # Attempt numeric conversion
        try:
            # use float first if decimal point or scientific notation present
            if "." in stripped or "e" in lower_val:
                numeric = float(stripped)
            else:
                numeric = int(stripped)
            values_dict[key] = numeric
        except ValueError:
            # Leave the value unchanged if conversion fails
            pass

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Helper functions
    def _flatten(prefix, obj, out):
        if isinstance(obj, dict):
            for k, v in obj.items():
                key = f"{prefix}.{k}" if prefix else k
                _flatten(key, v, out)
        elif isinstance(obj, list):
            for idx, item in enumerate(obj):
                key = f"{prefix}[{idx}]" if prefix else f"[{idx}]"
                _flatten(key, item, out)
        else:
            out[prefix] = obj

    # Validate plugin_dir
    if not isinstance(plugin_dir, (str, bytes, os.PathLike)):
        raise TypeError(f"plugin_dir must be a string or PathLike object, got {type(plugin_dir)}")
    plugin_dir = os.fspath(plugin_dir)

    if not os.path.isdir(plugin_dir):
        raise ValueError(f"plugin_dir '{plugin_dir}' is not a directory or does not exist")

    # Find spec file (yaml or json)
    spec_path = None
    for fname in ("plugin.yaml", "plugin.yml", "plugin.json"):
        potential = os.path.join(plugin_dir, fname)
        if os.path.isfile(potential):
            spec_path = potential
            break

    if spec_path is None:
        raise FileNotFoundError(f"No plugin spec file found in '{plugin_dir}' (expected plugin.yaml, plugin.yml, or plugin.json)")

    # Load spec
    spec_data = None
    try:
        if spec_path.lower().endswith(".json"):
            with open(spec_path, "r", encoding="utf-8") as f:
                spec_data = json.load(f)
        else:
            import yaml  # local import to avoid unnecessary dependency
            with open(spec_path, "r", encoding="utf-8") as f:
                spec_data = yaml.safe_load(f)
    except Exception as e:
        raise ValueError(f"Failed to load spec file '{spec_path}': {e}") from e

    if not isinstance(spec_data, (dict, list)):
        raise ValueError(f"Spec file '{spec_path}' does not contain a mapping or list at the top level")

    # Flatten spec
    flat_dict = {}
    try:
        # If top level is a list, use a placeholder key
        if isinstance(spec_data, list):
            _flatten("[0]", spec_data[0] if spec_data else {}, flat_dict)
            for idx in range(1, len(spec_data)):
                _flatten(f"[{idx}]", spec_data[idx], flat_dict)
        else:
            _flatten("", spec_data, flat_dict)
    except Exception as e:
        raise ValueError(f"Error while flattening spec: {e}") from e

    return flat_dict

