    spec_file = plugin_path / "plugin.json"
    if not spec_file.is_file():
        raise FileNotFoundError(f"Spec file 'plugin.json' not found in {plugin_dir}")

    try:
        with spec_file.open("r", encoding="utf-8") as f:
            spec_data = json.load(f)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON in {spec_file}: {e}") from e

    flat_dict = {}

    def _flatten(obj, prefix=""):
        if isinstance(obj, dict):
            for k, v in obj.items():
                _flatten(v, f"{prefix}.{k}" if prefix else k)
        elif isinstance(obj, list):
            for idx, item in enumerate(obj):
                _flatten(item, f"{prefix}.{idx}" if prefix else str(idx))
        else:
            flat_dict[prefix] = obj

    _flatten(spec_data)
    return flat_dict

