def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec.

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Helper function to flatten nested dictionaries (and lists)
    def _flatten(current, parent_key=""):
        flat = {}
        if isinstance(current, dict):
            for key, value in current.items():
                new_key = f"{parent_key}.{key}" if parent_key else key
                flat.update(_flatten(value, new_key))
        elif isinstance(current, list):
            for idx, item in enumerate(current):
                new_key = f"{parent_key}[{idx}]" if parent_key else f"[{idx}]"
                flat.update(_flatten(item, new_key))
        else:
            flat[parent_key] = current
        return flat

    # Validate plugin_dir
    if not isinstance(plugin_dir, str):
        raise TypeError(f"plugin_dir must be a string path, got {type(plugin_dir)}")
    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Plugin directory not found: {plugin_dir}")

    # Find spec file
    spec_file_candidates = [
        os.path.join(plugin_dir, "plugin.yaml"),
        os.path.join(plugin_dir, "plugin.yml"),
        os.path.join(plugin_dir, "plugin.json")
    ]
    spec_file = None
    for candidate in spec_file_candidates:
        if os.path.isfile(candidate):
            spec_file = candidate
            break
    if spec_file is None:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    # Load spec
    try:
        with open(spec_file, "r", encoding="utf-8") as f:
            if spec_file.lower().endswith((".yaml", ".yml")):
                import yaml
                try:
                    spec_data = yaml.safe_load(f)
                except Exception as e:
                    raise ValueError(f"Failed to parse YAML spec file '{spec_file}': {e}") from e
            else:  # JSON
                try:
                    spec_data = json.load(f)
                except Exception as e:
                    raise ValueError(f"Failed to parse JSON spec file '{spec_file}': {e}") from e
    except OSError as e:
        raise IOError(f"Error reading spec file '{spec_file}': {e}") from e

    # Ensure spec data is a dictionary (or list)
    if not isinstance(spec_data, (dict, list)):
        raise ValueError(f"Spec file '{spec_file}' does not contain a dict or list at its root")

    # Flatten and return
    return _flatten(spec_data)

