        os.environ[env_var] = config_path

def strip_root(path, root):
    """
    Remove root from path, throw exception on failure.
    """
    # Validate inputs
    if not isinstance(path, str):
        raise TypeError(f"path must be a string, got {type(path).__name__}")
    if not isinstance(root, str):
        raise TypeError(f"root must be a string, got {type(root).__name__}")
    if root == "":
        raise ValueError("root cannot be an empty string")

    # Ensure root ends with a path separator if it is not the whole path
    # This avoids accidental partial matches (e.g., root="C:/foo" not matching path="C:/foobar/file")
    path_separators = {"\\", "/"}
    # Normalize separators for consistent matching
    norm_path = path
    norm_root = root

    # Determine if path already uses a separator after the root
    # If root does not end with a separator, we need to ensure the match includes a separator
    suffix_ok = False
    if len(path) > len(root):
        if (path[len(root):len(root)+1] in path_separators):
            suffix_ok = True

    # Decide whether the root should be treated as a prefix
    if not path.startswith(root) and not (prefix := path.split(root)[0]) == "":
        # try reverse: root is lowercased? windows case-insensitive?
        # Use case-insensitive matching on Windows-like paths
        # We'll compare after normalizing to lower-case
        if path.lower().startswith(root.lower()):
            # We consider it a match but keep original case
            norm_root = root
            norm_path = path
        else:
            raise ValueError(f"root '{root}' is not a prefix of path '{path}'")

    # Remove the root from the start of the path
    if path.startswith(root):
        relative = path[len(root):]
    elif path.lower().startswith(root.lower()):
        relative = path[len(root):]
    else:
        raise ValueError(f"root '{root}' cannot be stripped from path '{path}'")

    # Strip leading separator if present
    if relative and relative[0] in path_separators:
        relative = relative[1:]

    return relative
